window.__Q=window.__Q||{};window.__Q["clin/7/A1"]=[{"q":"舌体主要来源于","o":["奇结节","侧舌突","联合突","下颌突","甲状舌管"],"a":1,"e":"舌体主要由左右侧舌突（侧舌膨大）融合形成，构成舌的大部分；奇结节只演化为舌盲孔前方舌体的小部分，联合突则发育为舌根。"},{"q":"中动脉内膜的组成包括","o":["内皮、内皮下层、内弹性膜","内皮、内皮下层、内膜下层","内皮、基膜、内弹性膜","内皮、基膜、内皮下层","内皮、内膜下层、内弹性膜"],"a":0,"e":"中动脉内膜由内皮、内皮下层和内弹性膜三层构成，与中膜交界处有1～2层明显的内弹性膜；内膜下层只出现于心内膜。"},{"q":"味蕾不存在于","o":["轮廓乳头","菌状乳头","丝状乳头","软腭和会厌","咽"],"a":2,"e":"丝状乳头数量最多、遍布舌背，上皮浅层角化，不含味蕾；味蕾见于菌状乳头、轮廓乳头以及软腭、会厌和咽的上皮内。"},{"q":"神经管壁早期分化形成三层，由内向外依次为","o":["室管膜层、套层和边缘层","套层、边缘层和室管膜层","边缘层、室管膜层和套层","边缘层、套层和室管膜层","套层、室管膜层和边缘层"],"a":0,"e":"神经管壁的神经上皮细胞增殖后，由内向外依次分化为室管膜层、套层和边缘层，套层演变为灰质、边缘层演变为白质。"},{"q":"下列无周期性横纹的是","o":["胶原纤维","骨骼肌纤维","网状纤维","心肌纤维","平滑肌纤维"],"a":4,"e":"平滑肌纤维无横纹，呈长梭形，核居中；横纹只见于骨骼肌和心肌纤维，胶原原纤维本身的周期性横纹属超微结构特征，与肌纤维横纹不同。"},{"q":"胞质含有大量脂滴的细胞位于","o":["垂体远侧部","神经垂体","肾上腺皮质","甲状腺","肾上腺髓质"],"a":2,"e":"肾上腺皮质束状带细胞胞质含大量脂滴，呈泡沫状，HE染色浅；该带最厚，分泌糖皮质激素。"},{"q":"触觉小体分布于","o":["皮肤真皮乳头内","皮肤真皮网织层内","表皮内","真皮血管壁上","皮下组织内"],"a":0,"e":"触觉小体位于真皮乳头内，手指掌侧最多，感受应力刺激参与产生触觉；环层小体位于皮下组织等处，感受压觉和振动觉。"},{"q":"从丘脑进入大脑皮质的神经纤维终末主要分布在","o":["外颗粒层","内颗粒层","内锥体细胞层","多形细胞层","外锥体细胞层"],"a":1,"e":"大脑皮质内颗粒层即第4层，主要接受丘脑特异性传入纤维的终末，是皮质的主要感觉传入层。"},{"q":"人胚第5周，直接通入泄殖腔的管道是","o":["中肾管","前肾管","中肾旁管","输尿管芽","原始直肠"],"a":0,"e":"中肾管由前肾管演变而来，第5周时仍直接开口于泄殖腔；输尿管芽虽起自中肾管末端，其本身并不通入泄殖腔。"},{"q":"胚胎上、下肢芽出现于胚胎发育的","o":["第2周","第3周","第4周","第5周","第6周"],"a":2,"e":"第4周末胚体左右侧体壁先后出现上肢芽与下肢芽，随后肢芽增长变粗，出现两个缩窄环而分为三段。"},{"q":"中肾管的正常发育分化，依赖其管壁细胞表面的","o":["雌激素受体","雄激素受体","孕激素受体","雌激素和孕激素受体","促性腺激素受体"],"a":1,"e":"雄激素经中肾管壁细胞的雄激素受体介导，促使中肾管分化为附睾管、输精管、精囊和射精管；缺乏受体则生殖管道向女性方向发育。"},{"q":"胎儿期左右心房之间的血流方向是从","o":["左心房经第二房间孔至右心房","右心房经卵圆孔、第一房间孔至左心房","左心房经卵圆孔至右心房","右心房经卵圆孔至左心房","左心房经第一房间孔至右心房"],"a":3,"e":"出生前肺循环尚未建立，左心房压力低于右心房，右心房的血液经卵圆孔流入左心房，卵圆孔瓣可阻止血液反向流动。"},{"q":"由成神经胶质细胞分化而来的是","o":["纤维性和原浆性星形胶质细胞","原浆性星形胶质细胞和小胶质细胞","少突胶质细胞和小胶质细胞","室管膜细胞和纤维性星形胶质细胞","纤维性星形胶质细胞和室管膜细胞"],"a":0,"e":"成神经胶质细胞分化为成星形胶质细胞和成少突胶质细胞，前者再分化为纤维性和原浆性星形胶质细胞；小胶质细胞来源于单核细胞。"},{"q":"球旁复合体的组成包括","o":["球旁细胞和致密斑","球外系膜细胞和致密斑","球旁细胞、致密斑和球内系膜细胞","球内系膜细胞和致密斑","球旁细胞、致密斑和球外系膜细胞"],"a":4,"e":"球旁复合体位于肾小体血管极，由球旁细胞、致密斑和球外系膜细胞（极垫细胞）三部分组成，球内系膜细胞不属于该复合体。"},{"q":"人体的结构非常精巧，组织结构特点与其功能发挥密切相关，例如衬覆于心脏、血管和淋巴管腔面的上皮组织，其特点中最利于血液和淋巴液流动的是","o":["细胞为多边形","细胞核位于中央","含核的部分略厚","游离面光滑","细胞间有连接结构"],"a":3,"e":"内皮为衬贴在心血管和淋巴管腔面的单层扁平上皮，其游离面光滑，可减小血流阻力，利于血液和淋巴流动。"},{"q":"以下关于精子形成的描述中，哪—项是错误的","o":["细胞核染色极度浓缩，核变长并移向细胞的一侧形成精子头","高尔基复合体形成顶体覆盖在核的前2/3","中心粒发出9＋2排列的微管，构成鞭毛中心的轴丝","线粒体汇集于轴丝中部的周围，形成线粒体鞘","残余胞质脱落"],"a":3,"e":"线粒体鞘由线粒体呈螺旋状缠绕于尾部中段的轴丝周围形成，位于近细胞核段而非轴丝全长中部，故该描述有误；顶体由高尔基复合体形成，残余胞质最后脱落。"},{"q":"化学突触是","o":["神经元内的细胞器","神经元表面的纤毛","神经元核膜与核周质接触处","神经元之间或神经元与效应细胞之间的细胞连接","神经元合成神经递质的场所"],"a":3,"e":"化学突触是神经元与神经元之间或神经元与效应细胞之间传递信息的细胞连接，由突触前部、突触间隙和突触后部构成。"},{"q":"关于内耳听觉感受器的描述，哪项错误","o":["由毛细胞和支持细胞组成","毛细胞是感受听觉的细胞","螺旋器又称Corti器","位于骨螺旋板上","毛细胞顶部有听毛"],"a":3,"e":"螺旋器位于膜螺旋板即基底膜上，由支持细胞和毛细胞组成，又称Corti器；骨螺旋板只参与构成蜗管下壁的内侧部。"},{"q":"平滑肌纤维内的细肌丝附着于","o":["密体","密斑","小凹","中间丝","粗肌丝"],"a":1,"e":"细肌丝一端附着于密斑或密体，另一端游离并环绕粗肌丝；密斑位于肌膜下，是细肌丝在细胞膜上的主要锚定点。"},{"q":"关于星形胶质细胞的描述，哪项错误","o":["主要起支持和分隔神经元的作用","突起不分轴突和树突","胞质内含有大量胶质丝","仅分布于中枢神经系统的灰质","是体积最大的神经胶质细胞"],"a":3,"e":"星形胶质细胞分纤维性和原浆性两种，分别分布于白质和灰质，故并非仅见于灰质；其体积最大，起支持、分隔神经元和构成血-脑屏障的作用。"},{"q":"图中结构是","o":["微静脉","小静脉","小动脉","中动脉","毛细血管"],"a":3,"e":"官方题库缺失图片"},{"q":"哪一项不是胸腺上皮细胞的功能","o":["形成网状纤维","参与形成胸腺小体","分泌激素","辅助培育T细胞","构成支架"],"a":0,"e":"胸腺上皮细胞构成胸腺支架、参与形成胸腺小体、分泌胸腺素等并辅助培育T细胞；网状纤维由网状细胞产生，不属胸腺上皮细胞的功能。"},{"q":"形成尿道下裂的原因是","o":["尿生殖窦膜破裂","生殖结节腹侧分裂","两侧尿生殖褶闭合不全","窦结节腹侧分裂","左右阴唇阴囊隆起闭合不全"],"a":2,"e":"胚胎期左右尿生殖褶未在腹侧中线完全闭合，尿道开口于阴茎腹侧，即尿道下裂；闭合正常则形成尿道海绵体。"},{"q":"卵巢的间质腺由下列哪种细胞形成","o":["卵泡膜的外层细胞","卵泡周围的结缔组织细胞","卵泡细胞","闭锁次级卵泡的膜细胞","黄体细胞"],"a":3,"e":"次级卵泡或成熟卵泡闭锁时，卵泡膜内层的膜细胞肥大，转变为间质腺细胞，可分泌雄激素并转化为雌激素，故称间质腺。"},{"q":"感受压力觉的神经末梢是","o":["触觉小体","肌梭","环层小体","神经-肌连接","腱梭"],"a":2,"e":"环层小体位于皮下组织、肠系膜和关节囊等处，体积大，中央有圆柱体，感受较强应力，产生压觉和振动觉。"},{"q":"光镜下肾HE染色切片，近曲小管上皮细胞分界不清，是因为","o":["胞质嗜酸性强，染色深","相邻细胞的侧突相互嵌和","细胞排列紧密","细胞膜较薄","刷状缘的存在"],"a":1,"e":"近曲小管上皮细胞侧面伸出许多侧突，与相邻细胞侧突相互嵌合，故光镜下细胞分界不清；其游离面有刷状缘，胞质嗜酸性强。"},{"q":"感受触觉的神经末梢是","o":["帕奇尼小体","迈斯纳小体","肌梭","游离神经末梢","运动终板"],"a":1,"e":"迈斯纳小体即触觉小体，位于真皮乳头内，内有扁平细胞横列，有髓神经纤维末梢盘绕其间，参与产生触觉。"},{"q":"合成和分泌免疫球蛋白的细胞是","o":["巨噬细胞","浆细胞","肥大细胞","嗜碱性粒细胞","嗜酸性粒细胞"],"a":1,"e":"浆细胞由B细胞受抗原刺激后分化而来，胞质含发达粗面内质网，合成并分泌免疫球蛋白即抗体，参与体液免疫应答。"},{"q":"关于T细胞，哪项正确","o":["约占血液中淋巴细胞总数的20%","在胸腺内受抗原刺激后分化成熟","成熟后多随血流迁移到淋巴小结生发中心","细胞表面有特异性抗原受体","参与体液免疫应答"],"a":3,"e":"T细胞表面具有特异性抗原受体，每个细胞只表达一种受体，只对一种抗原应答；T细胞在胸腺内不依赖抗原刺激即分化成熟。"},{"q":"以下哪种是肾皮质的特征性结构","o":["集合管","髓放线","弓形动脉","髓袢","远端小管"],"a":1,"e":"髓放线是肾锥体底呈辐射状伸入皮质的纵行管道束，位于皮质内，与周围皮质迷路共同构成肾小叶，是识别皮质的标志。"},{"q":"窦周隙内没有","o":["贮脂细胞","肝细胞微绒毛","网状纤维","肝巨噬细胞","血浆"],"a":3,"e":"窦周隙位于血窦内皮与肝细胞之间，内含贮脂细胞、肝细胞微绒毛、网状纤维和血浆；肝巨噬细胞定居于肝血窦腔内。"},{"q":"成釉质细胞来源于","o":["外胚层","内胚层","轴旁中胚层","侧中胚层","间充质"],"a":0,"e":"成釉质细胞由成釉器内层分化而来，成釉器源于口腔黏膜上皮，属外胚层；牙本质和牙髓则来自神经嵴来源的间充质。"},{"q":"关于小肠绒毛，哪项错误","o":["含中央乳糜管","有丰富的毛细血管网","扩大了吸收面积","上皮细胞在其顶端脱落","由黏膜和黏膜下层共同突起形成"],"a":4,"e":"小肠绒毛由上皮和固有层向肠腔凸起形成，中轴含中央乳糜管和丰富毛细血管网，可扩大吸收面积；黏膜与黏膜下层共同突起形成的是皱襞。"},{"q":"关于膜蜗管的结构，错误的是","o":["位于耳蜗内，周围充满外淋巴","围绕蜗轴盘旋两圈半，切面呈三角形","顶壁为前庭膜","外侧壁为复层扁平上皮，含血管，称血管纹","底壁上皮增厚形成螺旋器"],"a":3,"e":"膜蜗管外侧壁为含毛细血管的复层上皮，称血管纹，可产生内淋巴；顶壁为前庭膜，底壁为膜螺旋板，其上上皮增厚形成螺旋器。"},{"q":"心内膜垫","o":["发生于动脉干和心球内","是心肌膜增生形成的隆起","背、腹心内膜垫彼此相向生长并融合","将原始心房分隔为左、右心房","参与动脉干的分隔"],"a":2,"e":"心内膜垫由房室管背侧壁和腹侧壁正中的心内膜组织增厚形成，即背、腹心内膜垫，二者相对生长，第6周融合，将房室管分隔为左右两部分。"},{"q":"经两次成熟分裂后，生成4个精子的细胞是","o":["精原细胞","初级精母细胞","次级精母细胞","精子细胞","精子"],"a":1,"e":"初级精母细胞经第一次减数分裂形成2个次级精母细胞，再经第二次减数分裂形成4个精子细胞，变态后成为4个精子。"},{"q":"以下哪种细胞一般不会出现在下图箭头所指的管中","o":["单核细胞","淋巴细胞","中性粒细胞","红细胞","嗜酸性粒细胞"],"a":3,"e":"官方题库缺失图片"},{"q":"关于连续毛细血管的描述，哪项正确","o":["内皮细胞含少量吞饮小泡，内皮细胞间有紧密连接，基膜完整","内皮细胞含许多吞饮小泡，内皮细胞间有紧密连接，基膜完整","内皮细胞含许多吞饮小泡，内皮细胞间有间隙，基膜不完整","内皮细胞含少量吞饮小泡，内皮细胞间有紧密连接，基膜不完整","内皮细胞含少量吞饮小泡，内皮细胞间有间隙，基膜不完整"],"a":1,"e":"连续毛细血管内皮细胞间有紧密连接、基膜完整，胞质含大量质膜小泡即吞饮小泡，是血液与组织间物质交换的主要方式。"},{"q":"中动脉中膜的主要成分是","o":["胶原纤维","弹性纤维","平滑肌纤维","网状纤维","神经纤维"],"a":2,"e":"中动脉中膜最厚，由10～40层环行平滑肌纤维构成，故称肌性动脉；平滑肌纤维间有缝隙连接，利于协同舒缩。"},{"q":"螺旋器的听弦位于","o":["盖膜","前庭膜","膜螺旋板","骨螺旋板","血管膜"],"a":2,"e":"听弦是膜螺旋板即基底膜内呈辐射状排列的纤维束，其长度自蜗底向蜗顶递增，与不同频率声波的共振有关。"},{"q":"与睾丸相邻的中肾小管形成","o":["生精小管","睾丸网","睾丸附件","输出小管","附睾附件"],"a":3,"e":"与睾丸相邻的十余条中肾小管分化为附睾的输出小管；中肾管本身演变为附睾管、输精管、精囊和射精管。"},{"q":"平滑肌纤维有","o":["肌原纤维","肌节","横纹","肌丝","分支"],"a":3,"e":"平滑肌纤维内含粗肌丝、细肌丝和中间丝，无肌原纤维、无肌节、无横纹；细肌丝附着于密斑和密体，粗肌丝无M线。"},{"q":"不属于睾丸间质细胞特点的是","o":["常成群分布","位于血管周围","细胞大，胞质嗜酸性","具有蛋白质分泌细胞的超微结构特点","有丰富的滑面内质网、管状嵴线粒体和脂滴"],"a":3,"e":"睾丸间质细胞属类固醇分泌细胞，胞质嗜酸性，含丰富滑面内质网、管状嵴线粒体和脂滴；蛋白质分泌细胞以粗面内质网发达为特点。"},{"q":"脊髓内分化为内脏传出神经元的成神经细胞位于","o":["基板","翼板","翼板和基板之间","底板和基板之间","顶板和翼板之间"],"a":2,"e":"脊髓侧角的成神经细胞位于基板与翼板之间，其轴突经前根出脊髓，节前纤维终止于交感神经节，属内脏传出神经元。"},{"q":"角质形成细胞之间以（ ）相连","o":["紧密连接","中间连接","桥粒","缝隙连接","突触"],"a":2,"e":"角质形成细胞之间以桥粒相连，桥粒处胞质内的角蛋白丝附着于附着板，使表皮各层细胞连接牢固，耐受摩擦。"},{"q":"关于喉的结构，下列错误的是","o":["喉以软骨为支架，软骨间借韧带、肌肉或关节相连","会厌舌面上皮中有味蕾","声襞膜部的上皮为复层扁平上皮","喉各部的固有层中均有腺体，血供丰富","室襞的上皮为假复层纤毛柱状上皮"],"a":3,"e":"声襞膜部固有层内无腺体，以利于发声时黏膜振动；喉其余各部固有层内有混合腺且血供丰富，故各部均有腺体的说法不成立。"},{"q":"关于平滑肌纤维，哪项错误","o":["肌纤维呈长梭形","单核","细胞核居中","可见横纹","肌纤维收缩时，细胞核可扭曲"],"a":3,"e":"平滑肌纤维无横纹，呈长梭形，单核居中，收缩时核可扭曲；横纹是骨骼肌和心肌纤维的光镜特征。"},{"q":"输卵管的管壁由（ ）组成","o":["上皮、固有层、黏膜肌层","黏膜、肌层、浆膜","黏膜、肌层、纤维膜","黏膜、黏膜下层、肌层、浆膜","黏膜、黏膜下层、肌层、纤维膜"],"a":1,"e":"输卵管管壁由黏膜、肌层和浆膜三层构成，无黏膜下层；黏膜形成纵行分支的皱襞，以壶腹部最发达。"},{"q":"关于晶状体结构的描述，哪项错误","o":["双凸透明体","皮质的前表面有一层立方细胞","晶状体囊由交织成网的胶原纤维组成","中心部的纤维构成晶状体核","无血管，由房水提供营养"],"a":2,"e":"晶状体囊由基膜和胶原原纤维构成，为一层均质薄膜，并非交织成网的胶原纤维；囊内为皮质和晶状体核，无血管。"},{"q":"肝巨噬细胞位于","o":["肝血窦内","窦周隙内","肝板内","门管区内","中央静脉"],"a":0,"e":"肝巨噬细胞即库普弗细胞，定居于肝血窦腔内，其伪足可穿过内皮窗孔伸入窦周隙，由血液单核细胞分化而来。"},{"q":"骨骼肌纤维收缩时，其肌节的变化是","o":["仅I带缩短","仅A带缩短","I带、A带均缩短","仅H带缩短","I带缩短、H带缩短或消失"],"a":4,"e":"骨骼肌纤维收缩时细肌丝向M线滑行，明带即I带缩短，H带变窄或消失，暗带即A带长度不变，肌节缩短。"},{"q":"下列哪项是身体的直线变速运动和静止状态的感受器","o":["螺旋器","壶腹嵴","椭圆囊斑和球囊斑","致密斑","血管纹"],"a":2,"e":"椭圆囊斑和球囊斑合称位觉斑，感受直线变速运动和静止状态；壶腹嵴感受旋转变速运动，螺旋器感受听觉。"},{"q":"能分泌黏液但不含杯状细胞的器官是","o":["胃","小肠","结肠","阑尾","胆囊"],"a":0,"e":"胃黏膜上皮为单层柱状，由表面黏液细胞构成，不含杯状细胞，黏液由其自身分泌；小肠和大肠上皮内均散在大量杯状细胞。"},{"q":"B细胞不具有下列哪项特征","o":["参与淋巴细胞再循环","由脾和淋巴结内的淋巴干细胞增殖分化而成","在抗原刺激下增殖","可分化形成记忆细胞","可转变为产生抗体的浆细胞"],"a":1,"e":"B淋巴细胞在骨髓内发育成熟，并非由脾和淋巴结内的淋巴干细胞分化而来；受抗原刺激后可增殖分化为浆细胞和记忆细胞。"},{"q":"肌梭的主要功能是","o":["感受骨骼肌纤维的伸缩变化","感受肌腱的伸缩变化","感受心肌纤维的伸缩变化","引起平滑肌纤维的伸缩变化","感受肌上皮细胞的伸缩变化"],"a":0,"e":"肌梭为分布于骨骼肌内的梭形本体感受器，梭内肌纤维的张力变化刺激感觉末梢，产生对骨骼肌伸缩状态的感知并调控肌活动。"},{"q":"胆小管的管壁是","o":["单层扁平上皮","单层立方上皮","单层柱状上皮","假复层柱状上皮","肝细胞膜围成"],"a":4,"e":"胆小管是相邻肝细胞胞膜局部凹陷围成的微细管道，管壁即肝细胞膜，无独立上皮，胆汁经此汇入小叶间胆管。"},{"q":"关于小肠的结构特征，错误的是","o":["表面有大量绒毛","有环行皱襞","固有层内有肠腺","黏膜层及黏膜下层有淋巴组织","固有层内有明显的神经丛"],"a":4,"e":"小肠的神经丛有两处，黏膜下神经丛位于黏膜下层，肌间神经丛位于肌层之间，固有层内并无明显的神经丛。"},{"q":"下列哪个结构不分布在皮质迷路内","o":["入球微动脉和出球微动脉","球旁复合体","远端小管直部","致密斑","弓形集合管"],"a":2,"e":"远端小管直部位于髓放线和肾锥体内，与近直小管、细段共同构成髓袢；入球与出球微动脉、致密斑和弓形集合管均见于皮质迷路。"},{"q":"浦肯野细胞分布在","o":["大脑皮质","小脑皮质","脊髓灰质","脊神经节","脑神经节"],"a":1,"e":"浦肯野细胞是小脑皮质唯一的传出神经元，胞体呈梨形，位于浦肯野细胞层，轴突终止于小脑白质内的神经核。"},{"q":"红细胞胞质中主要含有","o":["核蛋白","肌动蛋白","血影蛋白","血红蛋白","白蛋白"],"a":3,"e":"成熟红细胞无核无细胞器，胞质内充满血红蛋白，具有结合并运输氧和二氧化碳的功能，双凹圆盘状有利于气体交换。"},{"q":"心肌闰盘处有","o":["中间连接、桥粒、紧密连接","中间连接、桥粒、缝隙连接","紧密连接、桥粒、缝隙连接","紧密连接、半桥粒、缝隙连接","中间连接、半桥粒、紧密连接"],"a":1,"e":"闰盘位于相邻心肌纤维的连接处，由黏着小带即中间连接、桥粒和缝隙连接构成，缝隙连接使心肌纤维成为功能合胞体。"},{"q":"下列哪种蛋白分子不参与细肌丝的构成","o":["肌球蛋白","肌动蛋白","原肌球蛋白","TnT亚单位","TnC亚单位"],"a":0,"e":"细肌丝由肌动蛋白、原肌球蛋白和肌钙蛋白构成，肌钙蛋白含TnT、TnI、TnC三个亚单位；肌球蛋白是粗肌丝的组成蛋白。"},{"q":"睾丸和卵巢下降过程中，引带连接于","o":["生殖腺尾端与生殖结节之间","生殖腺尾端与阴唇阴囊隆起之间","生殖腺尾端与尿生殖褶之间","生殖腺尾端与阴阜之间","生殖腺尾端与后腹壁下部"],"a":1,"e":"引带为连于生殖腺尾端与阴唇阴囊隆起之间的纤维索，随胚体增长相对缩短，牵引睾丸和卵巢下降。"},{"q":"胆汁进入血液可导致黄疸，其原因是","o":["与胆小管膜通透性增加有关","与肝血窦内皮细胞通透性增加有关","与肝细胞和肝血窦之间的窦周隙有关","与肝血窦内皮细胞间隙增大有关","与肝细胞连接面连接复合体破坏有关"],"a":4,"e":"胆小管周围相邻肝细胞膜形成由紧密连接和桥粒组成的连接复合体，封闭细胞间隙；该复合体破坏后胆汁溢入窦周隙并进入血窦，引起黄疸。"},{"q":"从支气管分支开始，肺泡最早出现于","o":["细支气管","终末细支气管","呼吸性细支气管","肺泡管","肺泡囊"],"a":2,"e":"呼吸性细支气管壁开始出现少量肺泡，是肺呼吸部的起始段；终末细支气管及其以上各段均无肺泡，属肺导气部。"},{"q":"胚体最易受到致畸因子作用而发生畸形的时段为受精后","o":["1～2周","3～5周","3～8周","5～10周","5～12周"],"a":2,"e":"受精后第3～8周为胚期，各器官原基正在形成，细胞增生分化活跃，是致畸敏感期；此前受致畸因子作用多致胚胎死亡而非畸形。"},{"q":"下列哪一项不属于环境致畸因子","o":["生物","物理","化学","药物","染色体异常"],"a":4,"e":"环境致畸因子包括生物性、物理性、致畸药物、化学性及其他因素；染色体畸变和基因突变属遗传因素。"},{"q":"骨骼肌纤维中贮存钙离子的部位是","o":["肌原纤维","肌浆网","横小管","线粒体","肌红蛋白"],"a":1,"e":"骨骼肌纤维的肌浆网发达，纵小管末端膨大为终池，可储存和释放钙离子；横小管只将肌膜的兴奋传入肌纤维深部。"},{"q":"关于小梁网的描述，哪项错误","o":["前方与角膜后界层相连","后方附着于虹膜","由胶原纤维交织形成","胶原纤维表面均有内皮细胞覆盖","与巩膜静脉窦相通"],"a":1,"e":"小梁网前方与角膜后界层相连，后方附着于巩膜突，由覆有内皮细胞的胶原纤维小梁构成，小梁间隙与巩膜静脉窦相通而参与房水回流。"},{"q":"下列哪项不属于胎膜","o":["羊膜","卵黄囊","尿囊","脐带","基蜕膜"],"a":4,"e":"胎膜包括绒毛膜、羊膜、卵黄囊、尿囊和脐带；基蜕膜属母体子宫蜕膜，与丛密绒毛膜共同组成胎盘。"},{"q":"视网膜脱离多发生在","o":["脉络膜和玻璃膜之间","玻璃膜和色素上皮之间","色素上皮和视细胞层之间","视细胞层和内核层之间","内核层和节细胞层之间"],"a":2,"e":"视网膜脱离发生在色素上皮层与视细胞层之间，即视杯内、外两层相贴处；此处为潜在间隙，两层分离即形成脱离。"},{"q":"疏松结缔组织中最主要的细胞是","o":["巨噬细胞","肥大细胞","浆细胞","脂肪细胞","成纤维细胞"],"a":4,"e":"成纤维细胞是疏松结缔组织中数目最多、最主要的细胞，功能活跃时合成胶原纤维、弹性纤维和基质；功能静止时称纤维细胞。"},{"q":"输尿管芽可演变为","o":["肾小囊","肾小体","细段","集合小管","近端小管"],"a":3,"e":"输尿管芽伸长后其主干分化为输尿管，末端反复分支形成肾盂、肾盏和集合管；肾小体和肾小管则由生后肾组织分化。"},{"q":"神经元尼氏体分布在","o":["胞体和轴突内","树突和胞体内","树突和轴突内","脂褐素内","细胞核内"],"a":1,"e":"尼氏体由粗面内质网和游离核糖体构成，分布于神经元胞体和树突内，轴丘与轴突内无尼氏体，故为光镜下区分树突与轴突的标志。"},{"q":"肥大细胞通过合成分泌多种细胞因子和生物活性物质，发挥多种生理功能。下列关于肥大细胞分泌颗粒的特点描述，错误的是","o":["粗大，充满胞质","嗜碱性","可被甲苯胺蓝染成蓝色","易溶于水","含嗜酸性粒细胞趋化因子"],"a":2,"e":"肥大细胞颗粒粗大、充满胞质，具嗜碱性和异染性，被甲苯胺蓝染成紫红色而非蓝色；颗粒含组胺、肝素和嗜酸性粒细胞趋化因子，易溶于水。"},{"q":"临床上常以月经龄来推算胚胎龄，即从妊娠妇女末次月经的第一天算起，至胎儿娩出共约","o":["37周","38周","39周","40周","42周"],"a":3,"e":"月经龄从孕妇末次月经第1天算起，至胎儿娩出共约40周；受精龄从受精之日算起约38周，二者相差约2周。"},{"q":"有关血管球的描述，下列哪项是错误的","o":["是一种独特的动脉性毛细血管网","与肾小体尿极相通","毛细血管为有孔型","血管系膜位于毛细血管之间","基膜较厚"],"a":1,"e":"血管球是入球微动脉分支盘曲形成的毛细血管袢，位于肾小囊内、血管极侧，并汇成出球微动脉；尿极是肾小囊与近曲小管相连的一端。"},{"q":"心脏是心血管系统的泵器官，其管壁结构分为","o":["心内膜、心中膜、心外膜和心瓣膜","心内皮、内皮下层、内弹性膜、心中膜和心外膜","心内膜、心肌膜和心外膜","心内皮、内皮下层、心内膜下层、心肌膜和心外膜","心内膜、心内膜下层、心肌层和心外膜"],"a":2,"e":"心脏壁由内向外依次为心内膜、心肌膜和心外膜三层；心内膜又分为内皮、内皮下层和心内膜下层。"},{"q":"具有抗寄生虫、分泌防御素的细胞是","o":["微皱褶细胞","浆细胞","壁细胞","S细胞","帕内特细胞"],"a":4,"e":"帕内特细胞位于小肠腺基部，顶部含粗大嗜酸性颗粒，分泌溶菌酶和防御素，能杀灭肠道微生物，参与抗感染防御。"},{"q":"目前认为先天性畸形发生的主要原因是","o":["染色体畸变","基因突变","生物性和物理性致畸因子","化学性致畸因子","遗传因素与环境因素的相互作用和原因不明"],"a":4,"e":"先天畸形中多数是遗传因素与环境因素相互作用的结果，并有相当比例原因不明，单纯遗传或单纯环境因素所致者占比更小。"},{"q":"关于Ⅰ型肺泡细胞，哪项错误","o":["覆盖大部分肺泡表面","细胞扁平菲薄","胞质中细胞器丰富，具有分裂能力","相邻上皮细胞间有紧密连接","胞质内吞饮小泡多"],"a":2,"e":"Ⅰ型肺泡细胞扁平菲薄，覆盖肺泡约95%表面，细胞器少而吞饮小泡多，无增殖能力，损伤后由Ⅱ型肺泡细胞增殖补充。"},{"q":"关于假复层纤毛柱状上皮的描述，哪项不正确","o":["细胞形状、高矮不一","细胞都附着于基膜上","细胞表面都有纤毛","细胞核位置高低不等","主要分布于呼吸道腔面"],"a":2,"e":"假复层纤毛柱状上皮中仅柱状细胞游离面有纤毛，杯状细胞和锥形基细胞无纤毛；各类细胞高矮不一，但均附着于基膜。"},{"q":"精子获得运动能力，达到功能上成熟的部位是","o":["生精小管","直精小管","睾丸网","输出小管","附睾管"],"a":4,"e":"精子在附睾管内停留8～17天，经历一系列成熟变化后获得运动能力并达到功能成熟；获能则发生在女性生殖管道内。"},{"q":"多囊肾内的囊肿是","o":["静脉曲张","集合小管积液","肾盏膨大","肾小管积液","淋巴管扩张"],"a":3,"e":"多囊肾因远曲小管与集合管未接通，尿液积聚于肾小管内形成大小不等的囊泡，压迫周围肾单位使其萎缩。"},{"q":"关于角膜的描述，哪项错误","o":["角膜基质含少量的血管","角膜上皮为复层扁平，含丰富的神经末梢","角膜基质层最厚","角膜上皮基底层细胞由角膜缘干细胞补充","前界层和后界层不含细胞"],"a":0,"e":"角膜基质由多层胶原原纤维板构成，无血管，营养来自房水和角膜缘血管；故含少量血管的说法有误。"},{"q":"胸腺小体的特征是","o":["是胸腺的重要特征，散在分布于皮质内","由胸腺上皮细胞呈同心圆包绕而成","小体外周的上皮细胞较成熟","小体中心的上皮细胞较幼稚","功能尚不太明确，但对胸腺培育胸腺细胞无影响"],"a":1,"e":"胸腺小体位于胸腺髓质，由胸腺上皮细胞呈同心圆状排列而成，中央细胞角化退变，是髓质的特征性结构。"},{"q":"有关胃发生的描述，哪项错误","o":["胃在早期发生时为前肠尾部的梭形膨大，借腹、背系膜连于体壁上","由于胃的背、腹侧生长速度不等，分别形成胃大弯和胃小弯","当网膜囊形成时，胃大弯由背侧转向右侧，胃小弯由腹侧转向左侧","由于胃的右侧肝在发育，使胃呈左上至右下的斜向方位","胃大弯的头端膨出，形成胃底"],"a":2,"e":"胃背系膜形成网膜囊后，胃大弯由背侧转向左侧，胃小弯由腹侧转向右侧，胃顺时针旋转90度，呈左上至右下的斜位。"},{"q":"视网膜色素上皮来源于","o":["表面外胚层","间充质","视杯内层","视杯外层","视杯口边缘部"],"a":3,"e":"视杯外层分化为视网膜色素上皮层，内层分化为神经层；两层之间的视泡腔消失后彼此相贴，构成视网膜视部。"},{"q":"受精多发生于","o":["子宫体部或底部","输卵管壶腹部","输卵管峡部","输卵管漏斗部","输卵管子宫部"],"a":1,"e":"受精一般发生于输卵管壶腹部，精子与卵子在此相遇；卵子排出后停留于壶腹部，受精激发其完成第二次减数分裂。"},{"q":"下面对成骨细胞的描述，错误的是","o":["可转变为骨细胞","体积较大，有多个核","排列在成骨活跃的骨组织表面","胞质内粗面质网和高尔基复合体发达","合成和分泌胶原纤维和基质，形成类骨质"],"a":1,"e":"成骨细胞体积较大，呈立方形，只有一个核，位于骨组织成骨活跃的表面，合成并分泌类骨质，后被埋入基质成为骨细胞。"},{"q":"卵巢中黄体形成时，子宫内膜","o":["处于月经期","处于增生期","处于分泌期","处于卵泡期","剥脱、出血"],"a":2,"e":"排卵后黄体形成，分泌孕激素和雌激素，子宫内膜在二者作用下继续增厚、腺体分泌旺盛，进入分泌期即黄体期。"},{"q":"肛管下段由（ ）演变而来","o":["肛直肠管尾段","肛凹","肛膜","尿生殖窦","泄殖腔"],"a":1,"e":"肛管下段上皮来自外胚层，由肛凹演变而来，上段上皮来自内胚层，二者以齿状线分界；第8周末肛膜破裂，肛管才与直肠相通。"},{"q":"发生肝憩室的部位是","o":["前肠中段腹侧壁","前肠末端背侧壁","中肠襻头支腹侧壁","中肠襻尾支背侧壁","前肠末端腹侧壁"],"a":4,"e":"第4周时前肠末端腹侧壁内胚层细胞增生，向外突出形成肝憩室，为肝和胆囊的原基，其基部发育为胆总管。"},{"q":"关于同源细胞群，哪项正确","o":["直接起源于单核细胞","属于多核细胞","来源于同一个软骨细胞","是成骨细胞的前体","是破骨细胞的前体"],"a":2,"e":"同源细胞群由同一个幼稚软骨细胞分裂增殖形成，一般为2～8个细胞，位于软骨中部，越近中央细胞越成熟。"},{"q":"唇裂是由于","o":["两侧的上颌突未愈合","两侧的内侧鼻突未愈合","两侧的外侧鼻突未愈合","同侧的上颌突与内侧鼻突未愈合","同侧的上颌突与外侧鼻突未愈合"],"a":3,"e":"唇裂因同侧上颌突与内侧鼻突未融合所致，裂沟位于人中外侧；两侧内侧鼻突未融合则引起上唇正中裂。"},{"q":"新生小鼠切除胸腺后，体内缺乏","o":["T淋巴细胞","B淋巴细胞","K细胞","NK细胞","浆细胞"],"a":0,"e":"胸腺是培育T细胞的场所，新生小鼠切除胸腺后缺乏T淋巴细胞，表现为排斥异体移植物能力丧失、淋巴小结不发育、抗体产生减少。"},{"q":"神经系统来源于","o":["内胚层","中胚层","外胚层","内胚层与外胚层","中胚层与外胚层"],"a":2,"e":"神经系统起源于神经外胚层，先形成神经管和神经嵴，前者分化为中枢神经系统，后者分化为周围神经系统和肾上腺髓质等。"},{"q":"一名新生儿哭闹时会出现青紫现象，他最可能存在以下哪种先天畸形","o":["动脉导管未闭","主动脉骑跨","房间隔缺损","室间隔缺损","卵圆孔未闭"],"a":1,"e":"哭闹时青紫提示存在右向左分流，法洛四联症因主动脉骑跨接受右心室未氧合血，故出现发绀；单纯间隔缺损或动脉导管未闭多以左向右分流为主。"},{"q":"精子获能是指","o":["在生精小管发生过程中获得受精能力","在附睾才具有受精能力","子宫和输卵管中的某些化学物质使精子具有受精能力","精子释放顶体酶的反应","透明带和放射冠被分解的过程"],"a":2,"e":"获能指精子在子宫和输卵管内被去除表面的糖蛋白覆盖层，从而获得使卵子受精的能力，在女性生殖管道内可维持约24小时。"},{"q":"关于Ⅱ型肺泡细胞，下列哪项正确","o":["细胞扁平","胞质内含有电子密度低的分泌颗粒","参与组成气血屏障","分泌表面活性物质","无分裂增殖能力"],"a":3,"e":"Ⅱ型肺泡细胞呈立方形，胞质含嗜锇性板层小体，以胞吐方式分泌表面活性物质，降低肺泡表面张力，防止肺泡塌陷。"},{"q":"关于视神经乳头的描述，错误的是","o":["又称视盘","是视神经穿出眼球的部位","无感光细胞","有视网膜中央动、静脉进出","中央略凹，视觉最敏锐"],"a":4,"e":"视神经乳头是节细胞轴突汇集穿出眼球处，无感光细胞，故为生理盲点；视觉最敏锐处是视网膜中央凹。"},{"q":"发育成视网膜神经层的是","o":["视杯内层","视杯外层","视柄","晶状体板","间充质"],"a":0,"e":"视杯内层增厚，分化出节细胞、视细胞和双极细胞等，构成视网膜神经层；视杯外层分化为色素上皮层。"},{"q":"胆小管周围的肝细胞膜有","o":["连接复合体","紧密连接","桥粒","缝隙连接","基膜"],"a":0,"e":"胆小管周围相邻肝细胞膜形成由紧密连接和桥粒等组成的连接复合体，可封闭细胞间隙，防止胆汁外溢至细胞间或窦周隙。"},{"q":"卵巢中的成熟卵泡正常情况下排卵时间约在月经周期的","o":["第1天","第7天","第14天","第21天","第28天"],"a":2,"e":"排卵一般发生在月经周期第14天左右，此时成熟卵泡破裂，次级卵母细胞连同放射冠排入腹腔。"},{"q":"隐睾患者不育的原因是","o":["无精子生成","生精小管内无支持细胞","雄激素分泌不足","附睾管不通畅","无睾丸间质细胞"],"a":0,"e":"精子发生需低于体温2～3度的环境，隐睾时局部温度高致生精障碍，故无精子生成而不育；间质细胞分泌雄激素不受明显影响。"},{"q":"小儿佝偻病主要是因缺乏","o":["维生素C","维生素E","维生素A","维生素D","维生素K"],"a":3,"e":"维生素D促进小肠吸收钙磷并有利于类骨质矿化，儿童缺乏时类骨质不能钙化而致佝偻病，成人缺乏则引起骨软化症。"},{"q":"脐静脉血经哪一结构入下腔静脉","o":["上腔静脉","门静脉","动脉导管","肺静脉","静脉导管"],"a":4,"e":"脐静脉将胎盘来的富氧血送入肝，大部分经静脉导管直接汇入下腔静脉，余者经肝血窦后注入下腔静脉。"},{"q":"关于软骨组织中同源细胞群的描述，下列哪项正确","o":["来源于同一个软骨细胞","属于多核细胞","每群2～8个细胞，都是幼稚的软骨细胞","多个软骨细胞被一个软骨囊包绕","是骨细胞的前体"],"a":0,"e":"同源细胞群指软骨中部由同一个幼稚软骨细胞分裂增殖形成的2～8个细胞群体，并非多核细胞，也不是骨细胞的前体。"},{"q":"卵巢门细胞分泌","o":["雌激素","雄激素","孕激素","卵泡刺激素","黄体生成素"],"a":1,"e":"卵巢门细胞位于卵巢门处，胞质含脂滴，分泌雄激素；增生或发生肿瘤时患者可出现男性化症状。"},{"q":"下丘脑神经内分泌细胞分泌的激素不含有","o":["释放抑制激素","催产素","催乳激素","加压素","释放激素"],"a":2,"e":"下丘脑神经内分泌细胞分泌释放激素和释放抑制激素，视上核与室旁核还分泌血管升压素和催产素；催乳激素由腺垂体嗜酸性细胞分泌。"},{"q":"平滑肌纤维中，与骨骼肌横小管相当的结构是","o":["密体","密斑","肌膜内陷形成的小凹","中间丝","肌质网"],"a":2,"e":"平滑肌纤维表面的肌膜向胞质内凹陷形成小凹，沿细胞长轴呈带状排列，功能相当于骨骼肌的横小管，可传递兴奋。"},{"q":"血管内皮下层不含有","o":["平滑肌纤维","营养血管","胶原纤维","弹性纤维","细胞外基质"],"a":1,"e":"血管内皮下层为薄层结缔组织，含胶原纤维、弹性纤维、基质和少量平滑肌纤维；营养血管分布于外膜。"},{"q":"以下一般不用于显示DNA的方法或试剂是","o":["原位杂交","孚尔根（Feulgen）反应","吖啶橙","甲基绿","派若宁"],"a":4,"e":"派若宁特异性显示核糖核酸，呈红色；显示DNA常用孚尔根反应、甲基绿和吖啶橙，原位杂交亦可检测特定DNA序列。"},{"q":"单核细胞的特点不包括","o":["血液中体积最大的细胞","占白细胞总数20%～25%","细胞质丰富，呈弱嗜碱性","有吞噬功能，属单核吞噬细胞系统","由骨髓内幼单核细胞转化而来"],"a":1,"e":"单核细胞占白细胞总数的3%～8%，是血液中体积最大的细胞，胞质丰富呈弱嗜碱性，由骨髓幼单核细胞转化而来，吞噬能力强。"},{"q":"下述哪一过程既不发生有丝分裂也不发生减数分裂","o":["精原细胞变为初级精母细胞","初级精母细胞变为次级精母细胞","次级精母细胞变为精子细胞","精子细胞变为精子","间质细胞的增殖"],"a":3,"e":"精子细胞变为精子是变态过程即精子形成，只发生形态变化，既不进行有丝分裂也不进行减数分裂；精原细胞增殖为有丝分裂。"},{"q":"人胚第5周时，由背侧体壁突入胚内体腔的两条纵行隆起是","o":["中肾嵴","生殖腺嵴","生肾索","尿生殖嵴","脊索"],"a":3,"e":"第4周末生肾索凸向胚内体腔形成尿生殖嵴，第5周其表面出现纵沟，分为外侧的中肾嵴和内侧的生殖嵴。"},{"q":"神经元传导神经冲动是通过","o":["微管","轴膜","神经内膜","神经膜","神经束膜"],"a":1,"e":"神经冲动沿轴膜传导，轴膜即轴突的细胞膜，其离子通道产生动作电位；髓鞘起绝缘作用，使有髓纤维呈跳跃式传导。"},{"q":"弹性软骨区别于透明软骨的主要特征是","o":["软骨陷窝不明显","缺乏软骨囊","无同源细胞群","基质中含有大量弹性纤维","软骨基质较多"],"a":3,"e":"弹性软骨与透明软骨结构相似，但基质中含大量交织排列的弹性纤维，故弹性好，见于耳郭、会厌和咽喉等处。"},{"q":"血窦不存在于","o":["肝","脾","骨髓","垂体","脑"],"a":4,"e":"血窦见于肝、脾、骨髓和部分内分泌腺，管腔大、内皮有窗孔；脑内毛细血管为连续型并构成血-脑屏障，故无血窦。"},{"q":"关于肾小体的组成，正确的是","o":["由肾小囊和血管球组成","由肾小管和血管球组成","由肾小囊和肾小管组成","由肾小囊，肾小管和集合管组成","由血管球和泌尿小管组成"],"a":0,"e":"肾小体由血管球和肾小囊组成，血管球为盘曲的毛细血管袢，肾小囊为双层上皮囊；肾小管与集合管属泌尿小管，不在肾小体之内。"},{"q":"关于胃底腺壁细胞的描述，哪项是错误的","o":["主要位于腺的颈部和体部","胞质嗜碱性","有特殊的细胞内分泌小管","含丰富的线粒体","细胞萎缩可引起贫血"],"a":1,"e":"壁细胞胞质嗜酸性，含大量线粒体和细胞内分泌小管，分泌盐酸和内因子；细胞萎缩致内因子不足，维生素B12吸收障碍而引起恶性贫血。"},{"q":"食管腔面衬覆的上皮和小肠上皮相比要耐摩擦，之所以耐摩擦是与该上皮独特的结构特点有关，下列哪项不属于这些特点","o":["组成的细胞层数多","浅层细胞胞质充满干硬的角蛋白","细胞之间有大量的桥粒","基底层的细胞与基膜之间有半桥粒","基底层细胞有很强的分裂增殖能力"],"a":1,"e":"食管上皮为未角化复层扁平上皮，浅层细胞有核、含角蛋白少；浅层充满干硬角蛋白的是皮肤表皮的角化复层扁平上皮。"},{"q":"肺泡进行气体交换的主要细胞是","o":["Ⅰ型肺泡细胞","Ⅱ型肺泡细胞","肺动脉内皮细胞","尘细胞","巨噬细胞"],"a":0,"e":"Ⅰ型肺泡细胞扁平菲薄，覆盖肺泡约95%表面积，与基膜和毛细血管内皮共同构成气-血屏障，是气体交换的部位。"},{"q":"构成骺板的是","o":["透明软骨","弹性软骨","骨组织","类骨质","数层骨板"],"a":0,"e":"骺板是位于长骨骨干与骺之间的透明软骨，其软骨细胞不断增殖、肥大、钙化并被骨组织替换，使长骨不断加长。"},{"q":"长期吸烟或反复感染可使气管和支气管","o":["纤毛细胞增加，纤毛运动增强","杯状细胞减少，分泌也减弱","腺体增生肥大，分泌增强","分泌的黏液糖蛋白成分不变","无白细胞渗出"],"a":2,"e":"长期吸烟或反复感染使气管和支气管的腺体增生肥大、分泌增强，杯状细胞增多，纤毛变短、粘连、倒伏甚至脱失。"},{"q":"有关气管表面黏液层描述正确的是","o":["由黏液性腺泡和杯状细胞的分泌物形成，具有中和有害气体和吸附微尘作用","由黏液性腺泡和浆细胞分泌物形成，具有中和有害气体和吸附微尘作用","由黏液性腺泡和杯状细胞分泌物形成，具有阻碍通气的作用","纤毛和杯状细胞分泌物形成，具有阻碍通气的作用","Clara细胞与杯状细胞分泌物形成，具有中和有害气体和吸附微尘作用"],"a":0,"e":"气管黏膜表面的黏液由混合腺的黏液性腺泡和杯状细胞分泌，可黏附异物颗粒并溶解二氧化硫等有害气体，再由纤毛向咽部排出。"},{"q":"大脑皮质内的传出神经元主要是","o":["浦肯野细胞","锥体细胞","梭形细胞","锥体细胞和梭形细胞","水平细胞和星形细胞"],"a":3,"e":"大脑皮质的传出神经元为高尔基I型神经元，包括大、中型锥体细胞和梭形细胞，其轴突组成投射纤维和联合传出纤维。"},{"q":"血小板描述正确的是","o":["是有核的细胞","细胞直径7～8μm","胞质中有嗜碱性的特殊颗粒","胞质的特殊颗粒含组胺和肝素","双凸圆盘形，直径约2～4μm"],"a":4,"e":"血小板是巨核细胞胞质脱落的小块，呈双凸圆盘状，直径2～4μm，无核，含特殊颗粒和开放小管系。"},{"q":"分泌雄激素结合蛋白的是","o":["精子细胞","初级精母细胞","支持细胞","睾丸间质细胞","精原细胞"],"a":2,"e":"支持细胞在卵泡刺激素和雄激素作用下合成并分泌雄激素结合蛋白，与雄激素结合以维持生精小管内高浓度雄激素，促进精子发生。"},{"q":"围心腔最早位于","o":["生心索背侧","口咽膜的尾侧","生心索腹侧","泄殖腔腹侧","神经管尾侧"],"a":0,"e":"围心腔出现于生心区，位于生心索即生心板的背侧；头褶发生后围心腔转至腹侧，心管则转至围心腔的背侧。"},{"q":"视上核分泌物运抵神经垂体的途径是","o":["漏斗柄","下丘脑垂体束","垂体门脉系统","结节垂体束","毛细淋巴管"],"a":1,"e":"视上核和室旁核神经元的轴突经漏斗下行，构成下丘脑神经垂体束，将血管升压素和催产素输送至神经部贮存并释放。"},{"q":"巨噬细胞是体内具有强大吞噬能力的结缔组织细胞，数量多，分布广泛。该细胞胞质内与吞噬功能相关的细胞器是","o":["滑面内质网和高尔基复合体","粗面内质网和高尔基复合体","溶酶体和吞噬体","吞噬体和嗜酸性异染性颗粒","粗面内质网和滑面内质网"],"a":2,"e":"巨噬细胞吞噬异物后形成吞噬体或吞饮泡，再与溶酶体融合而被酶降解，故与吞噬功能直接相关的细胞器是溶酶体和吞噬体。"},{"q":"符合复层扁平上皮特点的是","o":["浅层为一层立方细胞","中间层细胞之间有大量缝隙连接","基底层细胞有较强的分裂增殖能力","含较多的毛细血管","与结缔组织的连接面平直"],"a":2,"e":"复层扁平上皮的基底层细胞有较强的分裂增殖能力，可不断补充浅层脱落的细胞；其与结缔组织的连接面呈凹凸不平的乳头状。"},{"q":"中枢神经系统的原基是","o":["神经嵴","神经管","神经板","神经孔","神经沟"],"a":1,"e":"神经管是中枢神经系统的原基，分化为脑和脊髓以及松果体、神经垂体和视网膜等；神经嵴分化为周围神经系统。"},{"q":"组织固定的意义是","o":["使蛋白质迅速溶解","防止细胞自溶","使组织膨胀","使组织坚硬","加大组织成分反差"],"a":1,"e":"组织固定的主要意义是用固定液使蛋白质凝固，防止细胞自溶和组织腐败，并保持组织原有的形态结构。"},{"q":"泌尿、生殖系统的主要器官均发生于","o":["间介中胚层","侧中胚层","轴旁中胚层","间充质细胞","体节"],"a":0,"e":"泌尿系统和生殖系统的主要器官均起源于间介中胚层，其颈部为生肾节，尾段形成生肾索并进而形成尿生殖嵴。"},{"q":"小脑来源于","o":["端脑","间脑","中脑","后脑","末脑"],"a":3,"e":"菱脑泡头段演变为后脑，后脑再分化为脑桥和小脑；末脑演变为延髓，中脑泡演变为中脑。"},{"q":"软骨细胞的营养依靠","o":["基质中丰富的血管","软骨内小管","毛细血管直接开口于软骨陷窝","通过基质渗透","穿通管"],"a":3,"e":"软骨组织内无血管和淋巴管，深部软骨细胞依靠基质分子筛的渗透作用与周围组织进行物质交换，故营养通过基质渗透获得。"},{"q":"心肌纤维内的钙离子主要储存于","o":["肌浆网","肌浆","线粒体","闰盘","横小管"],"a":0,"e":"心肌纤维的肌浆网纵小管末端膨大成终池，是细胞内钙离子的主要储存部位；其肌浆网不如骨骼肌发达，收缩时还需细胞外钙离子参与。"},{"q":"正中腭裂是由于","o":["外侧腭突与正中腭突未融合","双侧外侧腭突未融合","正中腭突与上颌突未融合","外侧腭突与上颌突未融合","口咽膜未破裂"],"a":1,"e":"正中腭裂因左右外侧腭突未在中线融合所致，表现为从切齿孔至腭垂的矢状裂隙；外侧腭突与正中腭突未融合则形成前腭裂。"},{"q":"以下哪项各层富含血管和色素","o":["角膜，巩膜，虹膜","虹膜，睫状体，脉络膜","虹膜，角膜，脉络膜","角膜，虹膜，视网膜","虹膜，睫状体，视网膜"],"a":1,"e":"血管膜由富含血管和黑素细胞的疏松结缔组织构成，自前向后分为虹膜基质、睫状体基质和脉络膜三部分。"},{"q":"横小管是骨骼肌纤维的","o":["线粒体","高尔基复合体","粗面内质网","滑面内质网","肌膜向肌质内凹陷而成的小管"],"a":4,"e":"横小管是肌膜在明、暗带交界处向肌质内凹陷形成的管状结构，环绕肌原纤维，可将肌膜的兴奋传至肌纤维内部。"},{"q":"对于生发中心的描述，错误的是","o":["是初级淋巴小结中央着色浅淡的区域","是次级淋巴小结中央着色浅淡的区域","含B细胞、巨噬细胞、滤泡树突状细胞和Th细胞等","分为浅部的明区和其下方的暗区","周边有一层密集的小B细胞形成小结帽"],"a":0,"e":"生发中心是次级淋巴小结中央着色浅淡的区域，分暗区和明区，含B细胞、Th细胞、滤泡树突状细胞和巨噬细胞，周边为小结帽。"},{"q":"大脑皮质运动区较发达的一层是","o":["外锥体细胞层","内颗粒层","外颗粒层","内锥体细胞层","多形细胞层"],"a":3,"e":"大脑皮质运动区内锥体细胞层即第5层特别发达，含大型锥体细胞，其轴突下行组成皮质脊髓束和皮质核束。"},{"q":"球旁细胞的特征是","o":["细胞呈梭形，胞质色浅，核圆居中","胞质内有许多肌丝和分泌颗粒","胞质内肌丝少，有较多分泌颗粒","细胞呈立方形，胞质有许多黏原颗粒","颗粒内有结晶体，含有前列腺素"],"a":2,"e":"球旁细胞由入球微动脉的平滑肌纤维分化而来，呈立方形，胞质内肌丝少，粗面内质网和高尔基复合体发达，含肾素分泌颗粒。"},{"q":"与角膜缘结构和功能不符合的是","o":["位于角膜和巩膜移行处","有巩膜静脉窦和小梁网","小梁间有小梁间隙，是房水循环的通道","小梁间隙阻塞可使眼内压升高，导致白内障","巩膜静脉窦为环形小管，管内充满房水"],"a":3,"e":"小梁间隙阻塞使房水回流受阻、眼压升高，导致青光眼而非白内障；白内障是晶状体混浊所致的视觉障碍。"},{"q":"关于肝巨噬细胞的特征，哪项正确","o":["细胞形态不规则，胞浆嗜碱性","细胞表面突起可附着于内皮细胞表面或伸入内皮间隙","巨噬细胞位于窦周隙内","巨噬细胞由血窦内皮细胞转变而成","巨噬细胞能合成细胞外基质"],"a":1,"e":"肝巨噬细胞形态不规则，表面有大量皱褶和微绒毛，以板状和丝状伪足附着于内皮细胞，或穿过内皮窗孔伸入窦周隙，由单核细胞分化而来。"},{"q":"以下纤维中，哪种又称嗜银纤维","o":["网状纤维","弹性纤维","胶原纤维","微原纤维","肌原纤维"],"a":0,"e":"网状纤维主要由III型胶原蛋白构成，表面被覆糖蛋白，镀银染色呈黑色，故称嗜银纤维，主要存在于网状组织。"},{"q":"平滑肌纤维间存在的细胞连接是","o":["中间连接","紧密连接","缝隙连接","桥粒","闰盘"],"a":2,"e":"平滑肌纤维之间有发达的缝隙连接，可传递信息分子和电冲动，使众多平滑肌纤维同步收缩而成为功能整体。"},{"q":"神经元的轴突不含","o":["微管","尼氏体","线粒体","微丝","神经丝"],"a":1,"e":"尼氏体由粗面内质网和游离核糖体构成，位于胞体和树突内；轴突内无尼氏体，其胞质含微管、微丝、神经丝和线粒体。"},{"q":"在轴突运输中起主要作用的结构是","o":["滑面内质网","高尔基复合体","微丝","突触小泡","微管"],"a":4,"e":"微管是轴突运输的轨道，驱动蛋白与动力蛋白携货物沿微管双向移动，微丝和滑面内质网不承担长距离运输。"},{"q":"类骨质是指","o":["新形成未钙化的骨质","黏合线处的骨质","尚未形成骨板的骨质","软骨雏形的基质","软骨陷窝周围的基质"],"a":0,"e":"成骨细胞分泌的骨基质有机成分尚未矿化时称类骨质，钙盐沉积后即转变为坚硬的骨质，该过程称钙化。"},{"q":"施万细胞的细胞膜和基膜形成","o":["神经内膜","神经束膜","神经外膜","神经膜","胶质膜"],"a":3,"e":"施万细胞最外一层细胞膜与其外方基膜共同构成神经膜，包绕周围神经纤维并参与髓鞘形成。"},{"q":"刚出生7天的婴儿一直未大便，最可能的诊断是","o":["食管闭锁","十二指肠狭窄","不通肛","环状胰","喂养不当"],"a":2,"e":"不通肛即肛门闭锁，因肛膜未破裂或直肠与肛凹未接通，出生后无胎粪排出，应尽早手术。"},{"q":"参与体液免疫的细胞是","o":["B淋巴细胞","T淋巴细胞","肥大细胞","网状细胞","嗜碱粒细胞"],"a":0,"e":"B淋巴细胞受抗原刺激后分化为浆细胞并分泌抗体，抗体进入体液执行免疫，故称体液免疫。"},{"q":"透明角质颗粒存在于表皮的","o":["基底层","棘层","颗粒层","透明层","角质层"],"a":2,"e":"透明角质颗粒为颗粒层细胞质内强嗜碱性、无膜包裹的均质颗粒，是角蛋白形成的中间产物。"},{"q":"关于游离神经末梢的描述，哪一项是错误的","o":["是感觉神经元的轴突分支","感觉神经元的周围突末端失去髓鞘而成","分布于皮肤表皮或上皮组织内","也可分布于结缔组织和肌组织内","感受冷、热和痛觉"],"a":0,"e":"游离神经末梢是感觉神经元周围突即树突的末端，反复分支并失去髓鞘，分布于上皮、结缔组织和肌组织。"},{"q":"区别有粒白细胞和无粒白细胞的主要依据是","o":["细胞大小","细胞核形态","有无嗜天青颗粒","有无特殊颗粒","有无吞噬功能"],"a":3,"e":"白细胞按胞质内有无特殊颗粒分为有粒和无粒两类，特殊颗粒的染色性还是粒细胞进一步分类的依据。"},{"q":"关于初级卵泡结构，哪项错误","o":["卵泡体积增大","卵泡细胞由单层发育为多层","卵泡周围结缔组织形成一层卵泡膜","透明带由卵泡细胞形成，出现卵泡腔","卵泡细胞之间及卵泡细胞与初级卵母细胞间有缝隙连接存在"],"a":3,"e":"初级卵泡的透明带由卵母细胞与卵泡细胞共同分泌，卵泡腔到次级卵泡才出现，故该项描述错误。"},{"q":"采用透射电镜术制备和观察标本时，哪一项不正确","o":["取材要新鲜","组织块不需要固定","需制备超薄切片","用重金属染色","在荧光屏上观察"],"a":1,"e":"透射电镜标本须经戊二醛与锇酸两次固定并树脂包埋，否则细胞超微结构自溶破坏，无法观察。"},{"q":"有关十二指肠腺描述正确的是","o":["黏液性腺，开口于小肠腺之间","黏液性腺，开口于小肠腺底部","黏液性腺，开口于绒毛基部","浆液性腺，开口于小肠腺底部","浆液性腺，开口于胆总管开口处附近"],"a":1,"e":"十二指肠腺位于黏膜下层，为黏液腺，导管穿过黏膜肌层开口于小肠腺底部，分泌碱性黏液保护黏膜。"},{"q":"有髓神经纤维的神经冲动传导方式是","o":["在轴膜上连续进行","在轴膜上跳跃式进行","在郎飞结间连续跳跃式进行","在髓鞘切迹间连续跳跃式进行","在结间体间连续跳跃式进行"],"a":2,"e":"髓鞘含大量类脂而绝缘，兴奋只能在郎飞结处轴膜产生，冲动由一个郎飞结跳至下一个，故呈跳跃式传导。"},{"q":"毛的生长点是","o":["上皮根鞘","毛球","毛乳头","毛根","毛囊"],"a":1,"e":"毛球底面上皮细胞增殖分化形成毛根与毛囊，故为毛的生长点，毛乳头只起诱导和营养作用。"},{"q":"小脑皮质颗粒层的神经元包括","o":["浦肯野细胞和颗粒细胞","颗粒细胞和高尔基细胞","颗粒细胞和篮状细胞","颗粒细胞与星形细胞","星形细胞与锥体细胞"],"a":1,"e":"小脑皮质颗粒层含密集的颗粒细胞和少量高尔基细胞，浦肯野细胞、篮状细胞和星形细胞均位于分子层。"},{"q":"心肌闰盘的横向连接面上有","o":["紧密连接和桥粒","缝隙连接和桥粒","中间连接和桥粒","中间连接和缝隙连接","紧密连接和缝隙连接"],"a":2,"e":"闰盘横向部分位于Z线水平，有黏着小带即中间连接与桥粒，使心肌纤维连接牢固，缝隙连接位于纵向部分。"},{"q":"具有吞噬功能的细胞是","o":["中性粒细胞","肥大细胞","嗜碱性粒细胞","血小板","红细胞"],"a":0,"e":"中性粒细胞具强趋化性和吞噬功能，以吞噬细菌为主，肥大细胞和嗜碱性粒细胞主要释放活性物质参与过敏反应。"},{"q":"表皮中的干细胞位于","o":["基底层","棘层","颗粒层","透明层","角质层"],"a":0,"e":"基底层为附着于基膜的一层矮柱状细胞，是表皮的干细胞，不断分裂补充棘层及表面脱落的细胞。"},{"q":"人体内最坚硬的组织是","o":["牙本质","釉质","牙骨质","骨密质","纤维软骨"],"a":1,"e":"釉质无机物约占96%，覆盖牙冠表面，是人体最坚硬的结构，牙本质和牙骨质的硬度均低于釉质。"},{"q":"耳廓来自于","o":["听泡","第Ⅰ咽囊","第Ⅰ鳃沟","第Ⅰ鳃膜","耳丘"],"a":4,"e":"第1鳃沟周围间充质增生形成6个结节状耳丘，围绕外耳道口演变为耳郭，外耳道则由第1鳃沟演变。"},{"q":"胰岛调节血糖浓度的激素是","o":["A细胞分泌的胰岛素和B细胞分泌的高血糖素","A细胞分泌的高血糖素和B细胞分泌的胰岛素","A细胞分泌的高血糖素和D细胞分泌的生长抑素","B细胞分泌的高血糖素和D细胞分泌的生长抑素","B细胞分泌的胰岛素和D细胞分泌的生长抑素"],"a":1,"e":"A细胞分泌胰高血糖素使血糖升高，B细胞分泌胰岛素使血糖降低，二者协同维持血糖动态平衡。"},{"q":"下列关于肾的血液循环特点，哪项是错误的","o":["肾内血流量很大","动脉在肾内三次形成毛细血管网","血液流经肾血管球时形成滤液","球后毛细血管网内的胶体渗透压较高","动脉在肾内两次形成毛细血管网"],"a":1,"e":"肾内动脉仅两次形成毛细血管网，即入球微动脉形成血管球、出球微动脉形成球后毛细血管网。"},{"q":"延髓来源于","o":["端脑","间脑","中脑","后脑","末脑"],"a":4,"e":"菱脑泡尾段演变为末脑，末脑发育为延髓，其头段后脑演变为脑桥和小脑，中脑泡则演变为中脑。"},{"q":"睑板腺的性质是","o":["内分泌腺","汗腺","皮脂腺","浆液性腺","黏液性腺"],"a":2,"e":"睑板内平行排列的分支管泡状皮脂腺即睑板腺，导管开口于睑缘，分泌脂质润滑睑缘并保护角膜。"},{"q":"角膜上皮来自于","o":["表面外胚层","间充质","神经外胚层","内胚层","表面外胚层和间充质"],"a":0,"e":"角膜上皮由眼球前方的表面外胚层分化而来，角膜其余各层以及巩膜、血管膜均由间充质分化。"},{"q":"神经上皮最初呈","o":["单层扁平上皮","单层立方上皮","单层柱状上皮","假复层柱状上皮","复层扁平上皮"],"a":3,"e":"神经管壁最初为单层柱状上皮，此后细胞增殖使核位置分层，演变为假复层柱状上皮，即神经上皮。"},{"q":"化学突触的突触前膜指的是","o":["轴突的细胞膜","树突的细胞膜","有受体一侧的细胞膜","释放神经递质一侧的细胞膜","神经细胞胞体的细胞膜"],"a":3,"e":"突触前成分是释放神经递质一侧的轴突终末，其细胞膜为突触前膜，有受体的一侧为突触后膜。"},{"q":"组织学中最常用的制片技术是","o":["石蜡切片","火棉胶切片","冰冻切片","涂片","铺片"],"a":0,"e":"石蜡切片经取材、固定、包埋、切片、脱蜡和染色等步骤，可连续切片并长期保存，是组织学最常用的制片技术。"},{"q":"大脑皮质多形细胞层内的神经元主要为","o":["颗粒细胞","梭形细胞","锥体细胞","星形细胞","篮状细胞"],"a":1,"e":"多形细胞层以梭形细胞为主，另有锥体细胞和上行轴突细胞，梭形细胞轴突进入白质组成投射纤维。"},{"q":"关于甲状旁腺的描述，哪项错误","o":["腺细胞分为主细胞和嗜酸性细胞","分泌的激素参与血钙浓度调节","嗜酸性细胞体积大，胞质嗜酸性，核小深染","主细胞分泌的激素属于类固醇类激素","嗜酸性细胞随年龄增长而增多"],"a":3,"e":"甲状旁腺主细胞分泌甲状旁腺激素，属含氮的肽类激素，通过第二信使发挥作用，并非类固醇激素。"},{"q":"肌性动脉中膜内产生基质和纤维的细胞是","o":["成纤维细胞","间充质细胞","平滑肌细胞","内皮细胞","巨噬细胞"],"a":2,"e":"中动脉中膜平滑肌纤维丰富，能产生胶原纤维、弹性纤维和基质，发挥类似成纤维细胞的作用。"},{"q":"面斜裂的成因是","o":["两侧上颌突未融合","同侧的内、外侧鼻突未融合","额鼻突和外侧鼻突未融合","上颌突与同侧的外侧鼻突未融合","上颌突与同侧的内侧鼻突未融合"],"a":3,"e":"面斜裂位于眼内眦与口角之间，因上颌突与同侧外侧鼻突未融合所致，唇裂则源于上颌突与内侧鼻突未融合。"},{"q":"早期心管的4个膨大，从头端至尾端依次为","o":["心球、心房、心室、静脉窦","心房、心室、心球、静脉窦","心球、心室、心房、静脉窦","静脉窦、心房、心室、心球","心球、心室、心房、动脉干"],"a":2,"e":"心管由头向尾依次形成心球、心室、心房和静脉窦四个膨大，静脉窦末端分左右角接受回心血液。"},{"q":"后肾的发生中，来自输尿管芽的部分与生后肾组织的部分的连接点是","o":["肾盏与集合小管相连接","集合小管与远端小管相连接","远端小管与细段相连接","细段与近端小管相连接","近端小管与肾小体相连接"],"a":1,"e":"输尿管芽形成集合小管及肾盂、肾盏，生后肾组织形成肾小管，两者在远端小管与集合小管处接通。"},{"q":"肾脏病变可引起蛋白尿，正常情况下重吸收原尿中蛋白质的结构是近端小管上皮的","o":["侧突","顶小管和顶小泡","质膜内褶","细胞间隙","微绒毛"],"a":1,"e":"近端小管微绒毛基部的细胞膜凹陷形成顶小管和顶小泡，以吞饮方式重吸收原尿中的小分子蛋白质。"},{"q":"诱导外胚层增厚形成神经板的结构是","o":["原条","体节","原结","脊索","轴旁中胚层"],"a":3,"e":"脊索形成后诱导其背侧中线的外胚层增厚为神经板，神经板继而凹陷成神经沟并闭合为神经管。"},{"q":"精子发生的干细胞是","o":["精子细胞","精子","次级精母细胞","初级精母细胞","精原细胞"],"a":4,"e":"A型精原细胞是生精细胞中的干细胞，不断分裂增殖，部分子细胞维持干细胞身份，部分分化为B型精原细胞。"},{"q":"下列关于蛛网膜和软膜的描述，哪项错误","o":["蛛网膜是薄层结缔组织，有小梁连于软膜","蛛网膜与软膜间的腔隙叫蛛网膜下腔","蛛网膜下腔内有脑脊液，可借蛛网膜颗粒吸收入硬膜静脉窦","软膜内无血管分布","软膜外表面和蛛网膜的內、外表面以及小梁表面都被覆单层扁平上皮"],"a":3,"e":"软膜为薄层结缔组织，富含血管并随血管伸入脑内供应脑与脊髓，故软膜内无血管的说法错误。"},{"q":"输卵管起源于","o":["中肾旁管下段","中肾管下段","中肾旁管上段和横行的中段","尾端中肾小管","中肾管中段"],"a":2,"e":"中肾旁管上段与横行中段演变为输卵管，下段左右合并演变为子宫及阴道穹，中肾管在女性退化。"},{"q":"肌质网能够","o":["与粗肌丝相结合","与细肌丝相结合","将肌膜的兴奋迅速传到肌纤维内部","储存Ca2＋","分解ATP并释放能量"],"a":3,"e":"肌质网膜上有钙泵和钙通道，钙泵逆浓度差将Ca2+泵入网内贮存，兴奋时释放入肌质引起收缩。"},{"q":"关于卵黄囊，哪项正确","o":["人胚卵黄囊内有少量卵黄","卵黄蒂演化为尿囊","卵黄囊壁外附有胚外中胚层","卵黄囊构成原始消化管的一部分","顶部为外胚层"],"a":2,"e":"卵黄囊由下胚层周缘细胞围成，外表面附有胚外中胚层，并随胚外体腔扩大经体蒂与绒毛膜相连。"},{"q":"消化管具有绒毛结构的是","o":["胃","食管","小肠","结肠","阑尾"],"a":2,"e":"小肠黏膜和部分黏膜下层形成环行皱襞，黏膜上皮与固有层形成绒毛，上皮游离面还有微绒毛。"},{"q":"下列细胞中，哪个具有分泌功能","o":["纤毛细胞","杯状细胞","基细胞","Ⅰ型肺泡细胞","梭型细胞"],"a":1,"e":"杯状细胞顶部充满黏原颗粒，分泌黏液覆盖上皮表面，起润滑和保护作用，是单层柱状上皮中的分泌细胞。"},{"q":"女性体内可产生雄激素的细胞是","o":["肾上腺束状带细胞","胰岛细胞","肾间质细胞","肾上腺网状带细胞","垂体嗜酸性细胞"],"a":3,"e":"肾上腺网状带细胞分泌雄激素，女性体内的雄激素部分来源于此，卵巢门细胞也可分泌少量雄激素。"},{"q":"心脏传导系统","o":["由特殊的神经细胞和神经纤维构成","均位于心内膜下层","包括起搏细胞、移行细胞和普肯耶纤维","各成分之间由细胞质桥连成功能整体","将神经元的起搏冲动传导给普通心肌细胞"],"a":2,"e":"心脏传导系统由起搏细胞、移行细胞和浦肯野纤维构成，均属特殊心肌纤维，并非神经细胞和神经纤维。"},{"q":"动脉管壁的分层为","o":["内皮、内皮下层、弹性膜、肌层和外膜","内膜、弹性膜、肌膜和外膜","内膜、肌膜和外膜","内膜、中膜和外膜","内膜、内膜下层、中膜和外膜"],"a":3,"e":"动脉与静脉管壁自腔面向外均分为内膜、中膜和外膜三层，内膜又分内皮、内皮下层和内弹性膜。"},{"q":"关于脾的结构，哪项正确","o":["红髓色深，由淋巴小结组成","白髓色浅，由血窦组成","动脉周围淋巴鞘主要含B细胞","脾索主要含T细胞","脾索内的淋巴细胞可经内皮间隙进入脾血窦内"],"a":4,"e":"脾索内血细胞可变型穿越血窦内皮细胞间0.2～0.5μm的间隙进入脾血窦，衰老红细胞因变形性下降而被滞留。"},{"q":"二胚层胚盘形成于","o":["底蜕膜","极端滋养层","内细胞群","滋养层","中胚层"],"a":2,"e":"第2周内细胞群增殖分化，形成由上胚层和下胚层组成的圆盘状二胚层胚盘，是人体发生的原基。"},{"q":"胰腺分泌胰岛素和高血糖素的细胞分别是","o":["A细胞和B细胞","B细胞和A细胞","A细胞和D细胞","D细胞和B细胞","D细胞和A细胞"],"a":1,"e":"B细胞约占胰岛细胞总数的70%，分泌胰岛素降低血糖，A细胞分泌胰高血糖素升高血糖，二者协同维持血糖稳定。"},{"q":"约95%的膀胱肿瘤起源于上皮组织，膀胱和肾盂、输尿管共有的结构特点是","o":["腔面被覆单层立方上皮","腔面被覆变移上皮","腔面被覆复层扁平上皮","都有骨骼肌所包绕","都有三层平滑肌包绕"],"a":1,"e":"肾盏、肾盂、输尿管和膀胱的腔面均被覆变移上皮，其细胞层数随器官空虚或充盈而改变。"},{"q":"对视网膜描述，错误的是","o":["主要细胞成分有色素上皮细胞、视细胞、双极细胞和节细胞","神经胶质细胞是müller细胞","光镜下可分为10层","黄斑中央凹处只有视杆细胞","视神经乳头无感光功能"],"a":3,"e":"黄斑中央凹处只有视锥细胞，且与双极细胞、节细胞单线联系，故视觉最敏锐；视杆细胞分布于中央凹以外。"},{"q":"关于桥粒的描述，不正确的是","o":["在上皮细胞顶部呈带状","细胞间隙可见致密的中间线","细胞膜的胞质面有较厚的附着板","附着板上连有张力丝","桥粒是很牢固的细胞连接"],"a":0,"e":"桥粒呈斑块状分布于相邻细胞间，胞质面有附着板并连有张力丝，呈带状环绕细胞顶部的是黏着小带和紧密连接。"},{"q":"关于动脉的描述，错误的是","o":["大动脉包括主动脉、颈总动脉、锁骨下动脉、肺动脉等","中动脉的管壁3层结构典型","中动脉中膜由10～40层环形平滑肌组成","中动脉又称弹性动脉","小动脉属肌性动脉"],"a":3,"e":"大动脉中膜含多层弹性膜和大量弹性纤维，称弹性动脉；中动脉平滑肌丰富，称肌性动脉或分配动脉。"},{"q":"清除淋巴液内抗原的细胞主要是","o":["淋巴窦内皮细胞","淋巴窦内的巨噬细胞","淋巴窦内的星状内皮细胞","滤泡树突细胞","肥大细胞"],"a":1,"e":"淋巴窦内巨噬细胞附着于内皮，淋巴在窦内流动缓慢，便于其吞噬清除淋巴液中的抗原和异物。"},{"q":"调节晶状体曲度的主要结构是","o":["瞳孔括约肌","瞳孔开大肌","睫状肌","睫状小带","晶状体纤维"],"a":2,"e":"睫状肌收缩时睫状体前移内突，睫状小带松弛，晶状体因自身弹性变凸，屈光力增强，故调节依赖睫状肌。"},{"q":"关于膀胱的描述，正确的为","o":["黏膜上皮为复层扁平上皮","固有层内含较多的腺体","肌层由内纵、中环、外纵三层平滑肌组成","肌层由内环、外纵两层平滑肌组成","膀胱空虚时，上皮仅有3～4层细胞，表层细胞变扁"],"a":2,"e":"膀胱肌层由内纵行、中环行和外纵行三层平滑肌交错构成，中层在尿道内口处增厚形成括约肌。"},{"q":"关于胰腺的描述，下列哪项错误","o":["纯浆液性腺","可见泡心细胞","有较多的纹状管","可见胰岛","闰管较长"],"a":2,"e":"胰腺为纯浆液性复管泡状腺，有泡心细胞和较长闰管，无纹状管，纹状管发达的是下颌下腺。"},{"q":"促性腺激素释放激素主要作用于","o":["睾丸","卵巢","子宫","垂体嗜酸性细胞","垂体嗜碱性细胞"],"a":4,"e":"下丘脑促性腺激素释放激素经垂体门脉到达腺垂体，作用于远侧部嗜碱性促性腺激素细胞，促其分泌FSH和LH。"},{"q":"视泡发生于","o":["端脑","前脑","中脑","间脑","末脑"],"a":1,"e":"胚胎第4周前脑两侧壁向外膨出形成视泡，视泡内陷为视杯，视柄与间脑相连并演变为视神经。"},{"q":"心外膜内没有","o":["滋养血管","脂肪组织","结缔组织","心肌","平滑肌"],"a":3,"e":"心外膜为浆膜，由间皮和薄层结缔组织构成，内含血管、神经和脂肪，不含心肌，心肌仅存在于心肌膜。"},{"q":"近端小管上皮基部纵纹在电镜下的结构为","o":["大量纵向的小管和小泡","大量纵向的微管和微丝","许多侧突的分支","质膜内褶和纵向排列的杆状线粒体","质膜内褶和纵向排列的粗面内质网"],"a":3,"e":"近端小管基部质膜内褶与纵行排列的杆状线粒体共同构成光镜下的纵纹，扩大基底部面积利于物质转运。"},{"q":"呼吸性细支气管与终末细支气管的主要区别在于","o":["上皮细胞无纤毛","无杯状细胞","无混合腺","无软骨片","管壁有肺泡开口"],"a":4,"e":"呼吸性细支气管管壁已出现肺泡开口，兼有导气和换气功能；终末细支气管管壁完整，无肺泡开口。"},{"q":"肾叶的组成是","o":["两条髓放线之间的皮质迷路","每条髓放线及其周围的皮质迷路","一个肾锥体及其相连的皮质部分","一个肾锥体是一个肾小叶","一个集合管及其相通连的肾单位"],"a":2,"e":"一个肾锥体与其相连的皮质部分合称一个肾叶，一条髓放线及其周围的皮质迷路则为一个肾小叶。"},{"q":"阑尾炎手术时候，可根据结肠带寻找阑尾，结肠带是","o":["局部增厚的外纵肌","局部增厚的内环肌","增厚的黏膜肌","黏膜下层中的集合淋巴小结","聚集在外膜中的脂肪细胞"],"a":0,"e":"结肠外纵行肌局部增厚形成3条结肠带，内环行肌节段性增厚形成结肠袋，手术时可循结肠带寻找阑尾。"},{"q":"在HE染色的标本上某结构呈现蓝紫色，则表明该结构的化学性质是","o":["酸性","碱性","中性","嗜银性","异染性"],"a":0,"e":"苏木精为碱性染料，与组织中酸性物质如DNA、RNA结合呈蓝紫色，这种性质称嗜碱性。"},{"q":"关于骨细胞，下列哪项正确","o":["可同时存在于骨组织和骨膜","松质骨内不存在骨细胞","借缝隙连接与相邻骨细胞连接","粗面内质网和高尔基复合体发达","在骨的吸收过程中发挥主要作用"],"a":2,"e":"骨细胞胞体位于骨陷窝，突起伸入骨小管，相邻突起以缝隙连接相连，借以传递信息和交换物质。"},{"q":"关于脑垂体神经部的结构成分，哪项错误","o":["含赫林体","含分泌神经元胞体","含无髓神经纤维","含丰富的毛细血管网","含垂体细胞"],"a":1,"e":"神经垂体不含神经元胞体，只含下丘脑视上核和室旁核神经元的无髓轴突、赫林体及垂体细胞。"},{"q":"近端小管管壁上皮的钠泵位于","o":["微绒毛","杆状线粒体外膜","细胞侧突","细胞基部质膜","细胞游离面的质膜"],"a":3,"e":"近端小管基部质膜内褶处含丰富的Na+-K+-ATP酶即钠泵，位于细胞基部质膜，将细胞内Na+泵入间质。"},{"q":"巩膜来自于","o":["视杯周围间充质的内层","视杯周围间充质的外层","视杯口边缘部的间充质","晶状体周围的间充质","视柄周围的间充质"],"a":1,"e":"视杯周围间充质分内、外两层，内层分化为血管膜，外层分化为巩膜，角膜上皮则来自表面外胚层。"},{"q":"软骨的外加性生长不包括","o":["软骨膜内层骨祖细胞的分裂分化","减数分裂","新的基质和纤维的形成","向软骨组织表面添加新的软骨细胞","在发育中的软骨和成熟软骨中，均可见此种生长方式"],"a":1,"e":"外加性生长依靠软骨膜内骨祖细胞增殖分化为成软骨细胞，在软骨表面添加新基质，全程并无减数分裂。"},{"q":"从受精至胎儿娩出约经历","o":["36周","37周","38周","40周","42周"],"a":2,"e":"从受精之日算起至胎儿娩出约经38周即266天，比按末次月经首日推算的40周少约2周。"},{"q":"血液中数量最多的白细胞是","o":["中性粒细胞","淋巴细胞","单核细胞","嗜酸性粒细胞","嗜碱性粒细胞"],"a":0,"e":"中性粒细胞占白细胞总数的50%～70%，是数量最多的白细胞，核呈分叶状，具强趋化性和吞噬功能。"},{"q":"下列哪一项不属于畸形早发现、早诊断、早防治的常见检查手段","o":["羊水检查","绒毛膜检查","胎儿镜检查","超声检查","X线检查"],"a":4,"e":"产前诊断常用羊水检查、绒毛膜检查、胎儿镜和超声检查，X线检查有辐射致畸风险，不作常规筛查手段。"},{"q":"关于外耳的描述，哪项错误","o":["外耳道的皮肤内含皮脂腺，其分泌物为耵聍","耳廓以弹性软骨为支架","鼓膜为半透明薄膜","鼓膜外层上皮与外耳道表皮相延续","鼓膜内层由单层扁平上皮和薄层疏松结缔组织构成"],"a":0,"e":"外耳道皮肤内的耵聍腺属大汗腺，分泌耵聍，皮脂腺分泌皮脂，二者腺体性质和分泌物不同。"},{"q":"前神经孔未闭所致的畸形是","o":["无脑儿","脊柱裂","脊膜膨出","脊髓裂","脑积水"],"a":0,"e":"前神经孔未闭使颅侧神经管开放、脑组织暴露或缺如，形成无脑畸形，后神经孔未闭则致脊柱裂和脊髓裂。"},{"q":"环绕脑毛细血管形成胶质膜的细胞是","o":["神经膜细胞","星形胶质细胞","小胶质细胞","少突胶质细胞","室管膜细胞"],"a":1,"e":"星形胶质细胞突起末端膨大成脚板，附着于毛细血管表面形成胶质膜，是血-脑屏障的组成成分之一。"},{"q":"心肌纤维内没有","o":["横纹","糖原","脂滴","脂褐素","密体"],"a":4,"e":"密体和密斑是平滑肌细胞内的结构，参与细肌丝附着，心肌纤维有横纹、糖原、脂滴和脂褐素而无密体。"},{"q":"淋巴结深层皮质","o":["在被膜下，主要含T细胞","在皮质浅部，主要含B细胞","在皮质深部，主要含T细胞","在髓质浅部，主要含B细胞","在髓质深部，主要含T细胞"],"a":2,"e":"淋巴结副皮质区位于皮质深部，以T淋巴细胞为主，又称胸腺依赖区，内含高内皮微静脉。"},{"q":"微循环是指","o":["小动脉和小静脉之间的血液循环","微动脉和微静脉之间的血液循环","小动脉和毛细血管后微静脉之间的血液循环","微动脉和毛细血管后微静脉之间的血液循环","毛细血管和毛细血管后微静脉之间的血液循环"],"a":1,"e":"微循环指微动脉与微静脉之间的血液循环，是血液与组织进行物质交换的基本结构和功能单位。"},{"q":"下列哪项参与绒毛膜的形成","o":["外胚层","内胚层","中胚层","胚外中胚层","侧中胚层"],"a":3,"e":"绒毛膜由滋养层和衬于其内的胚外中胚层构成，绒毛干内的结缔组织和血管也来自胚外中胚层。"},{"q":"维生素A贮存于下列何种细胞内","o":["肝细胞","内皮细胞","肝巨噬细胞","贮脂细胞","淋巴细胞"],"a":3,"e":"贮脂细胞位于肝窦周隙，胞质含大量脂滴，人体70%～85%的维生素A贮存于此，机体需要时释放入血。"},{"q":"中肠袢在脐腔内旋转时围绕的血管是","o":["腹腔动脉","肠系膜上动脉","回结肠动脉","肠系膜下动脉","脐动脉"],"a":1,"e":"中肠袢以肠系膜上动脉为中轴，在脐腔内逆时针旋转90°，由矢状位转为水平位，随后返回腹腔。"},{"q":"有孔毛细血管存在于","o":["肌组织","中枢神经系统","肝","骨髓","胃肠黏膜"],"a":4,"e":"有孔毛细血管内皮细胞含窗孔，主要分布于胃肠黏膜、某些内分泌腺和肾血管球，利于中、小分子物质交换。"},{"q":"关于男性假两性畸形的描述，哪项正确","o":["同时具有睾丸和卵巢，外阴介于男女两性之间","只有卵巢，但外阴介于男女两性之间","只有睾丸，但外阴介于男女两性之间","只有卵巢，但外阴似男性","染色体有46，XX和46，XY两种组型"],"a":2,"e":"男性假两性畸形生殖腺为睾丸，核型46，XY，因雄激素分泌不足使外生殖器向女性方向不完全分化。"},{"q":"小肠绒毛是","o":["黏膜上皮向肠腔伸出的指状突起","黏膜及黏膜下层向肠腔伸出的突起","上皮细胞表面的小突起","上皮与固有层共同向肠腔突出而形成","上皮、固有层及黏膜肌层共同向肠腔突出而形成"],"a":3,"e":"小肠绒毛由上皮和固有层共同向肠腔突起形成，中轴固有层内含中央乳糜管和丰富的毛细血管网。"},{"q":"关于垂体后叶赫林体特征中，哪项是正确的","o":["为嗜碱性团块","为板层状小体","能产生血管升压素","能贮存催乳素","能贮存视上核和室旁核分泌的激素"],"a":4,"e":"赫林体是下丘脑视上核和室旁核神经元轴突内激素颗粒的聚集，贮存血管升压素和催产素，并非腺细胞分泌。"},{"q":"杯状细胞的特点是","o":["分布于胃肠黏膜上皮中","胞质内充满酶原颗粒","细胞核大，染色淡","细胞不贴附于基膜","起润滑和保护的作用"],"a":4,"e":"杯状细胞分泌黏蛋白，与水结合成黏液覆盖上皮表面，起润滑和保护作用，其核小、染色深、位于基底部。"},{"q":"关于弹性纤维的描述，不正确的是","o":["在三种纤维中，数量最多","由弹性蛋白和微原纤维构成","可有分支，交织成网","可被醛复红染为紫色","于HE染色切片难与胶原纤维区别"],"a":0,"e":"三种纤维中胶原纤维数量最多，弹性纤维较少，由弹性蛋白和微原纤维构成，可被醛复红染成紫色。"},{"q":"汗腺属于","o":["单泡状腺","复泡状腺","单管泡状腺","复管泡状腺","单曲管状腺"],"a":4,"e":"汗腺为单曲管状腺，分泌部盘曲成团位于真皮深层和皮下组织，导管不分支，直接开口于皮肤表面。"},{"q":"分泌黄体酮的细胞是","o":["膜细胞","颗粒细胞","膜黄体细胞","颗粒黄体细胞","门细胞"],"a":3,"e":"颗粒黄体细胞数量多、体积大、着色浅，位于黄体中央，主要分泌孕激素和松弛素，膜黄体细胞协同分泌雌激素。"},{"q":"红细胞脱去细胞核发生在","o":["原红细胞","早幼红细胞","中幼红细胞","晚幼红细胞","网织红细胞"],"a":3,"e":"晚幼红细胞的核致密固缩后脱出，成为网织红细胞，脱出的核由巨噬细胞吞噬，网织红细胞入血后成熟。"},{"q":"关于垂体的发生，下列哪项错误","o":["来自外胚层和神经外胚层","由拉特克氏囊和神经垂体芽共同发育而成","拉特克氏囊腔将大部分消失，仅留一小裂隙","神经垂体芽中神经元较少","腺垂体可分化出多种腺细胞"],"a":3,"e":"神经垂体芽只发育为神经垂体，内含下丘脑神经元轴突和垂体细胞，神经元胞体位于下丘脑，不在其中。"},{"q":"内、中、外三个胚层均起源于","o":["胚外中胚层","胚内中胚层","上胚层","下胚层","滋养层"],"a":2,"e":"上胚层细胞经原条迁移形成中胚层和内胚层，原上胚层改称外胚层，故三个胚层均起源于上胚层。"},{"q":"关于皮肤真皮的描述，正确的是","o":["由角化的复层扁平上皮构成","由上皮组织和结缔组织共同构成","由结缔组织构成","为上皮组织的基膜","由平滑肌组织构成"],"a":2,"e":"真皮位于表皮下方，由乳头层和网织层的结缔组织构成，不含上皮，表皮才由角化复层扁平上皮构成。"},{"q":"关于鼻的呼吸部，错误的是","o":["呼吸部占鼻黏膜的大部分","固有层内有较多的腺体","假复层纤毛柱状上皮的纤毛向外鼻孔摆动","有较多的静脉丛","有温暖湿润空气的作用"],"a":2,"e":"鼻呼吸部纤毛向咽部摆动，将黏液及黏附的尘埃、细菌推向咽部排出，向外鼻孔摆动则无法清除异物。"},{"q":"胞质颗粒内含组胺的细胞是","o":["浆细胞","巨噬细胞","肥大细胞","成纤维细胞","脂肪细胞"],"a":2,"e":"肥大细胞胞质充满粗大的嗜碱性颗粒，颗粒内含组胺、肝素等，并合成白三烯，参与过敏反应和炎症。"},{"q":"增生期通常是月经周期的","o":["第1～5天","第4～14天","第5～14天","第5～15天","第5～16天"],"a":2,"e":"增生期指月经周期第5～14天，在雌激素作用下内膜基底层增生修复，由约1mm增厚至2～4mm。"},{"q":"关于消化管的外膜描述，错误的是","o":["咽和食管为纤维膜","胃、空肠、回肠为浆膜","十二指肠、升结肠和降结肠的前壁为浆膜","盲肠、横结肠和乙状结肠为浆膜","十二指肠、升结肠和降结肠的前壁为纤维膜"],"a":4,"e":"升结肠和降结肠前壁为浆膜、后壁为纤维膜，十二指肠大部为纤维膜，故三者前壁均为纤维膜的说法错误。"},{"q":"纤毛可见于","o":["小肠上皮","气管上皮","变移上皮","口腔上皮","血管内皮"],"a":1,"e":"纤毛为上皮细胞游离面的运动性突起，见于呼吸道的假复层纤毛柱状上皮，如气管上皮；小肠为微绒毛。"},{"q":"肾上腺皮质球状带","o":["较厚，分泌盐皮质激素","较薄，分泌盐皮质激素","较厚，分泌糖皮质激素","较薄，分泌糖皮质激素","较薄，分泌性激素"],"a":1,"e":"球状带位于被膜下，最薄，细胞聚集成球团状，分泌醛固酮等盐皮质激素，受肾素-血管紧张素系统调节。"},{"q":"患过敏性鼻炎时，鼻分泌物内可见","o":["T淋巴细胞","嗜碱性粒细胞","红细胞","单核细胞","巨噬细胞"],"a":1,"e":"过敏性鼻炎属Ⅰ型超敏反应，嗜碱性粒细胞和肥大细胞脱颗粒释放组胺，故鼻分泌物中可检出嗜碱性粒细胞。"},{"q":"骨陷窝和骨小管内有","o":["骨细胞","毛细血管","组织液","骨细胞和组织液","血液"],"a":3,"e":"骨细胞胞体居于骨陷窝，突起位于骨小管，腔内含少量组织液，故骨陷窝和骨小管内为骨细胞和组织液。"},{"q":"关于胃肠道内分泌细胞，下列错误的是","o":["分布于上皮与腺体中","有基底侧突与邻近细胞相接触","在HE染色切片上容易辨认","底部胞质含大量分泌颗粒","分开放型与封闭型两类"],"a":2,"e":"胃肠内分泌细胞多单个夹于上皮细胞间，胞质染色浅淡，需银染或免疫组化才能辨认，HE切片上难以区分。"},{"q":"红细胞的血红蛋白可以携带","o":["大量一氧化碳","氧和少量二氧化碳","部分一氧化碳和全部二氧化碳","全部二氧化碳","不包括二氧化碳"],"a":1,"e":"血红蛋白的珠蛋白与氧结合形成氧合血红蛋白，同时可结合少量二氧化碳形成氨基甲酰血红蛋白。"},{"q":"关于嗜碱性粒细胞，描述正确的是","o":["占白细胞总数的比例最高","细胞质含大量溶酶体","胞核呈圆形","胞质中含嗜碱性特殊颗粒","在急性细菌性感染疾病时明显增多"],"a":3,"e":"嗜碱性粒细胞胞质含粗大的嗜碱性特殊颗粒，颗粒内含肝素、组胺等，数量最少，参与过敏反应。"},{"q":"垂体远侧部腺细胞主要受下列哪种激素调节","o":["结节部分泌的激素","下丘脑弓状核分泌的激素","下丘脑室旁核分泌的激素","神经垂体分泌的激素","下丘脑视上核分泌的激素"],"a":1,"e":"下丘脑弓状核等核团的神经元分泌释放激素或抑制激素，经垂体门脉系统到达远侧部，调节各种腺细胞的分泌。"},{"q":"组成脾白髓的结构有","o":["脾索和淋巴小结","脾索和脾血窦","血窦和边缘窦","脾血窦和动脉周围淋巴鞘","动脉周围淋巴鞘和淋巴小结"],"a":4,"e":"脾白髓由动脉周围淋巴鞘、淋巴小结和边缘区构成，红髓由脾索和脾血窦构成，前者以T细胞为主。"},{"q":"喉气管憩室将发育为","o":["喉和气管","喉、气管和支气管","喉、气管、支气管和肺","气管、支气管和肺","支气管和肺"],"a":2,"e":"喉气管憩室上端发育为喉，中段发育为气管，末端肺芽分支形成支气管和肺，故四者同源。"},{"q":"与厚表皮比较，薄表皮缺少以下哪一层","o":["透明层","基底层","角化层","棘层","颗粒层"],"a":0,"e":"厚表皮分基底层、棘层、颗粒层、透明层和角质层5层，薄表皮的颗粒层和透明层均不明显，故缺透明层。"},{"q":"大脑皮质多形细胞层的细胞主要有","o":["水平细胞","梭形细胞","篮状细胞","星形细胞","颗粒细胞"],"a":1,"e":"多形细胞层以梭形细胞为主，另有锥体细胞和上行轴突细胞，是大脑皮质最深层，其轴突进入白质组成投射纤维。"},{"q":"胞质内有大量粗面内质网、游离核糖体和高尔基复合体的细胞是","o":["未分化的间充质细胞","骨原细胞（或骨祖细胞）","骨细胞","破骨细胞","成骨细胞"],"a":4,"e":"成骨细胞分泌类骨质，胞质含大量粗面内质网、游离核糖体和发达的高尔基复合体，HE染色呈强嗜碱性。"},{"q":"巨噬细胞可延化学物质的浓度梯度朝浓度高的部位定向移动，聚集到产生和释放这些物质的部位，这种特点是","o":["吞噬作用","趋化性","抗原呈递作用","分泌功能","变形特性"],"a":1,"e":"巨噬细胞沿趋化因子浓度梯度定向移动并聚集的特性称趋化性，是其发挥吞噬和免疫应答功能的前提。"},{"q":"食管腺","o":["为纯浆液性腺","为管状腺","分泌淀粉酶","位于固有层","位于黏膜下层"],"a":4,"e":"食管腺为黏液腺，位于黏膜下层，导管穿过黏膜开口于食管腔，分泌黏液润滑食管便于食物通过。"},{"q":"对伊红亲和力强的结构是","o":["细胞膜","细胞质","细胞核膜","细胞核","核糖体"],"a":1,"e":"伊红为酸性染料，与细胞质中的碱性蛋白质结合呈红色，故对伊红亲和力强者为细胞质，此即嗜酸性。"},{"q":"可见浆半月的是","o":["胰腺和舌下腺","腮腺和下颌下腺","胰腺和腮腺","腮腺和舌下腺","舌下腺和下颌下腺"],"a":4,"e":"浆半月是混合腺泡中浆液细胞覆盖于黏液细胞表面形成的半月状结构，见于下颌下腺和舌下腺，腮腺为纯浆液腺。"},{"q":"产生肾上腺素的细胞是","o":["嗜铬细胞","肾上腺束状带细胞","肾上腺球状带细胞","肾上腺网状带细胞","交感神经节细胞"],"a":0,"e":"肾上腺髓质嗜铬细胞含电子密度高的分泌颗粒，多数为肾上腺素细胞，分泌肾上腺素，受交感神经节前纤维支配。"},{"q":"箭头所指细胞的功能是","o":["吞噬抗原","分泌抗体","分泌穿孔素杀伤感染细胞","分泌肝素、白三烯等生物活性物质","生成网状纤维"],"a":1,"e":"官方题库缺失图片"},{"q":"要检测某一组织中是否含有特定的某一非糖蛋白类的蛋白质，并要对该蛋白质进行细胞定位，最佳的检测技术是","o":["扫描电镜技术","PAS反应","孚尔根（Feulgen）反应","免疫组织化学术","原位杂交术"],"a":3,"e":"免疫组织化学依据抗原与抗体特异性结合的原理，用标记抗体在切片上原位显示肽和蛋白质，可定性、定位。"},{"q":"下列哪种细胞在功能活跃状态下可形成皱褶缘","o":["软骨细胞","骨祖细胞","成骨细胞","骨细胞","破骨细胞"],"a":4,"e":"破骨细胞功能活跃时，贴近骨组织一侧的细胞膜形成许多不规则的皱褶缘，释放水解酶和有机酸溶解骨质。"},{"q":"大动脉管壁的主要结构特点是","o":["弹性膜和弹性软骨多","弹性纤维和胶原纤维多","弹性膜和弹性纤维多","弹性纤维和平滑肌纤维多","胶原纤维多"],"a":2,"e":"大动脉中膜含多层弹性膜和大量弹性纤维，平滑肌少，故称弹性动脉，可缓冲收缩压并维持舒张期血流。"},{"q":"排卵时卵母细胞处于","o":["第一次减数分裂前期","第一次减数分裂中期","第二次减数分裂前期","第二次减数分裂中期","第二次减数分裂末期"],"a":3,"e":"排卵前初级卵母细胞完成第一次减数分裂，次级卵母细胞随即进入第二次减数分裂并停滞于中期，排卵即排出该细胞。"},{"q":"内、外弹性膜均明显的血管是","o":["大静脉","中静脉","小静脉","大动脉","中动脉"],"a":4,"e":"中动脉内弹性膜明显，较大者中膜与外膜交界处有断续的外弹性膜，大动脉内弹性膜不明显，静脉多无内外弹性膜。"},{"q":"关于螺旋器的结构，哪项错误","o":["位于膜蜗管的基底膜上","由支持细胞和毛细胞组成","支持细胞主要有柱细胞和指细胞","柱细胞的胞质内有丰富的张力原纤维，起支持作用","毛细胞顶部的静纤毛伸入壶腹帽的胶质内"],"a":4,"e":"螺旋器毛细胞的静纤毛插入盖膜的胶质内，壶腹嵴毛细胞的纤毛才插入壶腹帽，两者位置不同。"},{"q":"来自内、中、外三个胚层的是","o":["外耳道","鼓膜","咽鼓管","听小骨","膜蜗管"],"a":1,"e":"鼓膜外层来自第1鳃沟外胚层，内层来自第1咽囊内胚层，中层结缔组织来自间充质，故由三个胚层参与形成。"},{"q":"有关位觉和听觉感受器，哪项错误","o":["均有毛细胞","均有感觉神经元","均有柱形支持细胞","均有传入神经末梢","表面均有胶状物覆盖"],"a":1,"e":"位觉斑、壶腹嵴和螺旋器均由毛细胞与支持细胞构成，感觉神经元胞体位于神经节，不属于感受器本身。"},{"q":"视杆细胞和视锥细胞来自胚胎的","o":["视柄","视杯外层","视杯内、外两层","视杯内层","晶状体泡"],"a":3,"e":"视杯内层增厚分化为节细胞、视锥细胞、视杆细胞和双极细胞等，视杯外层只分化为色素上皮层。"},{"q":"关于眼球壁血管膜的分部，哪项正确","o":["血管层、色素上皮层、睫状体","虹膜、睫状体、脉络膜","睫状体、脉络膜、色素上皮层","血管层、睫状体、色素上皮层","虹膜、血管层、睫状体"],"a":1,"e":"血管膜自前向后分为虹膜、睫状体和脉络膜三部分，均由富含血管和黑素细胞的疏松结缔组织构成。"},{"q":"在肝纤维化病变中，贮脂细胞的作用类似于","o":["单泡脂肪细胞","多泡脂肪细胞","肝巨噬细胞","成纤维细胞","肥大细胞"],"a":3,"e":"病理时贮脂细胞增殖并转化为成纤维细胞，合成胶原增多，参与肝纤维化，故其作用类似成纤维细胞。"},{"q":"用煌焦油蓝染色呈细网状的血细胞是","o":["红细胞","淋巴细胞","单核细胞","网织红细胞","中性粒细胞"],"a":3,"e":"网织红细胞胞质内残留部分核糖体，用煌焦油蓝染色呈细网状，成年人占红细胞总数的0.5%～1.5%。"},{"q":"消化管的上皮来源于","o":["内胚层","外胚层","胚内中胚层","胚外中胚层","间介中胚层"],"a":0,"e":"原始消化管上皮由内胚层分化，故咽以下的消化管和消化腺上皮均来源于内胚层，仅口腔和肛管下段来自外胚层。"},{"q":"气管上皮由以下哪组细胞组成","o":["纤毛细胞、杯状细胞、基细胞、克拉拉细胞","柱状细胞、杯状细胞、基底细胞、潘氏细胞、小颗粒细胞","纤毛细胞、杯状细胞、梭形细胞、刷细胞、颗粒细胞","纤毛细胞、杯状细胞、基底细胞、刷细胞、小颗粒细胞","柱状细胞、壁细胞、基细胞、杯状细胞、刷细胞"],"a":3,"e":"气管上皮为假复层纤毛柱状上皮，由纤毛细胞、杯状细胞、刷细胞、基细胞和小颗粒细胞组成。"},{"q":"有关胃底腺的主细胞，哪项正确","o":["主要分布在胃底腺上部","分泌胃蛋白酶","分泌胃蛋白酶原","分泌内因子","大量粗面内质网聚集于顶部胞质"],"a":2,"e":"主细胞分布于胃底腺下半部，胞质基部强嗜碱性，顶部充满酶原颗粒，分泌胃蛋白酶原，经盐酸激活为胃蛋白酶。"},{"q":"心球的一部分参与形成","o":["左心室","右心室","左心房","右心房","静脉窦"],"a":1,"e":"心球尾段膨大后被心室吸收，成为原始右心室，原心室成为原始左心室，心球其余部分参与动脉干形成。"},{"q":"在化学突触的突触前成分胞质内，含神经递质的结构是","o":["突触小泡","微丝","微管","线粒体","滑面内质网"],"a":0,"e":"突触小泡内含神经递质或神经调质，表面借突触素附着于细胞骨架，冲动到达时与突触前膜融合释放递质。"},{"q":"出生后血循环发生变化的主要原因是","o":["动脉导管的闭锁","静脉导管的闭锁","卵圆孔的关闭","左右心房不再相通","胎盘血循环中断和肺开始呼吸"],"a":4,"e":"出生后胎盘循环中断、肺开始呼吸，使体循环阻力升高、肺循环开放，继发卵圆孔和动脉导管关闭。"},{"q":"对神经元描述错误的是","o":["细胞核大，染色淡，核仁明显","胞质含嗜酸性的尼氏体","硝酸银染色可见胞体和突起内含神经原纤维","突起可分为轴突和树突","可接受刺激，产生和传导冲动"],"a":1,"e":"尼氏体由粗面内质网和游离核糖体构成，呈强嗜碱性，可被苏木精染成蓝紫色，并非嗜酸性。"},{"q":"生后肾原基可演变为","o":["肾盂","肾盏","集合小管","输尿管","肾小管"],"a":4,"e":"生后肾组织形成肾小管，其一端膨大凹陷包绕毛细血管球形成肾小体，集合小管、肾盂和肾盏则来自输尿管芽。"},{"q":"关于甲状腺滤泡旁细胞的描述，正确的是","o":["胞质内有嗜银颗粒，分泌物多由细胞基底面释放","胞质内有嗜银颗粒，分泌物多由细胞顶部释放","胞质内有嗜铬颗粒，分泌物多由细胞侧面释放","胞质内有嗜铬颗粒，分泌物多由细胞顶部释放","胞质内有嗜铁颗粒，分泌物多由细胞基底面释放"],"a":0,"e":"滤泡旁细胞体积较大、着色浅，镀银染色胞质内有黑色嗜银颗粒，分泌降钙素，颗粒多由细胞基底面释放。"},{"q":"被覆肾盂和肾盏腔面的上皮是","o":["单层柱状上皮","复层柱状上皮","假复层柱状上皮","复层扁平上皮","变移上皮"],"a":4,"e":"肾盏、肾盂、输尿管和膀胱的腔面均被覆变移上皮，细胞层数随器官空虚或充盈状态而改变。"},{"q":"内耳上皮来源于","o":["表面外胚层","神经外胚层","内胚层","菱脑两侧壁的神经细胞","间充质"],"a":0,"e":"内耳膜迷路上皮由菱脑两侧表面外胚层增厚形成的听板、听窝和听泡演变而来，骨迷路则由周围间充质分化。"},{"q":"上皮细胞侧突最发达的是","o":["近端小管","远端小管","细段","直集合管","弓形集合管"],"a":0,"e":"近端小管上皮细胞侧面伸出许多侧突相互嵌合，使细胞分界不清并扩大侧面面积，为各段肾小管中最发达者。"},{"q":"血-睾屏障结构异常，会导致精子抗原物质溢出到生精小管外而发生自体免疫反应，从而引起男性不育。关于血-睾屏障的叙述，哪项是正确的","o":["是支持细胞间的紧密连接构成","是由生精上皮、基膜和支持细胞的紧密连接构成","防止细菌侵入生精小管影响精子发生","血-睾屏障影响生精小管的雄激素浓度，不利于精子发生","是由毛细血管内皮及基膜、结缔组织、生精上皮基膜和支持细胞间紧密连接构成"],"a":4,"e":"血-睾屏障由毛细血管内皮及基膜、结缔组织、生精上皮基膜和支持细胞间紧密连接构成，维持生精微环境。"},{"q":"关于嫌色细胞的描述，错误的是","o":["细胞体积小","细胞着色浅","细胞数量较多","分布于腺垂体","属于神经胶质细胞"],"a":4,"e":"嫌色细胞是腺垂体远侧部体积小、着色浅、数量较多的腺细胞，其功能尚不清楚，不属于神经胶质细胞。"},{"q":"次级卵母细胞的第二次减数分裂完成时间和部位是","o":["排卵前；卵巢内","受精前；输卵管外","排卵时；输卵管内","受精时；输卵管内","受精时；子宫腔内"],"a":3,"e":"次级卵母细胞停滞于第二次减数分裂中期，受精时被精子穿入激发才完成分裂，部位在输卵管壶腹部。"},{"q":"哪一项不是血-胸腺屏障的组成","o":["连续型毛细血管和内皮细胞间的紧密连接","内皮细胞周围不连续的基膜","血管周隙及其内含的巨噬细胞","胸腺上皮细胞基膜","连续的胸腺上皮细胞突起"],"a":1,"e":"血-胸腺屏障的内皮周围基膜是连续的，不连续基膜见于其他部位，故该项不属于其组成。"},{"q":"下列细胞分化方向正确的是","o":["骨祖细胞→成软骨细胞→骨细胞","成骨细胞→破骨细胞","单核细胞→破骨细胞","成软骨细胞→软骨细胞→破骨细胞","骨祖细胞→成骨细胞→软骨细胞"],"a":2,"e":"破骨细胞为多核巨细胞，一般认为由多个单核细胞融合而成，骨祖细胞只分化为成骨细胞和成软骨细胞。"},{"q":"胞质内含嗜碱性分泌颗粒的细胞是","o":["成纤维细胞","浆细胞","巨噬细胞","纤维细胞","肥大细胞"],"a":4,"e":"肥大细胞胞质内充满粗大的嗜碱性分泌颗粒，可被醛复红染成紫色，颗粒含组胺、肝素等活性物质。"},{"q":"关于缝隙连接的特点哪项错误","o":["也见于心肌细胞之间","由6个柱状亚单位组成，中央有小管通连","未连接处相邻细胞间有狭小间隙","相邻细胞间有许多细丝相连","有传递化学信息和电冲动作用"],"a":3,"e":"缝隙连接处相邻细胞膜间仅3nm，由6个连接蛋白亚单位围成中央小管，细胞间有细丝相连的是黏着小带。"},{"q":"长骨增长的主要原因是","o":["初级骨化中心的出现","骺板软骨的不断生长和骨化","次级骨化中心的出现","骨膜内成骨细胞的成骨","骨领的出现"],"a":1,"e":"长骨加长依靠骺板软骨不断增生并替换成骨，骺板保留于骨骺与骨干之间，是长骨延长的结构基础。"},{"q":"对消化管皱襞形成的正确描述是","o":["上皮突向管腔","上皮和固有层突向管腔","上皮、固有层和黏膜肌层突向管腔","黏膜和部分黏膜下层突向管腔","黏膜、黏膜下层和肌层突向管腔"],"a":3,"e":"皱襞由黏膜和部分黏膜下层共同向管腔突出形成，可扩大黏膜表面积，绒毛则仅由上皮和固有层构成。"},{"q":"对于球旁细胞的最佳描述是","o":["由入球微动脉的平滑肌细胞分化而成","由肾小囊壁层的上皮细胞分化而成","形成致密斑","由入球微动脉的内皮细胞分化而成","分泌抗利尿激素"],"a":0,"e":"球旁细胞由入球微动脉近血管极处的平滑肌细胞分化为上皮样细胞，胞质含分泌颗粒，分泌肾素。"},{"q":"甲状腺滤泡上皮来源于","o":["表面外胚层","神经外胚层","中胚层","内胚层","间充质"],"a":3,"e":"甲状腺原基由原始咽底壁内胚层上皮向腹侧下陷形成，滤泡上皮由该内胚层分化而来，属咽喉以下消化管衍生的上皮组织。"},{"q":"神经嵴演化所形成的结构是","o":["脑神经节、肾上腺嗜铬细胞","脊神经节、小脑","脑神经节、脑垂体","脊神经节、髓核","脊神经节、肾上腺皮质"],"a":0,"e":"神经嵴细胞分化为脑神经节、脊神经节等感觉神经节细胞及施万细胞，部分迁入肾上腺原基分化为髓质嗜铬细胞，故脑神经节与嗜铬细胞均源自神经嵴。"},{"q":"胰腺炎是胰腺因蛋白酶的自身消化作用而引起的疾病，导致胰腺炎的蛋白酶源自","o":["胃底腺的主细胞合成分泌","胃底腺的壁细胞合成分泌","胰腺的腺泡合成分泌","肝细胞合成分泌","小肠腺潘氏细胞合成分泌"],"a":2,"e":"胰腺外分泌部腺泡细胞合成并以酶原形式分泌胰蛋白酶原等消化酶，酶原进入小肠后被肠激酶激活，若在腺内提前活化即自身消化胰腺组织。"},{"q":"胰岛PP细胞分泌","o":["胰高血糖素","胰岛素","生长抑素","胰多肽","促胰液素"],"a":3,"e":"胰岛PP细胞分泌胰多肽，抑制胃肠运动、胰液分泌和胆囊收缩；胰高血糖素来自A细胞，胰岛素来自B细胞，生长抑素来自D细胞。"},{"q":"肝小叶内不与血浆接触的是","o":["肝细胞血窦面的微绒毛","库普弗细胞","肝细胞胆小管面的微绒毛","肝血窦内皮细胞","贮脂细胞"],"a":2,"e":"胆小管由相邻肝细胞质膜局部凹陷围成，仅与胆汁相通；血窦面微绒毛、内皮细胞、库普弗细胞和贮脂细胞均位于血窦侧或窦周隙，可与血浆接触。"},{"q":"间皮可见于","o":["肺泡上皮","腹膜腔表面","血管外表面","心脏内表面","肾小囊壁层"],"a":1,"e":"间皮为衬于胸膜、腹膜和心包膜表面的单层扁平上皮，由中胚层分化而来，可使器官表面光滑并减少相互摩擦。"},{"q":"参与心房分隔的结构有","o":["第一房间隔和第二房间隔","房间隔和心内膜垫","房间隔和动脉干嵴","房间隔和室间隔膜部","房间隔和心球嵴"],"a":1,"e":"第一、第二房间隔共同构成房间隔，其游离缘须与心内膜垫融合才能封闭第一房间孔，故心房分隔由房间隔与心内膜垫协同完成。"},{"q":"与鼻腔形成有关的结构是","o":["内侧鼻突","外侧鼻突","鼻窝","口咽膜","正中腭突"],"a":2,"e":"鼻窝向深部扩大形成原始鼻腔，其上方的额鼻突与内、外侧鼻突参与鼻梁和鼻翼塑形，鼻窝是原始鼻腔及外鼻孔形成的直接始基。"},{"q":"肝小叶缺血性坏死通常先发生于小叶中央部位，与此现象无关的血流因素是","o":["携带丰富营养物质的门静脉分支形成小叶间静脉","携带丰富氧气的肝动脉分支形成小叶间动脉","源于小叶间静脉的血液注入肝血窦","源于小叶间动脉的血液注入肝血窦","中央静脉的血液汇入小叶下静脉"],"a":4,"e":"小叶间静脉与动脉带来的血经肝血窦流向中央静脉，使小叶中央最先受到缺血缺氧影响；中央静脉汇入小叶下静脉属流出途径，与中央带易坏死无关。"},{"q":"关于肾上腺网状带的特征，哪项是错误的","o":["细胞索吻合成网状","网孔中有窦状毛细血管","胞质的脂滴含量是三个带中最多的","具有分泌类固醇激素细胞的超微结构特征","可分泌雄激素"],"a":2,"e":"网状带细胞脂滴含量较少，脂滴最丰富的是束状带细胞；网状带细胞索吻合成网、网孔内有窦状毛细血管，具类固醇激素分泌细胞特征并分泌雄激素。"},{"q":"鼻呼吸部黏膜不具备哪个结构特点","o":["上皮为复层扁平上皮","生活状态的黏膜呈淡红色","固有层的静脉丛丰富","固有层有丰富的淋巴组织","固有层内有丰富的腺体"],"a":0,"e":"鼻呼吸部黏膜为假复层纤毛柱状上皮，固有层含丰富静脉丛、腺体和淋巴组织，故活体黏膜呈淡红色；复层扁平上皮见于鼻前庭。"},{"q":"心肌的二联体位于","o":["A带和I带交界处","Z线","H带","M线","A带中间"],"a":1,"e":"心肌横小管较粗，位于Z线水平，与一侧终池相贴构成二联体；位于明暗带交界处并与两侧终池构成三联体是骨骼肌的特点。"},{"q":"形成女性生殖管道的结构是","o":["中肾旁管","中肾管","中肾小管","前肾管","尿生殖窦"],"a":0,"e":"中肾旁管又称米勒管，上段和中段演化为输卵管，下段左右合并形成子宫及阴道穹；中肾管在女性因缺乏雄激素而退化。"},{"q":"Turner综合征属于","o":["性染色体单体型","性染色体三体型","常染色体数目增多","常染色体数目减少","染色体结构畸变"],"a":0,"e":"Turner综合征核型为45，X，少一条性染色体，属性染色体单体型，患者卵巢发育不全、条索状性腺并呈女性表型。"},{"q":"泄殖腔是","o":["后肠末段膨大","原始直肠末段膨大","尿囊末段膨大","尿生殖窦末段膨大","由后肠与尿囊汇合形成"],"a":0,"e":"泄殖腔为后肠末段膨大而成，腹侧头端与尿囊相连、尾端以泄殖腔膜封闭，后被尿直肠隔分隔为尿生殖窦与原始直肠。"},{"q":"睾丸内吞噬并消化精子残余胞质的细胞是","o":["精原细胞","精子细胞","管周肌样细胞","间质细胞","支持细胞"],"a":4,"e":"支持细胞位于生精上皮内，侧面镶嵌各级生精细胞，能吞噬并消化精子形成过程中脱落的残余胞质，还参与构成血-睾屏障。"},{"q":"在骨骼肌纤维收缩过程中","o":["肌膜的兴奋直接传向肌浆网","大量钙离子从肌浆转入肌浆网内","细肌丝向A带内滑入","A带变窄","粗肌丝变短"],"a":2,"e":"肌丝滑行时细肌丝向M线方向滑入A带内，A带长度不变而I带和H带缩短；兴奋经横小管传至肌浆网，引起Ca2+释放而非回摄。"},{"q":"食管黏膜上皮及食管腺源于","o":["外胚层","胚内中胚层","胚外中胚层","内胚层","间充质"],"a":3,"e":"食管黏膜上皮与食管腺均属消化管黏膜上皮和腺上皮，由原始消化管内胚层分化；结缔组织、肌组织和血管内皮则来自中胚层。"},{"q":"大脑皮质的主要神经元有","o":["锥体细胞和梨状细胞","锥体细胞和星形细胞","锥体细胞和篮状细胞","锥体细胞和颗粒细胞","颗粒细胞和水平细胞"],"a":3,"e":"大脑皮质神经元以锥体细胞和颗粒细胞为主，锥体细胞分大、中、小三级，颗粒细胞属高尔基Ⅱ型中间神经元，构成皮质内局部环路。"},{"q":"下列关于浅表肾单位的描述，下列哪项是正确的","o":["发生早，数量多，分布在皮质浅层和中层，肾小体小，肾单位髓袢较短","发生早，数量少，分布在皮质浅层和中层，肾小体小，肾单位髓袢较短","发生晚，数量少，分布在皮质浅层和中层，肾小体小，肾单位髓袢较长","发生晚，数量多，分布在皮质浅层和中层，肾小体小，肾单位髓袢较短","发生晚，数量多，分部在皮质浅层和中层，肾小体大，肾单位髓袢较短"],"a":3,"e":"浅表肾单位发生较晚、数量多，约占85%，肾小体位于皮质浅层和中层、体积小、髓袢短，是尿液形成的主要部位；髓旁肾单位则相反。"},{"q":"汗腺的肌上皮细胞分布于","o":["导管上皮细胞间","导管上皮细胞与基膜间","分泌部上皮细胞间","分泌部上皮细胞与基膜间","导管和分泌部上皮细胞与基膜间"],"a":3,"e":"汗腺肌上皮细胞位于腺细胞与基膜之间，胞质含肌动蛋白丝，收缩时挤压分泌部排出分泌物，其位置不在导管上皮细胞之间。"},{"q":"光镜下所见的纹状缘和刷状缘，电镜下观察是密集排列的","o":["微丝","微管","微绒毛","纤毛","张力丝"],"a":2,"e":"纹状缘与刷状缘均由密集整齐排列的微绒毛构成，微绒毛直径约0.1μm，内含纵行微丝，可显著扩大细胞游离面的表面积。"},{"q":"软骨和骨中含有血管的结构是","o":["软骨陷窝","骨陷窝","中央管","骨小管","软骨囊"],"a":2,"e":"中央管内含结缔组织、血管、神经及骨祖细胞等，是密质骨中含血管的管道；软骨陷窝、骨陷窝、骨小管和软骨囊内均无血管。"},{"q":"尿直肠隔起源于","o":["泄殖腔与尿囊之间的间充质","泄殖腔与尿生殖窦之间的间充质","后肠与尿囊起始部之间的间充质","直肠与尿囊之间的间充质","泄殖腔与直肠之间的间充质"],"a":2,"e":"尿直肠隔由尿囊与后肠之间的间充质增生形成，呈镰状突入泄殖腔并与泄殖腔膜融合，将其分隔为腹侧尿生殖窦和背侧原始直肠。"},{"q":"关于巩膜的描述，哪项错误","o":["主要由致密结缔组织构成","呈乳白色，坚韧而不透明","维持眼球形状及保护眼内含物","无血管和神经","是纤维膜的大部分"],"a":3,"e":"巩膜由致密结缔组织构成，呈瓷白色、坚韧不透明，占纤维膜后5/6，其表层有血管和神经穿行，并非无血管神经。"},{"q":"下列哪种结构为完整的细胞","o":["胶原纤维","弹性纤维","肌纤维","神经纤维","网状纤维"],"a":2,"e":"肌纤维即肌细胞，胞质含肌丝，是完整的细胞；胶原纤维、弹性纤维和网状纤维为细胞外基质，神经纤维由轴突及包绕的胶质细胞构成。"},{"q":"关于胰岛的特征，哪项错误","o":["由内分泌细胞组成","HE切片中可分辨出A、B、D、PP四型细胞","细胞间有丰富的毛细血管","胰岛大小不等","成团位于腺泡之间"],"a":1,"e":"胰岛A、B、D、PP四型细胞在HE染色下形态相似、难以区分，需用免疫组织化学或特殊染色鉴别；胰岛大小不等，细胞间有丰富有孔毛细血管。"},{"q":"能分泌抗中肾旁管激素的细胞是","o":["卵巢的卵原细胞","卵巢的卵泡细胞","睾丸的精原细胞","睾丸支持细胞","睾丸间质细胞"],"a":3,"e":"睾丸支持细胞分泌抗中肾旁管激素，使中肾旁管退化；间质细胞分泌雄激素，促使中肾管发育为附睾管、输精管、精囊和射精管。"},{"q":"肾上腺盐皮质激素作用于肾脏的","o":["近端小管曲部","远端小管曲部","细段","近端小管直部","远端小管直部"],"a":1,"e":"盐皮质激素促进肾远端小管曲部和集合管重吸收Na+并排出K+，故其靶细胞位于远曲小管；近端小管以重吸收水和营养物质为主。"},{"q":"胃溃疡时，胃黏膜黏液碳酸氢盐屏障受到破坏，胃酸和活化的胃蛋白酶损伤胃黏膜，其中参与分泌胃黏膜表面黏液的细胞是","o":["主细胞","壁细胞","颈黏液细胞","内分泌细胞","表面黏液细胞"],"a":4,"e":"胃黏膜表面的黏液由表面黏液细胞分泌，其顶部充满黏原颗粒，分泌物富含糖蛋白和碳酸氢根，与细胞间紧密连接共同构成胃黏膜屏障。"},{"q":"构成气血屏障的结构应该除外","o":["Ⅰ型肺泡细胞","肺泡上皮的基膜","Ⅱ型肺泡细胞","毛细血管的内皮细胞","肺泡上皮和毛细血管内皮之间的结缔组织"],"a":2,"e":"气-血屏障由肺泡表面液体层、Ⅰ型肺泡细胞及基膜、薄层结缔组织、毛细血管基膜和内皮构成，Ⅱ型肺泡细胞只分泌表面活性物质。"},{"q":"白内障的主要原因是","o":["房水产生过多","房水流出受阻","角膜混浊","晶状体混浊","玻璃体混浊"],"a":3,"e":"白内障是晶状体蛋白变性混浊导致视觉障碍的疾病，老化、外伤和代谢异常均可引起晶状体混浊，与房水循环及角膜、玻璃体无关。"},{"q":"细胞内含大量溶酶体的细胞是","o":["破骨细胞","成骨细胞","骨祖细胞","骨细胞","软骨细胞"],"a":0,"e":"破骨细胞由单核细胞融合而成，富含溶酶体和水解酶，经皱褶缘释放酶与有机酸溶解骨盐、降解有机成分，完成骨吸收。"},{"q":"复层柱状上皮组织分布于","o":["气管","食管","肠管","眼睑结膜","女性尿道"],"a":3,"e":"复层柱状上皮分布于睑结膜和男性尿道腔面，有保护作用；气管为假复层纤毛柱状上皮，食管为复层扁平上皮，肠管为单层柱状上皮。"},{"q":"生殖腺发生的描述中，下列哪一项是错误的","o":["精原细胞和卵原细胞均由原始生殖细胞分化而来","支持细胞和卵泡细胞均起源于初级性索","若胚胎细胞的性染色体为XY时，则分化为睾丸","早期生精小管只含支持细胞和精原细胞","卵原细胞在胎儿出生前已分化为初级卵母细胞"],"a":1,"e":"卵泡细胞由生殖腺表面上皮增生形成的皮质索分化而来，初级性索在女性退化，故支持细胞与卵泡细胞并非同源于初级性索。"},{"q":"关于泄殖腔的演变，哪项错误","o":["由尿生殖膈分割泄殖腔","腹侧份为尿生殖窦","背侧份为原始直肠","腹侧份分化为外生殖器","背侧份分化为直肠和肛管上段"],"a":3,"e":"泄殖腔腹侧份被分隔为尿生殖窦，演变为膀胱和尿道大部分；外生殖器由生殖结节、尿生殖褶和阴唇阴囊隆起发育而成。"},{"q":"唾液腺中，浆液性腺泡的特点是","o":["腺细胞染色浅","细胞基部有较多分泌颗粒","细胞顶部有较多粗面内质网","细胞基部有大量滑面内质网","分泌物含较多唾液淀粉酶"],"a":4,"e":"浆液性腺泡细胞基底部胞质强嗜碱性、顶部含嗜酸性酶原颗粒，分泌物稀薄且富含唾液淀粉酶；黏液性腺泡染色浅，分泌物以黏蛋白为主。"},{"q":"脾滤血的主要部位是","o":["脾小体和脾血窦","脾索和边缘区","边缘区和动脉周围淋巴鞘","动脉周围淋巴鞘和脾小体","脾索和脾小体"],"a":1,"e":"脾索是富含血细胞的淋巴组织索，血液流经其网孔时巨噬细胞可吞噬衰老红细胞和病原体；边缘区是首先接触抗原并启动免疫应答的部位。"},{"q":"有关心肌纤维横小管的结构，哪项是错误的","o":["由肌膜凹陷形成","与终池相贴近，组成二联体","同一水平的横小管吻合成网","位于A带和I带交界水平","可传导肌膜兴奋"],"a":3,"e":"心肌横小管较粗且位于Z线水平，与一侧终池形成二联体；位于明暗带交界处并吻合成网是骨骼肌横小管的结构特点。"},{"q":"衬于心血管和淋巴管腔面的单层扁平上皮称为","o":["间皮","内皮","表皮","基膜","桥粒"],"a":1,"e":"衬贴在心脏、血管和淋巴管腔面的单层扁平上皮称内皮，表面光滑利于血液和淋巴流动；间皮则衬于胸膜、腹膜和心包膜表面。"},{"q":"卵裂是指","o":["卵细胞的第一次成熟分裂","卵细胞的无丝分裂","卵细胞的第二次成熟分裂","卵细胞的分裂","受精卵的早期分裂"],"a":4,"e":"卵裂是受精卵形成后进行的有丝分裂，因受透明带限制、分裂间期无生长，卵裂球数目增多而体积逐渐变小，最终形成桑葚胚。"},{"q":"鼓膜来自于","o":["听泡","第Ⅰ咽囊","第Ⅰ鳃沟底","间充质","3个胚层"],"a":4,"e":"鼓膜由三胚层共同形成，外层为外胚层来源的表皮，内层为内胚层来源的鼓室黏膜，中间结缔组织来自间充质。"},{"q":"在体液免疫应答时，淋巴结内（ ）增多变大","o":["初级淋巴小结","次级淋巴小结","副皮质区","深层皮质","髓质"],"a":1,"e":"体液免疫应答时B淋巴细胞在浅层皮质增殖分化，淋巴小结出现生发中心并增大增多形成次级淋巴小结，是体液免疫应答的重要标志。"},{"q":"关于直精小管的描述，哪项是错误的","o":["位于近睾丸纵隔处","细而短","由生精小管移行而来","进入睾丸纵隔后互相吻合成睾丸网","管壁上皮为单层扁平上皮"],"a":4,"e":"直精小管管壁为单层柱状上皮，由生精小管末端移行而来，短而细，进入睾丸纵隔后吻合成睾丸网，并非单层扁平上皮。"},{"q":"胎儿出生后，脐静脉萎缩形成下列哪种结构","o":["肝圆韧带","动脉韧带","静脉韧带","脐正中韧带","脐外侧韧带"],"a":0,"e":"脐静脉出生后闭锁形成肝圆韧带；静脉导管闭锁为静脉韧带，脐动脉远侧段形成脐外侧韧带，动脉导管闭锁为动脉韧带。"},{"q":"扫描电镜术主要用于观察","o":["组织和细胞内部的微细结构","器官和细胞表面的立体微细结构","细胞断裂面的微细结构","各种细胞器的微细结构","细胞膜内蛋白质颗粒的分布"],"a":1,"e":"扫描电镜以电子束扫描标本表面，收集二次电子成像，景深长、立体感强，用于观察器官和细胞表面的三维微细结构。"},{"q":"肛管的黏膜上皮来自","o":["外胚层","内胚层","中胚层","内胚层和外胚层","中胚层和外胚层"],"a":3,"e":"肛管上段上皮源自后肠内胚层，下段源自肛凹外胚层，二者以齿状线为界，故肛管黏膜上皮由内、外两胚层共同形成。"},{"q":"心室分隔后的室间隔包括","o":["心内膜垫和室间隔肌部","心内膜垫和室间隔膜部","室间隔肌部和室间隔膜部","室间隔肌部和心球嵴","室间隔膜部和心球嵴"],"a":2,"e":"室间隔由室间隔肌部与膜部构成，膜部由心球嵴、心内膜垫和肌部上缘融合而成，室间孔封闭后左、右心室完全分隔。"},{"q":"结缔组织由大量细胞和细胞外基质构成。细胞数量少，种类多。多种细胞可分泌生物活性物质，参与多种生理功能。其中与过敏反应有关的两种细胞是","o":["成纤维细胞和巨噬细胞","巨噬细胞和浆细胞","肥大细胞和嗜碱性粒细胞","肥大细胞和单核细胞","单核细胞和成纤维细胞"],"a":2,"e":"肥大细胞与嗜碱性粒细胞来源于骨髓同种造血祖细胞，颗粒内含组胺、肝素，并可合成白三烯，脱颗粒后引发过敏反应，二者作用基本相同。"},{"q":"对于规则致密结缔组织的描述，哪一项错误","o":["主要构成肌腱和腱膜，使骨骼肌附于骨上","大量胶原纤维顺应力学方向排列成束","腱细胞很多，位于纤维束之间","腱细胞是一种特殊的成纤维细胞","腱细胞胞体伸出多个薄翼状突起插入纤维束之问"],"a":2,"e":"规则致密结缔组织中腱细胞数量很少，仅夹在平行排列的胶原纤维束之间，胞体发出薄翼状突起包绕纤维束，以适应肌腱的强大拉力。"},{"q":"关于骨组织的特点，哪项错误","o":["含有四种细胞类型","胶原纤维多且排列紧密","骨基质呈板层状","细胞外基质钙化","骨盐的主要成分为氯化钠"],"a":4,"e":"骨盐占干骨重量65%，主要形式为羟基磷灰石结晶，以钙、磷为主，并非氯化钠；骨基质呈板层状并钙化，含四种骨组织细胞。"},{"q":"关于胆囊的描述，正确的是","o":["胆囊壁由黏膜、黏膜下层和外膜组成","黏膜和黏膜下层凸起形成高而分支的皱襞","胆囊的功能为分泌并浓缩胆汁","上皮为单层柱状，凹陷形成黏膜窦","外膜大部分为纤维膜"],"a":3,"e":"胆囊黏膜上皮为单层柱状，固有层上皮凹陷形成黏膜窦；胆囊壁无黏膜下层，外膜大部分为浆膜，胆囊只贮存和浓缩胆汁而不分泌胆汁。"},{"q":"血管升压素和缩宫素合成于","o":["垂体远侧部","垂体神经部","垂体中间部","正中隆起","下丘脑部分神经内分泌细胞"],"a":4,"e":"血管升压素和缩宫素由下丘脑视上核、室旁核的神经内分泌细胞合成，经轴突运输至垂体神经部贮存并释放入血。"},{"q":"与花粉引起的过敏反应关系密切的两种细胞是","o":["成纤维细胞和巨噬细胞","巨噬细胞和浆细胞","肥大细胞和浆细胞","肥大细胞和单核细胞","单核细胞和成纤维细胞"],"a":2,"e":"花粉过敏原刺激B细胞分化为浆细胞产生IgE，IgE与肥大细胞表面受体结合，再次接触过敏原时肥大细胞脱颗粒释放组胺，引发过敏反应。"},{"q":"肾小叶的组成是","o":["两条髓放线之间的皮质迷路","一条髓放线及其周围的皮质迷路","肾锥体及其相连的皮质部分","一条髓放线和相邻的肾柱","一个集合管及与其相通连的肾单位"],"a":1,"e":"一条髓放线及其周围的皮质迷路组成一个肾小叶；一个肾锥体与相连的皮质组成肾叶，肾锥体之间的皮质部分称肾柱。"},{"q":"脾内发生细胞免疫应答的主要变化是","o":["脾小体增多、增大","动脉周围淋巴鞘增厚","边缘区增大","脾血窦充血","脾索增大"],"a":1,"e":"细胞免疫应答时动脉周围淋巴鞘内T淋巴细胞分裂增殖，鞘增厚，相当于淋巴结副皮质区的扩大；体液免疫应答则表现为脾小体增多增大。"},{"q":"消化管各段之间结构差异最大、功能关系最密切和消化管中最常出现病变的部分是","o":["黏膜","黏膜肌层","黏膜下层","肌层","外膜"],"a":0,"e":"黏膜由上皮、固有层和黏膜肌层组成，各段上皮类型与腺体差异显著，是消化管结构差异最大、功能最重要且病变最常发生的层次。"},{"q":"有单层立方上皮的器官或结构是","o":["肾小管","男性尿道","胆囊","眼睑结膜","肺泡"],"a":0,"e":"肾小管和甲状腺滤泡为单层立方上皮；胆囊为单层柱状上皮，男性尿道和睑结膜为复层柱状上皮，肺泡为单层扁平上皮。"},{"q":"肾小管细段的显微结构是","o":["单层扁平上皮，核扁圆形凸向管腔","单层柱状上皮，无刷状缘","单层立方上皮，胞质着色浅","单层柱状上皮，胞质着色深","细胞呈锥体形，胞质着色浅"],"a":0,"e":"细段管径仅10～15μm，管壁为单层扁平上皮，细胞核椭圆、含核部分凸向管腔，胞质着色浅且无刷状缘，利于水和离子通透。"},{"q":"透明软骨的基质不包括","o":["胶原蛋白","毛细血管","硫酸软骨素","硫酸角质素","透明质酸"],"a":1,"e":"透明软骨基质由无定形基质和胶原原纤维构成，含硫酸软骨素、硫酸角质素和透明质酸，软骨本身无血管，营养靠渗透获得。"},{"q":"分泌物以唾液淀粉酶为主的是","o":["腮腺","汗腺","胰腺","下颌下腺","食管腺"],"a":0,"e":"腮腺为纯浆液腺，闰管长而纹状管较短，分泌物以唾液淀粉酶为主；下颌下腺和舌下腺为混合腺，分泌物中含黏液。"},{"q":"平滑肌纤维的肌丝单位的组成是","o":["细肌丝和粗肌丝","细肌丝和中间丝","粗肌丝和中间丝","粗肌丝，细肌丝和中间丝","只有中间丝"],"a":0,"e":"平滑肌无肌原纤维，若干条粗肌丝与细肌丝聚集形成肌丝单位即收缩单位，中间丝连接密斑与密体，构成细胞骨架而非收缩成分。"},{"q":"关于胃底腺结构，哪项正确","o":["由壁细胞、主细胞、颈黏液细胞、干细胞和内分泌细胞组成","位于胃底和胃体黏膜下层内","为混合性腺","其壁细胞主要位于腺的体、底部","其主细胞主要位于腺的颈、体部"],"a":0,"e":"胃底腺位于胃底和胃体黏膜固有层，为分支管状腺，由主细胞、壁细胞、颈黏液细胞、干细胞和内分泌细胞组成；壁细胞多分布在腺的颈部和体部。"},{"q":"大脑皮质组织发生中最先出现的是","o":["旧皮质","新皮质","梨状皮质","海马和梨状皮质","古皮质"],"a":4,"e":"大脑皮质发生依次经历古皮质、旧皮质和新皮质三个阶段，海马和齿状回最早出现，相当于古皮质，梨状皮质相当于旧皮质。"},{"q":"下列细胞具有形成胶原纤维的功能的是","o":["间充质细胞","成骨细胞","破骨细胞","骨原细胞","骨细胞"],"a":1,"e":"成骨细胞由骨祖细胞分化而来，合成并分泌胶原纤维和基质形成类骨质，随后矿化为骨组织；破骨细胞只负责骨吸收。"},{"q":"神经元树突的特点是","o":["是胞体的延续，与胞体结构相似","细长均匀，分支较少","分支常呈直角发出","表面光滑无棘刺","无粗面内质网"],"a":0,"e":"树突是胞体向外伸出的突起，其细胞质结构与胞体相似，含尼氏体和微管，分支上可见大量树突棘，主要功能是接受刺激。"},{"q":"使用普通光学显微镜观察HE染色切片时，低倍镜下结构清楚，但高倍镜下看不见或看不清楚，最可能的原因是","o":["虹彩未打开","对光不好","载玻片太厚","盖玻片太厚","盖玻片朝下"],"a":4,"e":"盖玻片朝下时组织切片被载玻片遮挡并超出工作距离，故低倍镜下可见轮廓而高倍镜下模糊不清，翻转切片方向即可解决。"},{"q":"平滑肌组织可分布于","o":["心脏壁","眼周","食管壁上三分之一段","胃壁","肌腱"],"a":3,"e":"平滑肌广泛分布于消化管、呼吸道和血管等中空器官的管壁，胃壁肌层即由其构成；心脏壁为心肌，食管上1/3段为骨骼肌。"},{"q":"中枢神经系统有髓神经纤维的髓鞘形成细胞是","o":["原浆性星形胶质细胞","少突胶质细胞","小胶质细胞","施万细胞","纤维性星形胶质细胞"],"a":1,"e":"中枢神经系统有髓神经纤维的髓鞘由少突胶质细胞突起末端扩展包卷轴突形成，周围神经系统的髓鞘则由施万细胞形成。"},{"q":"小脑皮质可分为三层，由外向内分别是","o":["分子层、锥体细胞层和颗粒层","分子层、颗粒层和浦肯野细胞层","分子层、浦肯野细胞层和节细胞层","分子层、浦肯野细胞层和颗粒层","颗粒层、分子层、浦肯野细胞层"],"a":3,"e":"小脑皮质由外向内分为分子层、浦肯野细胞层和颗粒层，浦肯野细胞胞体大、呈梨形，其轴突是小脑皮质唯一的传出纤维。"},{"q":"肠壁内神经丛的组成是","o":["交感神经元和无髓神经纤维","交感神经元和有髓神经纤维","副交感神经元和无髓神经纤维","副交感神经元和有髓神经纤维","感觉神经元和神经纤维"],"a":2,"e":"肠壁内神经丛属自主神经节，由副交感神经节细胞和无髓神经纤维构成，节后纤维支配平滑肌和腺体，调节消化管运动与分泌。"},{"q":"神经元胞体是细胞的营养中心，这主要是胞体内富含","o":["线粒体","粗面内质网和游离核糖体","脂肪","高尔基复合体","滑面内质网"],"a":1,"e":"胞体是神经元的营养和代谢中心，尼氏体由发达的粗面内质网和游离核糖体构成，可合成结构蛋白、递质合成酶及肽类神经调质。"},{"q":"关于球旁复合体的描述，下列哪项是正确的","o":["也称肾小球旁器，由球旁细胞、致密斑及球内系膜细胞组成","球旁细胞来自上皮细胞","球旁细胞分泌物肾素易通过血管基膜及内皮细胞释放入血","致密斑来自于远端小管靠近肾小体血管极侧的上皮细胞","致密斑可感受尿液中各种离子的浓度变化"],"a":3,"e":"致密斑是远端小管靠近肾小体血管极侧的上皮细胞增高密集排列形成的椭圆形斑，可感受远曲小管内Na+浓度变化并调节肾素释放。"},{"q":"具有分泌黏液功能的细胞是","o":["柱状细胞","潘氏细胞","干细胞","杯状细胞","内皮细胞"],"a":3,"e":"杯状细胞散在于肠上皮和呼吸道上皮中，顶部充满黏原颗粒，分泌黏蛋白以润滑和保护黏膜；潘氏细胞则分泌防御素和溶菌酶。"},{"q":"视网膜中感受强光和色觉的细胞是","o":["视锥细胞","视杆细胞","色素细胞","双极细胞","水平细胞"],"a":0,"e":"视锥细胞主要分布在视网膜中央部，感受强光和颜色，中央凹处只有视锥细胞并与双极细胞、节细胞一对一联系，分辨力最高。"},{"q":"次级卵泡中的卵母细胞是","o":["卵原细胞","初级卵母细胞","次级卵母细胞","成熟卵细胞","卵泡细胞"],"a":1,"e":"次级卵泡的卵泡腔形成时，其中的卵母细胞仍为初级卵母细胞，停滞于第一次减数分裂前期的双线期，直至排卵前才完成分裂。"},{"q":"胎儿的右心房大部分来源于下列何种结构","o":["原始肺静脉","原始心房","右肺静脉","静脉窦右角","腔静脉"],"a":3,"e":"静脉窦右角被吸收并入原始右心房，形成永久性右心房的静脉窦部即平滑部；窦左角退化为冠状窦，原始心房演变为右心耳。"},{"q":"光镜下心肌纤维与骨骼肌纤维区别，哪项是错误的","o":["两种肌纤维的大小和粗细不同","骨骼肌纤维有横纹，心肌纤维没有横纹","骨骼肌纤维没有闰盘，心肌纤维有闰盘","骨骼肌纤维没有分支，心肌纤维有分支","骨骼肌纤维含有多个细胞核，位于周边，心肌纤维只有一两个细胞核，位于中央"],"a":1,"e":"骨骼肌与心肌均有明暗相间的横纹，区别在于心肌纤维有分支和闰盘、核居中央，骨骼肌纤维无分支、多核居周边。"},{"q":"不属于单核吞噬细胞系统的有","o":["尘细胞","库普弗细胞","小胶质细胞","破骨细胞","白细胞"],"a":4,"e":"单核吞噬细胞系统包括单核细胞及由其分化而来的巨噬细胞，如库普弗细胞、尘细胞、小胶质细胞和破骨细胞；白细胞并非均属此系统。"},{"q":"毛细血管的构成是","o":["内膜、中膜和外膜和间皮","内皮、基膜和平滑肌","内皮和基膜","内皮、基膜和周细胞","内皮、基膜、周细胞和平滑肌"],"a":3,"e":"毛细血管壁仅由内皮细胞、基膜和周细胞构成，管径6～8μm，无内膜、中膜与外膜分层，可分为连续、有孔和血窦三类。"},{"q":"原始心脏发生于","o":["脊索腹侧的中胚层","脊索头端的中胚层","口咽膜头端的中胚层","口咽膜尾端的中胚层","前肠背侧的中胚层"],"a":2,"e":"生心区由胚盘前缘口咽膜头端的中胚层细胞汇聚形成，此处出现围心腔并形成心管，故原始心脏发生于口咽膜头端的中胚层。"},{"q":"对于胸腺依赖区的描述，哪一项错误","o":["由弥散淋巴组织构成","以T细胞为主","是细胞免疫应答的主要场所","是体液免疫应答的主要场所","常分布着毛细血管后微静脉"],"a":3,"e":"胸腺依赖区即淋巴结副皮质区，以T淋巴细胞为主，是细胞免疫应答的主要场所；体液免疫应答主要发生在浅层皮质的淋巴小结。"},{"q":"关于泌尿系统的畸形，下列哪一项是错误的","o":["多囊肾是因集合小管未与远端小管接通所致","马蹄肾是因两肾上端异常融合所致","双输尿管是因输尿管芽过早分支所致","脐尿瘘是因脐尿管未闭锁所致","异位肾是因肾在上升过程中受阻所致"],"a":1,"e":"马蹄肾是两肾上升过程中受阻于肠系膜下动脉根部，两肾下端融合成马蹄形；多囊肾因集合小管未与远端小管接通，尿液潴留形成囊肿。"},{"q":"关于远曲小管的特点描述，下列哪项正确","o":["胞质染色较深，嗜酸性","上皮细胞为立方形，染色浅","是糖皮质激素的靶细胞","有刷状缘","上皮细胞核位于基部"],"a":1,"e":"远曲小管上皮为立方形，细胞较近端小管小，核位于中央或近腔面，胞质染色浅、游离面无刷状缘，管腔大而规则。"},{"q":"初级卵母细胞完成第一次成熟分裂是在","o":["青春期前","次级卵泡时期","成熟卵泡形成时","排卵前36～48小时","受精时"],"a":3,"e":"初级卵母细胞在排卵前36～48小时完成第一次减数分裂，形成次级卵母细胞和第一极体，随即进入第二次减数分裂并停滞于中期。"},{"q":"肾上腺皮质细胞超微结构特点是富含","o":["粗面内质网和滑面内质网","粗面内质网和高尔基复合体","粗面内质网和溶酶体","高尔基复合体和线粒体","滑面内质网和线粒体"],"a":4,"e":"肾上腺皮质细胞属类固醇激素分泌细胞，胞质富含滑面内质网和嵴呈管泡状的线粒体，脂滴丰富，不形成分泌颗粒。"},{"q":"角膜的营养来自","o":["角膜内血管和房水","角膜缘血管和房水","虹膜血管","睫状体血管层","脉络膜血管"],"a":1,"e":"角膜本身无血管和淋巴管，营养由房水和角膜缘的血管以渗透方式供应，故角膜缘病变可影响角膜的营养与修复。"},{"q":"滤泡旁细胞的特征中，哪项是错误的","o":["位于滤泡之间或滤泡上皮细胞之间","胞质中有较丰富的粗面内质网和高尔基复合体","胞质中有嗜银颗粒","HE染色胞质呈强嗜伊红性","分泌降钙素"],"a":3,"e":"滤泡旁细胞胞体较大，HE染色胞质着色浅，镀银染色可见嗜银颗粒，分泌降钙素降低血钙；强嗜伊红性是甲状旁腺嗜酸性细胞的特点。"},{"q":"食管是食物进入胃的通道，容易受到摩擦，胃酸反流也容易引起黏膜损伤。食管黏膜上皮是","o":["单层扁平上皮","单层柱状上皮","变移上皮","未角化的复层扁平上皮","角化的复层扁平上皮"],"a":3,"e":"食管黏膜上皮为未角化的复层扁平上皮，可耐受食物摩擦，其下端与胃贲门部单层柱状上皮骤然相接，为食管癌好发部位。"},{"q":"肢端肥大症是由垂体哪种细胞分泌过盛引起的","o":["垂体细胞","嗜碱性细胞","嫌色细胞","嗜酸性细胞","弓状核神经内分泌细胞"],"a":3,"e":"肢端肥大症由腺垂体嗜酸性生长激素细胞分泌生长激素过盛所致，成年后骨骺已闭合，表现为肢端及颌面骨过度增生。"},{"q":"关于皮下组织的描述，下列哪项是正确的","o":["为位于皮肤下方的结缔组织","为位于表皮下方的结缔组织","与皮肤有明显的分界线","是皮肤的一个组成部分","可见丰富的触觉小体"],"a":0,"e":"皮下组织又称浅筋膜，位于真皮下方，由疏松结缔组织和脂肪组织构成，不属于皮肤结构，与真皮之间无明显分界。"},{"q":"光镜下，相邻肺泡开口处有结节状膨大的结构是","o":["终末细支气管","呼吸性细支气管","肺泡管","肺泡囊","细支气管"],"a":2,"e":"肺泡管管壁上有大量肺泡开口，相邻肺泡开口之间残留的管壁形成结节状膨大，内含弹性纤维和环行平滑肌；肺泡囊开口之间无此膨大。"},{"q":"骨骼肌纤维三联体的结构","o":["由一条横小管和两侧的终池形成","由两条横小管和中间的终池形成","由两条纵小管和中间的终池形成","由一条横小管和一个终池形成","由一条纵小管和一个终池形成"],"a":0,"e":"骨骼肌每条横小管与其两侧的终池共同构成三联体，是肌膜兴奋经横小管传至肌浆网并触发Ca2+释放的结构基础。"},{"q":"骨骼肌纤维的肌节是由","o":["1/2明带＋1/2暗带组成","1/2明带＋暗带＋1/2明带组成","明带＋暗带组成","1/2暗带＋明带＋1/2暗带组成","1/2明带＋1/2暗带＋1/2明带组成"],"a":1,"e":"肌节是相邻两条Z线之间的一段肌原纤维，由1/2明带、暗带和1/2明带构成，暗带长度恒定，明带随收缩与舒张而改变。"},{"q":"由中肠演化形成的器官是","o":["肝","空肠","胃","胆总管","胰"],"a":1,"e":"中肠袢头支演化为空肠和回肠大部分，尾支主要演化为结肠；胃、肝、胆囊、胆总管和胰腺均由前肠演化形成。"},{"q":"脊髓内分化为中间神经元的成神经细胞位于","o":["基板","翼板","顶板","底板","翼板和基板之间"],"a":1,"e":"脊髓翼板内的成神经细胞分化为后角中间神经元，基板形成前角躯体运动神经元，基板与翼板之间形成侧角的内脏传出神经元。"},{"q":"生肾索发生于","o":["尿生殖嵴","中肾嵴","生殖腺嵴","间介中胚层","侧中胚层"],"a":3,"e":"生肾索由间介中胚层尾段增生形成，第4周末继续增生凸向胚内体腔形成尿生殖嵴，后者再分为中肾嵴和生殖腺嵴。"},{"q":"运动终板突触小泡内含有的主要神经递质是","o":["脑啡肽","乙酰胆碱","去甲肾上腺素","5-羟色胺","多巴胺"],"a":1,"e":"运动终板属躯体运动神经末梢，轴突终末的突触小泡内含乙酰胆碱，释放后与肌膜受体结合，引起肌纤维收缩。"},{"q":"神经元细胞核的特点是","o":["球形，较大，着色较淡，核仁明显","分叶状，较大，着色较深，核仁不明显","球形，较小，着色较淡，核仁明显","球形，较大，着色较深，核仁不明显","梭形，较小，着色淡，核仁明显"],"a":0,"e":"神经元胞核大而圆、多位于胞体中央，异染色质少故着色浅，核仁大而明显，提示其转录与蛋白质合成功能活跃。"},{"q":"巩膜的主要成分是","o":["网状纤维","粗大的胶原纤维","弹性纤维","胶原原纤维","平滑肌"],"a":1,"e":"巩膜由大量粗大的胶原纤维交织构成，纤维间有少量弹性纤维和基质，质地坚韧呈瓷白色，构成眼球壁的保护层。"},{"q":"电镜下微绒毛与纤毛不同点是","o":["前者细长，后者粗短","前者能摆动，后者不可摆动","前者光镜下可见，后者不可见","前者内含微丝，后者内含微管","前者内含线粒体，而后者则无"],"a":3,"e":"微绒毛内含纵行微丝即肌动蛋白丝，可伸缩；纤毛内含微管，按9+2排列并能定向摆动，两者在电镜下据此区别。"},{"q":"以下哪两种细胞均不参与机体免疫反应","o":["成纤维细胞和脂肪细胞","脂肪细胞和浆细胞","浆细胞和肥大细胞","肥大细胞和巨噬细胞","巨噬细胞和成纤维细胞"],"a":0,"e":"成纤维细胞合成纤维和基质，脂肪细胞贮存脂肪，二者均不参与免疫应答；巨噬细胞、浆细胞和肥大细胞分别参与吞噬、产生抗体和过敏反应。"},{"q":"和肝纤维化肝硬化有关的是","o":["贮脂细胞形成脂滴的能力增强","贮脂细胞形成脂滴的能力减弱","贮脂细胞合成胶原的功能增强","贮脂细胞合成胶原的功能抑制","贮脂细胞摄取和贮存维生素A的功能减弱"],"a":2,"e":"病理情况下贮脂细胞增多并转化为成纤维细胞，合成胶原功能增强，导致窦周隙胶原沉积，是肝纤维化的重要环节。"},{"q":"以下对神经元突起的描述，哪项错误","o":["分为轴突和树突","轴突细而长，每一个神经细胞只有一个轴突，中途很少分支，末端可有大量分支","树突较短多分支，尼氏体可伸入其内","由细胞体发出轴突处称轴丘，内含尼氏体","神经原纤维沿轴突长轴平行排列"],"a":3,"e":"轴丘是胞体发出轴突的圆锥形部位，该区无尼氏体故染色浅；轴突内亦无粗面内质网和核糖体，不能合成蛋白质。"},{"q":"最常见的突触方式是","o":["轴-树突触","轴-体突触","轴-轴突触","树-树突触","树-棘突触"],"a":0,"e":"突触最常见的形式是轴突终末与树突或树突棘形成的轴-树突触，其次为轴-体突触，轴-轴突触较为少见。"},{"q":"腺上皮的是指","o":["含有腺细胞的上皮","具有分泌功能的上皮","具有吸收功能的上皮","以分泌功能为主的上皮","以吸收功能为主的上皮"],"a":3,"e":"腺上皮是由腺细胞构成的以分泌功能为主的上皮，其分泌物包括酶、黏液和激素，可经导管排至体表或器官腔，也可直接入血。"},{"q":"分泌房水的是","o":["角膜上皮","角膜内皮","晶状体上皮","虹膜色素上皮","睫状体非色素上皮"],"a":4,"e":"睫状体上皮内层为矮柱状非色素上皮细胞，可分泌房水并产生睫状小带和玻璃体的成分，房水经小梁间隙入巩膜静脉窦回流。"},{"q":"关于致密斑的描述，哪项正确","o":["由近曲小管上皮细胞紧密排列形成","靠近肾小体血管极的远端小管上皮细胞增高密集排列呈斑状结构","能感受滤液中Na＋的变化，分泌肾素","致密斑的细胞与球旁细胞关系密切，二者之间有基膜","细胞排列紧密，呈斑状，细胞为立方形"],"a":1,"e":"致密斑由远端小管靠近肾小体血管极侧的上皮细胞增高密集排列成斑状，细胞呈柱状、核密集，基膜不完整，紧邻球旁细胞。"},{"q":"骨骼肌纤维的肌膜向内凹陷形成","o":["小凹","肌浆网","横小管","闰盘","终池"],"a":2,"e":"横小管是肌膜向肌质内凹陷形成的管状结构，与肌纤维长轴垂直，位于明暗带交界处，可将肌膜兴奋传入细胞深部。"},{"q":"关于后肾发生部位，下列哪项是正确的","o":["前肾管末端的输尿管芽和中肾嵴末端的生后肾原基","中肾管末端的输尿管芽和生殖腺嵴末端的生后肾原基","中肾管末端的输尿管芽和中肾嵴末端的生后肾原基","中肾管末端的生后肾原基和中肾嵴末端的输尿管芽","中肾旁管末端的输尿管芽和中肾嵴末端的生后肾原基"],"a":2,"e":"后肾由中肾管末端的输尿管芽与中肾嵴尾端的生后肾原基相互诱导共同发生，输尿管芽形成输尿管、肾盂、肾盏和集合管。"},{"q":"软骨膜的纤维主要是","o":["网状纤维","胶原纤维","胶原原纤维","微原纤维","弹性纤维"],"a":1,"e":"软骨膜分内外两层，外层纤维层以胶原纤维为主并含血管和神经，内层细胞层含骨祖细胞样细胞，可增殖分化为软骨细胞。"},{"q":"幼稚红细胞合成血红蛋白的结构是","o":["游离核糖体","粗面内质网","高尔基复合体","线粒体","滑面内质网"],"a":0,"e":"幼稚红细胞胞质内的血红蛋白在游离核糖体上合成，因其缺乏粗面内质网，合成后核与细胞器逐渐排出。"},{"q":"黏液性腺细胞分泌的黏液是","o":["糖蛋白","蛋白多糖","脂蛋白","糖脂","蛋白质"],"a":0,"e":"黏液性腺细胞分泌的黏液主要成分为糖蛋白，含糖基多而蛋白质少，HE染色着色浅淡，排出后起润滑和保护作用。"},{"q":"关于生后肾组织的描述，错误的是","o":["来源于生肾索的尾端部分","在输尿管芽的诱导下分化","分化为肾单位","形成肾小管和集合小管","外周部分形成肾被膜"],"a":3,"e":"集合小管由输尿管芽反复分支分化而来，生后肾组织只分化肾小体及近端小管、细段和远端小管，其外周部分形成肾被膜。"},{"q":"髓袢的组成部分是","o":["近直小管和细段","近直小管、细段和远直小管","细段和远直小管","远直小管和集合管","近直小管和远直小管"],"a":1,"e":"髓袢呈U形，由近端小管直部、细段和远端小管直部依次连接构成，位于髓放线和髓质内，与尿液浓缩密切相关。"},{"q":"初级卵母细胞的第一次减数分裂完成于","o":["原始卵泡阶段","初级卵泡阶段","排卵前36～48小时","排卵时","排卵后"],"a":2,"e":"排卵前36～48小时初级卵母细胞完成第一次减数分裂，产生次级卵母细胞和第一极体，极体位于次级卵母细胞与透明带之间的卵周间隙。"},{"q":"分泌类固醇激素的器官/部位是","o":["甲状腺","肾上腺皮质","肾上腺髓质","腺垂体远侧部","下丘脑视上核"],"a":1,"e":"肾上腺皮质球状带、束状带和网状带细胞均分泌类固醇激素，胞质富含滑面内质网和管泡状嵴线粒体；甲状腺和腺垂体分泌含氮激素。"},{"q":"下列关于透明带的描述中，哪项是错误的","o":["由三种糖蛋白分子ZP1、ZP2、ZP3构成，其中ZP3为精子受体","为一层均质状、折光性强的嗜酸性膜","位于膜细胞与卵泡细胞之间","卵母细胞表面突起与卵泡细胞的微绒毛在透明带内形成缝隙连接","从初级卵泡开始出现"],"a":2,"e":"透明带位于初级卵母细胞与卵泡细胞之间，由二者共同分泌形成，含ZP1、ZP2、ZP3三种糖蛋白，其中ZP3为精子受体。"},{"q":"骨骼肌纤维收缩时，长度不变的是","o":["I带","A带","H带","肌节","肌原纤维"],"a":1,"e":"骨骼肌收缩时细肌丝向M线方向滑行，I带和H带变窄，A带由粗肌丝构成、长度恒定不变，肌节随之缩短。"},{"q":"长期炎症等刺激下，胃黏膜可能出现化生现象，但正常胃黏膜的结构和功能特点不包括","o":["黏膜上皮为夹有杯状细胞的单层柱状上皮","上皮中尚有少量内分泌细胞","胃小凹的上皮与表面上皮一样，可分泌黏液","胃小凹的底与胃腺相通","胃体部的胃腺可分泌黏液、盐酸、酶原和激素"],"a":0,"e":"正常胃黏膜上皮为单层柱状，由表面黏液细胞和少量内分泌细胞构成，不含杯状细胞；胃小凹与胃腺相通，胃底腺分泌盐酸、酶原、黏液和激素。"},{"q":"性未分化期，胚胎有两套生殖管道，分别是","o":["中肾小管和中肾管","中肾管和中肾旁管","中肾小管和中肾旁管","中肾管和前肾小管","前肾小管和中肾旁管"],"a":1,"e":"性未分化期胚体内存在中肾管和中肾旁管两对生殖管道，男性靠雄激素使中肾管发育、抗中肾旁管激素使中肾旁管退化，女性则相反。"},{"q":"泪腺来源于","o":["中胚层","表面外胚层","神经外胚层","内胚层","神经外胚层和中胚层"],"a":1,"e":"泪腺由睑结膜表面上皮即表面外胚层向深部增生分化而成，属表面外胚层起源的腺体，与角膜上皮相延续。"},{"q":"腺垂体嗜酸性细胞可合成和分泌","o":["生长激素和促甲状腺激素","促甲状腺激素、促肾上腺皮质激素和促性腺激素","催乳激素和生长激素","催产素和生长激素","催乳激素和催产素"],"a":2,"e":"腺垂体嗜酸性细胞分生长激素细胞和催乳激素细胞，分别分泌生长激素和催乳素；促甲状腺激素等则由嗜碱性细胞分泌。"},{"q":"人胚发育3个月后，胎儿的尿液通过尿道外口排入","o":["胚内体腔","卵黄囊","羊膜腔","泄殖腔","胚外体腔"],"a":2,"e":"后肾自第12周开始产生尿液，经输尿管、膀胱和尿道排入羊膜腔，成为羊水的主要来源，胎儿尿液不排入胚内体腔。"},{"q":"以下哪一种细胞产生纤维和基质","o":["巨噬细胞","肥大细胞","浆细胞","成纤维细胞","脂肪细胞"],"a":3,"e":"成纤维细胞是疏松结缔组织中数量最多的细胞，合成并分泌胶原纤维、弹性纤维和基质，功能活跃时粗面内质网和高尔基复合体发达。"},{"q":"关于气管与支气管的细胞，下列错误的是","o":["刷细胞表面的纤毛较短","杯状细胞数量较多，分泌黏蛋白","基细胞可分化为纤毛细胞及杯状细胞","纤毛细胞的纤毛向咽部快速摆动","管壁内的神经内分泌细胞又称小颗粒细胞"],"a":0,"e":"刷细胞游离面有短小微绒毛而非纤毛；杯状细胞分泌黏蛋白，基细胞可增殖分化为纤毛细胞和杯状细胞，小颗粒细胞属神经内分泌细胞。"},{"q":"法洛四联症的最主要原因是","o":["右心室肥大","室间隔膜部缺损","主动脉骑跨","肺动脉狭窄","主动脉肺动脉隔偏位"],"a":4,"e":"法洛四联症因主动脉肺动脉隔偏向肺动脉一侧，造成肺动脉狭窄，继而引起室间隔缺损、主动脉骑跨和右心室肥大，分隔偏位是根本原因。"},{"q":"胚泡植入后的子宫内膜称为","o":["胎膜","蜕膜","绒毛膜","羊膜","基膜"],"a":1,"e":"胚泡植入后子宫内膜在孕激素作用下发生蜕膜反应，基质细胞肥大、富含糖原和脂滴，内膜改称蜕膜，分为基蜕膜、包蜕膜和壁蜕膜。"},{"q":"关于次级精母细胞的描述，错误的是","o":["位置靠近管腔","较初级精母细胞小，核圆，染色较深","染色体核型为23，X或23，Y","经DNA复制和第2次成熟分裂后形成精子细胞","存在时间短，故生精小管切面上不易见到"],"a":3,"e":"次级精母细胞不再进行DNA复制，核型为23，X或23，Y，含2nDNA，迅速完成第二次减数分裂形成两个精子细胞。"},{"q":"精子的顶体是特殊的","o":["线粒体","滑面内质网","溶酶体","中心粒","粗面内质网"],"a":2,"e":"顶体是覆盖精子核前2/3的帽状结构，由高尔基复合体形成，属特殊溶酶体，内含顶体素、透明质酸酶等水解酶，参与受精。"},{"q":"理论上讲，一个初级精母细胞最终能形成精子的数目是","o":["2个","4个","6个","8个","10个"],"a":1,"e":"一个初级精母细胞经第一次减数分裂形成两个次级精母细胞，再经第二次减数分裂形成四个精子细胞，最终变态为四个精子。"},{"q":"子宫内膜的上皮是","o":["单层立方上皮，含分泌细胞","单层立方上皮或单层扁平上皮，以分泌细胞为主","单层柱状上皮，以分泌细胞为主","单层柱状或假复层纤毛柱状上皮，以纤毛细胞为主","单层柱状上皮，以纤毛细胞为主"],"a":2,"e":"子宫内膜上皮为单层柱状上皮，由分泌细胞和少量纤毛细胞组成，以分泌细胞为主，分泌期分泌糖原为胚的植入提供营养。"},{"q":"微皱褶细胞","o":["是组成肠腺的一种细胞","其基底面有许多微皱褶","在光镜下很容易辨认","可摄取抗原并传递给下方的淋巴细胞","产生的分泌片与IgA结合形成sIgA"],"a":3,"e":"M细胞即微皱褶细胞，基底面内陷形成口袋，可摄取肠腔抗原并以囊泡形式转运给下方的巨噬细胞和淋巴细胞，是黏膜免疫的入口。"},{"q":"下列哪种细胞是周围神经系统的神经胶质细胞","o":["卫星细胞","嗅细胞","锥体细胞","味细胞","毛细胞"],"a":0,"e":"周围神经系统的神经胶质细胞包括施万细胞和卫星细胞，前者形成髓鞘，后者包绕神经节细胞胞体；少突胶质细胞和星形胶质细胞属中枢。"},{"q":"毛细血管可分为","o":["连续型、不连续型、有孔型和血窦","连续型、有孔型和血窦","无孔型和有孔型","连续型、不连续型、有孔型和无孔型","连续型和不连续型"],"a":1,"e":"毛细血管按内皮和基膜结构分为连续毛细血管、有孔毛细血管和血窦三类，血窦即不连续毛细血管，管腔大、基膜不完整。"},{"q":"软骨分类的依据是","o":["软骨细胞的数量","软骨基质中硫酸软骨素的含量","软骨基质中纤维的种类","软骨细胞的形态","软骨的功能"],"a":2,"e":"软骨按基质中纤维的种类和含量分为透明软骨、弹性软骨和纤维软骨，与软骨细胞的数量和形态无关。"},{"q":"早期的神经板为","o":["假复层柱状上皮","单层柱状上皮","单层立方上皮","复层柱状上皮","假复层纤毛柱状上皮"],"a":1,"e":"早期神经板由单层柱状上皮构成，随后细胞增殖演变为假复层柱状上皮即神经上皮，再分化为神经管壁。"},{"q":"膀胱腔面上皮的特点为","o":["细胞形状可发生变化","上皮的厚度恒定不变","浅层细胞为柱状","表层细胞角化以防止尿液侵蚀","基底面凹凸不平"],"a":0,"e":"变移上皮的细胞形状和层数随器官充盈程度改变，膀胱空虚时上皮厚、盖细胞呈立方形，充盈时上皮变薄、盖细胞扁平。"},{"q":"肾的哪段血管胶体渗透压高","o":["入球微动脉","球内毛细血管","球后毛细血管","小叶间静脉","小叶间动脉"],"a":2,"e":"血液流经血管球时大量水分被滤出，使出球微动脉分支形成的球后毛细血管内血浆蛋白浓度相对升高，胶体渗透压显著增高，利于重吸收。"},{"q":"对骨膜的描述，哪项是错误的","o":["穿通纤维与骨外膜相连","骨的外表面被覆骨外膜","骨的外表面与骨髓腔面均被覆骨外膜","骨髓腔面和骨小梁表面被覆骨内膜","穿通管和中央管内表面也被覆骨内膜"],"a":2,"e":"长骨除关节面外，外表面被覆骨外膜，骨髓腔面、骨小梁表面及穿通管、中央管内表面被覆骨内膜，两者并非都由骨外膜覆盖。"},{"q":"关于肾上腺皮质束状带的叙述，错误的是","o":["皮质中最厚，腺细胞排列成索状","腺细胞滑面内质网丰富，线粒嵴呈管泡状","腺细胞含较多分泌颗粒","腺细胞含大量的脂滴","细胞间有丰富的血窦"],"a":2,"e":"束状带细胞属类固醇激素分泌细胞，胞质充满脂滴，滑面内质网发达、线粒体嵴呈管泡状，不形成分泌激素的颗粒，激素合成后即弥散释放。"},{"q":"骨骼肌收缩的结构基础是","o":["肌浆网","肌节","横小管","线粒体","粗面内质网"],"a":1,"e":"肌节由粗、细两种肌丝规律排列构成，是骨骼肌纤维收缩的最小结构和功能单位，其缩短引起肌原纤维乃至肌纤维收缩。"},{"q":"卵泡液由","o":["卵泡细胞分泌形成","卵泡膜细胞分泌形成","卵泡膜血管内血液渗出而成","卵泡细胞分泌和卵泡膜血管内血液渗出而成","卵泡细胞和卵泡膜细胞共同分泌形成"],"a":3,"e":"卵泡液由卵泡细胞分泌，并有卵泡膜血管内的血浆成分渗出共同形成，充满卵泡腔，含激素和营养物质。"},{"q":"关于支气管树结构的变化错误的是","o":["上皮逐渐变薄，杯状细胞逐渐变少以至消失","管径逐渐变细，管壁逐渐变薄","肌层越来越薄","腺体逐渐变少，最后消失","软骨呈不规则片状，逐渐减少以至消失"],"a":2,"e":"支气管树分支中管径渐细、上皮渐薄，杯状细胞和腺体渐少，软骨由环状变为片状并减少；平滑肌则相对增多，并非越来越薄。"},{"q":"排卵时，随卵泡液释放出的成分是","o":["成熟卵细胞","成熟卵细胞和透明带","成熟卵细胞、透明带和放射冠","初级卵母细胞、透明带和放射冠","次级卵母细胞、透明带和放射冠"],"a":4,"e":"排卵时成熟卵泡破裂，次级卵母细胞连同透明带和放射冠随卵泡液一起排出，此时卵母细胞停滞于第二次减数分裂中期。"},{"q":"关于嗜酸性粒细胞，哪项错误","o":["嗜酸性颗粒含组胺酶和芳基硫酸酯酶","具有抗寄生虫作用","在血流中停留6～8小时","占白细胞总数0.5%～3%","导致过敏反应"],"a":4,"e":"嗜酸性粒细胞颗粒含组胺酶和芳基硫酸酯酶，能分解组胺、灭活白三烯从而抑制过敏反应，并具抗寄生虫作用，占白细胞0.5%～3%。"},{"q":"肥大细胞较大，胞质内充满丰富的嗜碱性颗粒，颗粒内含有多种细胞因子和生物活性物质，发挥多种生理功能。当细胞脱颗粒时会","o":["使毛细血管通透性降低","减轻炎症反应","减轻支气管痉挛","导致荨麻疹","导致血压升高"],"a":3,"e":"肥大细胞脱颗粒释放组胺和白三烯，使皮肤微静脉和毛细血管扩张、通透性增强，局部水肿形成红肿块即荨麻疹，并使血压下降。"},{"q":"关于肾单位的组成，哪项是正确的","o":["肾小体和泌尿小管","肾小体，近曲小管，远曲小管和髓袢","肾小体和髓袢","肾小体和近端小管","肾小体和远端小管"],"a":1,"e":"肾单位由肾小体和与之相连的肾小管构成，后者包括近端小管、细段和远端小管，故近曲小管、远曲小管和髓袢均属肾单位。"},{"q":"关于子宫内膜分泌期的描述中，哪项是错误的","o":["为月经周期的第15～28天","又称黄体期","固有层呈生理性水肿","子宫腺腔增大，腔内可见分泌物","螺旋动脉短暂扩张，导致功能层血管破裂"],"a":4,"e":"螺旋动脉短暂扩张致血管破裂出血见于月经期，是孕激素撤退后血管持续收缩缺血再扩张的结果；分泌期以腺体分泌和基质水肿为特征。"},{"q":"人体组织常被归纳为四大类型，通常指","o":["上皮组织、疏松结缔组织、肌组织、神经组织","上皮组织、结缔组织、骨骼肌组织、神经组织","上皮组织、结缔组织、肌组织、神经组织","上皮组织、固有结缔组织、肌组织、神经组织","被覆上皮组织、结缔组织、肌组织、神经组织"],"a":2,"e":"人体四大基本组织为上皮组织、结缔组织、肌组织和神经组织，结缔组织涵盖疏松与致密结缔组织、软骨、骨和血液等。"},{"q":"腺垂体调节下丘脑的主要方式是","o":["交感神经调节","副交感神经调节","反馈方式调节","分泌释放激素调节","分泌释放抑制激素调节"],"a":2,"e":"腺垂体对下丘脑的调节属反馈方式：腺垂体促激素使靶腺激素升高后，可负反馈抑制下丘脑释放激素及自身促激素的分泌。"},{"q":"在淋巴结和脾，以B细胞为主的结构是","o":["副皮质区和淋巴小结","副皮质区和脾索","副皮质区和动脉周围淋巴鞘","淋巴小结和动脉周围淋巴鞘","淋巴小结和脾小体"],"a":4,"e":"淋巴小结是B淋巴细胞聚集增殖的球形结构，脾内的淋巴小结即脾小体；副皮质区和动脉周围淋巴鞘为胸腺依赖区，以T细胞为主。"},{"q":"皮肤的表皮中可见","o":["毛细血管","触觉小体","环层小体","游离神经末梢","肌梭"],"a":3,"e":"表皮内无血管，感觉神经末梢以游离神经末梢穿行于细胞间；触觉小体位于真皮乳头，环层小体位于真皮深层，肌梭位于骨骼肌内。"},{"q":"增生期子宫内膜的子宫腺细胞光镜下的核下空泡是","o":["分泌颗粒聚集而成","脂滴聚集而成","糖原聚集而成","核糖体聚集而成","过氧化物酶体聚集而成"],"a":2,"e":"增生晚期子宫腺细胞核下区糖原大量集聚，制片时糖原被溶解而形成核下空泡，故空泡实质是糖原的痕迹，分泌颗粒位于细胞顶部。"},{"q":"关于成骨细胞的形态描述，哪项正确","o":["胞体较大，有多个大而圆的细胞核","胞质嗜酸性","细胞表面有许多细小突起，可与邻近成骨细胞形成缝隙连接","有大量线粒体和溶酶体","有许多吞噬泡和吞噬体"],"a":2,"e":"成骨细胞胞体较大呈立方形，表面伸出许多细小突起，与邻近细胞以缝隙连接相通；胞质嗜碱性，富含粗面内质网和发达的高尔基复合体。"},{"q":"虹膜上皮来自胚胎的","o":["视杯口边缘部","视柄","视杯内层","视杯外层","视杯口周围间充质"],"a":0,"e":"视杯口边缘部内层上皮不增厚，与外层上皮共同分化为虹膜上皮，外层成色素上皮，内层成瞳孔开大肌和瞳孔括约肌。"},{"q":"在光镜下进行观察的石蜡包埋切片厚度一般是","o":["0.1～0.5μm","1μm左右","5～10μm","50μm","100μm"],"a":2,"e":"光镜观察的常规石蜡切片厚5～10μm，能显示组织和细胞的整体结构；0.1μm级属超薄切片，供透射电镜使用。"},{"q":"粗面内质网和高尔基复合体是合成蛋白质相关的细胞器。在疏松结缔组织内，数量最多，具有丰富粗面内质网和发达高尔基复合体，可合成和分泌胶原蛋白和弹性蛋白的细胞是","o":["巨噬细胞","肥大细胞","白细胞","脂肪细胞","成纤维细胞"],"a":4,"e":"成纤维细胞是疏松结缔组织中数量最多的细胞，电镜下粗面内质网和高尔基复合体发达，能合成胶原蛋白、弹性蛋白和基质。"},{"q":"淋巴细胞从血液进入脾内淋巴组织的重要通道","o":["动脉周围淋巴鞘","脾血窦","脾索","边缘窦","淋巴小结"],"a":3,"e":"边缘窦位于白髓与红髓交界处，是血液中淋巴细胞穿出血管进入脾淋巴组织的重要通道；中央动脉周围淋巴鞘主要容纳T细胞。"},{"q":"以下对心肌纤维超微结构的描述，哪项是错误的","o":["肌原纤维不如骨骼肌的明显","横小管位于明带和暗带交界处","肌浆网不如骨骼肌的发达","仅形成二联体","心肌纤维连接处形成闰盘"],"a":1,"e":"心肌纤维横小管较粗，位于Z线水平，与肌浆网形成二联体；横小管位于明带与暗带交界处、形成三联体是骨骼肌的特点。"},{"q":"胎盘中分泌HPL的主要是","o":["细胞滋养层","合体滋养层","基蜕膜","包蜕膜","壁蜕膜"],"a":1,"e":"人胎盘合体滋养层细胞合成并分泌人胎盘催乳素，促进母体乳腺发育和胎儿生长；细胞滋养层主要起增殖补充作用。"},{"q":"假单极神经元存在于","o":["大脑皮质","小脑皮质","自主神经节","脊髓灰质","脑脊神经节"],"a":4,"e":"假单极神经元胞体位于脊神经节和脑神经节，突起呈T形分支，一支至外周感受器，一支入中枢；自主神经节内为多极神经元。"},{"q":"来自内胚层的是","o":["外耳道和中耳鼓室的上皮","中耳鼓室和咽鼓管的上皮","外耳道和咽鼓管的上皮","中耳鼓室和膜迷路的上皮","膜迷路和咽鼓管的上皮"],"a":1,"e":"中耳鼓室与咽鼓管的黏膜上皮由第1咽囊内胚层分化而来；外耳道上皮来自第1鳃沟外胚层，膜迷路上皮来自耳泡。"},{"q":"关于近曲小管上皮细胞的特征，哪项是错误的","o":["细胞分界清晰","腔面有刷状缘","细胞基部有纵纹","胞质嗜酸性","细胞核呈圆形，位于近基底部"],"a":0,"e":"近曲小管上皮细胞分界不清，胞质强嗜酸性，腔面有刷状缘、基部有纵纹，核圆位居近基底部；分界清晰是远曲小管的特点。"},{"q":"下列哪种细胞的滑面内质网最发达","o":["催乳素细胞","肾上腺皮质细胞","肾上腺髓质细胞","滤泡旁细胞","滤泡上皮细胞"],"a":1,"e":"肾上腺皮质细胞分泌类固醇激素，滑面内质网最发达，含管状嵴线粒体和脂滴；含氮激素分泌细胞则以粗面内质网发达为特点。"},{"q":"关于输尿管芽，下列哪项错误","o":["是中肾管末端近泄殖腔处长出的盲管","属于中胚层组织","部分分化物参与构成泌尿小管","其分支末端诱导生后肾原基形成肾小体","其分支末端将与肾小管接通"],"a":3,"e":"输尿管芽末端反复分支只分化为肾盂、肾盏和集合管；肾小体由生后肾原基形成的肾小管一端膨大凹陷而成，输尿管芽仅起诱导作用。"},{"q":"关于单层柱状上皮的描述，哪项正确","o":["由一层棱柱状细胞组成","胞核长圆形，位细胞中央","常分布于消化道、呼吸管道","以保护功能为主","游离面常见微绒毛和纤毛"],"a":0,"e":"单层柱状上皮由一层棱柱状细胞组成，核椭圆形且长轴与细胞长轴平行，多分布于胃、肠、胆囊和子宫腔面，游离面常有微绒毛。"},{"q":"消化系统和呼吸系统的发生在一章内叙述，是因为","o":["两者都是管道性器官组成","两者的主要器官均来自原始消化管","两者均经口与鼻与外界相通","两者的管壁均分黏膜、黏膜下层、肌层和外膜","机体通过两者从外界摄取物质"],"a":1,"e":"消化系统与呼吸系统的主要器官均起源于原始消化管，其头段前肠演变为咽、食管、胃、肝、胰及呼吸道原基，故合为一章叙述。"},{"q":"胆囊的主要功能是","o":["合成胆汁","贮存、浓缩和释放胆汁","分解胆汁","分泌消化脂类的酶","贮存消化的食物"],"a":1,"e":"胆囊黏膜上皮吸收水和电解质使肝胆汁浓缩，并贮存胆汁，进食后经胆囊收缩排入十二指肠；胆汁由肝细胞合成，胆囊不产生消化酶。"},{"q":"关于红细胞描述错误的是","o":["外周血红细胞均无细胞器","胞质中充满血红蛋白","细胞呈双凹圆盘状","细胞膜上有ABO血型抗原","向全身的组织和细胞供给氧气，带走二氧化碳"],"a":0,"e":"成熟红细胞无核无细胞器，但外周血中仍含少量网织红细胞，其胞质内残存核糖体等结构，故“均无细胞器”的表述过于绝对。"},{"q":"参与室间隔膜部形成的结构有","o":["第一房间隔和第二房间隔的结缔组织","心内膜垫和左右心球嵴的结缔组织","半月瓣基部未分化的结缔组织","房室瓣基部未分化的结缔组织","心球和心内膜垫的结缔组织"],"a":1,"e":"室间隔膜部由心内膜垫的结缔组织与左、右心球嵴融合下延的结缔组织共同形成，封闭室间孔；肌部由心室底壁肌层向上生长而成。"},{"q":"骨板由（ ）组成","o":["骨细胞、胶原纤维和钙盐","弹性纤维、有机基质和钙盐","胶原纤维、弹性纤维和钙盐","胶原纤维、有机基质和钙盐","胶原纤维、弹性纤维、网状纤维和钙盐"],"a":3,"e":"骨板由胶原纤维、有机基质和钙盐沉积而成，纤维平行或同心排列并钙化；骨细胞位于骨板之间或骨陷窝内，不参与骨板组成。"},{"q":"心外膜的组成是","o":["间皮","脂肪组织","间皮和结缔组织","间皮和脂肪组织","结缔组织和平滑肌"],"a":2,"e":"心外膜即浆膜性心包的脏层，表面为一层间皮，深部为疏松结缔组织，含脂肪、血管和神经；心肌膜与心内膜均无间皮。"},{"q":"下面对软骨细胞的描述，哪项是错误的","o":["近软骨膜处的软骨细胞较幼稚","软骨中央处的软骨细胞较成熟","同源细胞群是由一个软骨细胞分裂增殖而来","同源细胞群是软骨细胞逐渐集合而成","同源细胞群中每个细胞都有各自的软骨陷窝和软骨囊"],"a":3,"e":"同源细胞群由一个幼稚软骨细胞分裂增殖而来，含2～8个细胞，各细胞有独立的软骨陷窝和软骨囊，并非细胞逐渐集合而成。"},{"q":"形成原条的胚层是","o":["下胚层","上胚层","胚内中胚层","胚外中胚层","内胚层"],"a":1,"e":"原条由上胚层细胞向尾侧中线迁移增殖形成，并诱导中胚层和内胚层发生；三个胚层均起源于上胚层，下胚层不参与胚体形成。"},{"q":"子宫内膜为分泌期时，卵巢的结构是","o":["卵泡开始发育和成熟","卵泡退化阶段","黄体正在形成和发育","黄体正在退化","卵泡膜正在形成"],"a":2,"e":"分泌期相当于月经周期第15～28天，排卵后残存卵泡壁形成黄体并继续发育，分泌孕激素和雌激素；黄体退化即转入月经期。"},{"q":"关于胸腺细胞的描述，错误的是","o":["是胸腺内分化发育的各期T细胞","外皮质层的大淋巴细胞为前胸腺细胞","深皮质层的淋巴细胞体积较小，为普通胸腺细胞，数量多","凡不能与自身抗原相结合或与自身MHC抗原相容的胸腺细胞将被灭活或淘汰","成熟的普通胸腺细胞，其CD4和CD8中有一种增强，另一种减弱或消失"],"a":3,"e":"阳性选择保留能与自身MHC分子结合的胸腺细胞，阴性选择淘汰与自身抗原高亲和力结合者；不能与自身抗原结合并非淘汰标准。"},{"q":"在口腔开口处渐变为复层扁平上皮的导管是","o":["闰管","纹状管","小叶间导管","总导管","小叶内导管"],"a":3,"e":"唾液腺的总导管在口腔开口处上皮由单层柱状渐变为复层扁平上皮；闰管、纹状管和小叶间导管均保持单层上皮。"},{"q":"足月分娩时羊水量为","o":["500～1000ml","500～1500ml","500～2000ml","1000～1500ml","1000～2000ml"],"a":3,"e":"足月妊娠羊水量约1000～1500ml，少于300ml为羊水过少，超过2000ml为羊水过多，两者均提示胎儿发育异常的可能。"},{"q":"神经元内的尼氏体是电镜下的","o":["溶酶体","粗面内质网和游离核糖体","线粒体","高尔基复合体","游离核糖体和滑面内质网"],"a":1,"e":"尼氏体电镜下由发达的粗面内质网和游离核糖体构成，是神经元合成蛋白质的场所，分布于胞体和树突内，轴突内缺如。"},{"q":"胎儿血循环中，以下哪个血管中的血液含氧量最低","o":["主动脉弓","肺动脉","脐动脉","降主动脉","动脉导管"],"a":2,"e":"脐动脉将胎儿体内含氧最低、含代谢废物多的血液送入胎盘，经母胎交换后由脐静脉以富氧血返回胎儿。"},{"q":"分泌物含黏液的腺体是","o":["舌下腺","腮腺","汗腺","胰腺","泪腺"],"a":0,"e":"舌下腺为混合腺且以黏液性腺泡为主，分泌物含大量黏液；腮腺为纯浆液腺，胰腺和泪腺亦属浆液腺，汗腺分泌汗液不含黏液。"},{"q":"脑脊液是由下列哪种结构分泌的","o":["脉络丛上皮下的毛细血管","脉络膜","脉络丛上皮","室管膜上皮","蛛网膜"],"a":2,"e":"脉络丛由软膜与室管膜突入脑室形成，其表面的室管膜上皮具分泌功能，主动转运产生脑脊液；脉络膜本身不分泌脑脊液。"},{"q":"淋巴小结生发中心内主要增殖的细胞是","o":["T淋巴细胞","B淋巴细胞","K细胞","NK细胞","浆细胞"],"a":1,"e":"次级淋巴小结的生发中心以B淋巴细胞为主，暗区为增殖活跃的大B细胞，明区含较小B细胞、Th细胞和巨噬细胞。"},{"q":"关于螺旋器的描述，哪项错误","o":["位于膜蜗管的基底膜上","每个耳蜗中的螺旋器为一连续性的整体","上皮由毛细胞和支持细胞组成","内毛细胞排成3～4列，外毛细胞排成1列","毛细胞的游离面有规则排列的静纤毛"],"a":3,"e":"螺旋器内毛细胞排成1列，外毛细胞排成3～4列，分别坐落于内、外指细胞顶部的凹陷内；题干所述排列正好颠倒。"},{"q":"关于胎儿血液循环，哪项错误","o":["脐静脉血主要从静脉导管流入下腔静脉","进入右心房的血主要经卵圆孔入左心房","肺动脉的血大部经动脉导管入主动脉","主动脉弓的血大部分布到头颈部","脐动脉富含氧气的血流向胎盘"],"a":4,"e":"脐动脉将胎儿体内含代谢废物和二氧化碳多的低氧血送入胎盘，并非富含氧；脐静脉才输送来自母体的富氧血。"},{"q":"诱导神经管发生的结构是","o":["脊索","原条","原结","体节","神经沟"],"a":0,"e":"脊索形成后诱导其背侧中线的外胚层增厚为神经板，继而卷曲成神经管；原条、原结参与中胚层发生，体节为中胚层分化物。"},{"q":"浦肯野纤维位于","o":["心室的内皮下层","心室的心内膜下层","心房的心肌层浅部","心肌层深部","心房的心内膜下层"],"a":1,"e":"浦肯野纤维是房室束及其各级分支的主要细胞，位于心室的心内膜下层并伸入心肌膜，心房壁内无浦肯野纤维。"},{"q":"以下哪种细胞不产生纤维和基质","o":["成纤维细胞","成软骨细胞","成骨细胞","肥大细胞","腱细胞"],"a":3,"e":"肥大细胞合成组胺、白三烯和肝素，贮存于分泌颗粒，不产生纤维和基质；成纤维细胞、成软骨细胞、成骨细胞和腱细胞均能合成基质成分。"},{"q":"来源于B淋巴细胞的是","o":["巨噬细胞","浆细胞","肥大细胞","嗜碱性粒细胞","嗜酸性粒细胞"],"a":1,"e":"初始B淋巴细胞受抗原刺激后增殖分化，大部分子细胞成为效应B细胞即浆细胞，分泌抗体；巨噬细胞、肥大细胞和粒细胞另有来源。"},{"q":"以下关于皮肤的描述，正确的是","o":["是上皮组织，具备上皮组织的特点","可分为5层：基底层、棘层、颗粒层、透明层和角质层","是一个独立的器官","由表皮、真皮和皮下组织共同组成","可见丰富的神经末梢，但是没有血管分布"],"a":2,"e":"皮肤由表皮、真皮和附属器构成，具屏障、感觉、调节体温和免疫等功能，是机体内最大的独立器官；皮下组织属浅筋膜，不归入皮肤。"},{"q":"小脑皮质的传出神经元是","o":["浦肯野细胞","高尔基细胞","篮状细胞","颗粒细胞","星形细胞"],"a":0,"e":"小脑皮质唯一的传出神经元是浦肯野细胞，其轴突止于小脑深部核团；颗粒细胞、篮状细胞、星形细胞和高尔基细胞均为中间神经元。"},{"q":"近端小管管壁上皮游离面的微绒毛在光镜下称为","o":["微绒毛","纹状缘","刷状缘","皱褶缘","螺旋缘"],"a":2,"e":"近端小管游离面密集规则的微绒毛在光镜下称刷状缘，可扩大重吸收面积；纹状缘是远曲小管基部纵纹的表现，皱褶缘见于破骨细胞。"},{"q":"质膜内褶处细胞质内常含有丰富的","o":["粗面内质网","滑面内质网","溶酶体","高尔基复合体","线粒体"],"a":4,"e":"质膜内褶是上皮细胞基底面细胞膜折向胞质形成的皱褶，褶间含大量纵行线粒体，为主动转运提供能量，常见于肾小管。"},{"q":"下一对甲状旁腺和上一对甲状旁腺的发生是","o":["第3对咽囊腹侧份的上皮增生分化而成","第3对咽囊背侧份的上皮增生分化而成","第4对咽囊腹侧份的上皮增生分化而成","第3和第4对咽囊腹侧份的上皮增生分化而成","第3和第4对咽囊背侧份的上皮增生分化而成"],"a":4,"e":"下对甲状旁腺来自第3对咽囊背侧份，上对来自第4对咽囊背侧份；两咽囊腹侧份分别形成胸腺原基和后鳃体。"},{"q":"透明膜病是由于","o":["Ⅱ型肺泡细胞发育不良","Ⅰ型肺泡细胞发育不良","肺泡表面活性物质分泌过多","肺泡表面有一层纤毛","肺泡不能扩张"],"a":0,"e":"Ⅱ型肺泡细胞分泌肺泡表面活性物质，降低肺泡表面张力；其发育不良或分泌不足使肺泡不能稳定扩张，出生后进行性呼吸困难即透明膜病。"},{"q":"胚内体腔发生于","o":["侧中胚层","体节","间介中胚层","内胚层","轴旁中胚层"],"a":0,"e":"侧中胚层裂开形成胚内体腔，其脏层与壁层参与浆膜形成；体节分化为中轴骨骼和骨骼肌，间介中胚层形成泌尿生殖器官。"},{"q":"心脏房室束及其分支位于","o":["内皮下层","心肌膜浅层","心内膜下层","心肌膜深层","心外膜"],"a":2,"e":"房室结、房室束及其主要分支位于心内膜下层，分支末端伸入心室心肌膜；窦房结位于上腔静脉与右心耳交界处的心外膜深部。"},{"q":"胚泡植入的正常部位是","o":["子宫底和体部内膜的功能层","子宫颈部黏膜","子宫内膜基底层与肌层之间","子宫内膜基底层","输卵管黏膜"],"a":0,"e":"胚泡正常植入部位为子宫底和体部内膜的功能层，此处血供丰富；植入宫颈、输卵管或基底层则分别形成前置胎盘、宫外孕等异常。"},{"q":"对于大部分静脉来说，最厚的部分是","o":["内膜","内皮下层","中膜","环形平滑肌","外膜"],"a":4,"e":"多数静脉中膜薄，平滑肌和弹性纤维少，外膜最厚且含纵行平滑肌束，起支持和防止血管过度扩张的作用。"},{"q":"静脉瓣","o":["内皮凸入管腔折叠而成，见于全部静脉","内皮凸入管腔折叠而成，见于中静脉和大静脉","内膜凸入管腔折叠而成，见于全部静脉","内膜凸入管腔折叠而成，仅见于大静脉","内膜凸入管腔折叠而成，见于中静脉和大静脉"],"a":4,"e":"静脉瓣由内膜向管腔折叠形成，表面覆内皮、中央为结缔组织，可防止血液逆流，多见于中静脉和大静脉，小静脉与微静脉无瓣。"},{"q":"以下哪项不是淋巴细胞的特点","o":["约为白细胞总数的50%～70%","根据细胞形态分为大、中、小三种","血液中小淋巴细胞数量最多","根据功能的不同又可分为T、B、NK等","B淋巴细胞参与机体的体液免疫"],"a":0,"e":"淋巴细胞约占白细胞总数的20%～40%，50%～70%是中性粒细胞的比例；小淋巴细胞数量最多，按功能可分为T、B、NK细胞。"},{"q":"下列不是中央乳糜管的结构特点的是","o":["管壁由一层内皮组成","内皮细胞间隙较大","基膜明显","通透性强","乳糜微粒容易进入管内"],"a":2,"e":"中央乳糜管是小肠绒毛固有层中央的毛细淋巴管，管壁仅由一层内皮构成，内皮间隙大、无基膜、通透性高，利于乳糜微粒进入。"},{"q":"关于垂体的中间部，以下哪项正确","o":["比远侧部小，比神经部大","含神经胶质细胞","无分泌细胞","属神经垂体","有滤泡"],"a":4,"e":"垂体中间部含嗜碱性细胞和滤泡，滤泡腔内可有胶质；中间部属腺垂体，与神经部合称垂体后叶，但不含神经胶质细胞。"},{"q":"神经元的轴突内缺少","o":["神经丝","微管","微丝","粗面内质网","线粒体"],"a":3,"e":"轴突内无粗面内质网和游离核糖体，不能合成蛋白质，所需蛋白质由胞体合成后经轴突运输送来；神经丝、微管、微丝和线粒体均存在。"},{"q":"以下关于光镜下神经元的特征，哪项是错误的","o":["细胞形态多种多样，均有突起","分为细胞体、树突和轴突三部分","核大而圆，异染色质少，核仁明显","胞体及突起内均有尼氏体","胞体及突起内均有神经原纤维"],"a":3,"e":"尼氏体仅见于胞体和树突内，轴突及轴丘处缺如，故“胞体及突起内均有尼氏体”错误；神经原纤维则见于胞体、树突和轴突。"},{"q":"支气管哮喘时，环形平滑肌发生痉挛性收缩的管道主要是","o":["叶支气管","段支气管","小支气管","终末细支气管","呼吸性细支气管"],"a":3,"e":"支气管哮喘时痉挛的环形平滑肌主要位于细支气管和终末细支气管，此处无软骨支撑而平滑肌相对丰富，收缩使管腔明显狭窄。"},{"q":"神经元胞体不分布于","o":["神经","神经丛","神经节","灰质","神经核"],"a":0,"e":"神经元胞体集中于灰质、神经核和神经节内，构成神经的只是神经纤维及其被膜，故神经内无神经元胞体。"},{"q":"关于皮肤黑素细胞，哪项错误","o":["是多突起的细胞","内含黑素颗粒比角质形成细胞多","可把黑素颗粒转移给角质形成细胞","白种人和黑种人的黑素细胞数量相差不大","酪氨酸酶丰富"],"a":1,"e":"黑素颗粒形成后迅速运至突起末端并被角质形成细胞吞入，故黑素细胞内颗粒少而角质形成细胞内较多，一个黑素细胞可供应多个角质形成细胞。"},{"q":"无毛细血管分布的组织是","o":["骨骼肌","软骨组织","肌腱","平滑肌","韧带"],"a":1,"e":"软骨组织内无血管和淋巴管，营养由软骨膜血管经基质扩散供应；骨骼肌、平滑肌、肌腱和韧带均有血管分布。"},{"q":"嗜碱性粒细胞的颗粒内含有","o":["白三烯和组胺","白三烯和肝素","组胺、肝素","芳基硫酸酯酶","组胺酶"],"a":2,"e":"嗜碱性粒细胞颗粒内含肝素、组胺及中性粒细胞、嗜酸性粒细胞趋化因子；白三烯由细胞膜脂质代谢产生后释放，不贮存于颗粒。"},{"q":"中肾发生的描述中，哪一项错误","o":["发生于前肾尾侧的中肾嵴内","中肾小管的一端膨大，并内陷成肾小囊","背主动脉分支而来的毛细血管与肾小囊共同构成肾小体","中肾小管的另一端开口于体腔","中肾管由前肾管演化而来"],"a":3,"e":"中肾小管内侧端膨大凹陷成肾小囊，包绕血管球形成肾小体，外侧端通入中肾管；开口于胚内体腔的是前肾小管。"},{"q":"关于前列腺的描述，哪项是错误的","o":["分泌物为稀薄的乳白色液体","腺实质分3带，即尿道周带、内带和外带","分泌部腺腔不规则，腔内可见凝固体或结石","其分泌活动受雄激素的影响","前列腺癌多发生于尿道周带"],"a":4,"e":"前列腺分尿道周带、内带和外带，老年人良性增生多发生于尿道周带与内带，前列腺癌则多起于外带。"},{"q":"一名医学生在做解剖实验时发现肝的脏面有一条纤维索，其一端连着下腔静脉，另一端连着门静脉左支。这条纤维索胚胎时期对应的结构是","o":["静脉韧带","静脉导管","肝圆韧带","脐动脉","脐静脉"],"a":1,"e":"该纤维索为静脉韧带，是胎儿期静脉导管的遗迹；静脉导管连接左脐静脉与下腔静脉，出生后闭锁，肝圆韧带则是脐静脉的遗迹。"},{"q":"关于成神经细胞正确的是","o":["由室管膜层迁移至神经上皮外周","有分裂增生的能力","位于神经管套层，分化为神经元","位于边缘层","分化为神经元和神经胶质细胞"],"a":2,"e":"套层的成神经细胞先为无突起细胞，继而长出突起分化为神经元；边缘层只有其突起构成的神经纤维，成神经细胞已失去分裂能力。"},{"q":"下列哪项结构不是起源于内胚层","o":["生精细胞","阴道前庭","男性尿道海绵体部","膀胱与输尿管交界处","女性尿道"],"a":3,"e":"输尿管与膀胱三角区下部来自中肾管末端，属中胚层；生精细胞源于卵黄囊内胚层，阴道前庭、男性尿道海绵体部和女性尿道均来自尿生殖窦内胚层。"},{"q":"结肠不同于小肠的结构在于","o":["有环行皱襞和绒毛，杯状细胞多，固有层内肠腺发达，有结肠带","有环行皱襞，无绒毛，杯状细胞特别多，固有层内肠腺较少，有结肠带","有半环行皱襞和绒毛，杯状细胞多，固有层内肠腺发达，有结肠带","有半环行皱襞，无绒毛，杯状细胞较少，固有层内肠腺发达，有结肠带","有半环行皱襞，无绒毛，杯状细胞特别多，固有层内肠腺发达，有结肠带"],"a":4,"e":"结肠有半环行皱襞但无绒毛，杯状细胞特别多，固有层肠腺发达，并具结肠带、结肠袋和肠脂垂；小肠则有环行皱襞和绒毛。"},{"q":"生精上皮的基底室内","o":["无生精细胞","有精母细胞","有精原细胞，初级和次级精母细胞","只有初级精母细胞","只有精原细胞"],"a":4,"e":"生精上皮基底室位于支持细胞紧密连接与基膜之间，仅含精原细胞；精母细胞和精子细胞位于近腔室，故基底室内不见精母细胞。"},{"q":"对骨骼肌的描述，错误的一项是","o":["长圆柱状","单核","横纹明显","含大量肌原纤维","肌纤维周围有肌卫星细胞"],"a":1,"e":"骨骼肌纤维为长圆柱状多核细胞，核位于肌膜下方，肌原纤维发达、横纹明显，肌膜外有肌卫星细胞；单核居中是心肌纤维的特点。"},{"q":"脾脏不具有下列哪项功能","o":["产生抗体和效应淋巴细胞","边缘区和脾索有滤血功能","脾脏可储存部分血细胞","脾小体可分泌激素","严重缺血时可恢复造血功能"],"a":3,"e":"脾是最大的外周淋巴器官，具有滤血、储血、免疫应答和应激时造血的功能；脾小体即白髓淋巴小结，为B细胞区，不分泌激素。"},{"q":"具有趋化性的细胞是","o":["成纤维细胞","巨噬细胞","肥大细胞","浆细胞","脂肪细胞"],"a":1,"e":"巨噬细胞可沿趋化因子浓度梯度定向移动，趋化性是其发挥吞噬和免疫监视功能的前提；成纤维细胞、浆细胞、脂肪细胞无此特性。"},{"q":"肺泡Ⅰ型细胞的特征正确的是","o":["不参与构成气-血屏障","细胞为立方形，染色浅","胞质内细胞器少，但含有大量吞饮小泡","损伤后可自我增殖分化补充","细胞菲薄处有大量窗孔"],"a":2,"e":"Ⅰ型肺泡细胞胞体扁平，覆盖肺泡大部分表面，胞质内细胞器少而吞饮小泡多，参与构成气-血屏障；损伤后由Ⅱ型细胞增殖补充。"},{"q":"关于表皮各层细胞结构特点的描述，哪项错误","o":["基底层细胞能不断增殖，分化为表皮其他层的细胞","基底层细胞胞质内含板层颗粒","颗粒层细胞质内有透明角质颗粒，板层颗粒多","透明层细胞的胞核和细胞器退化，光镜下为嗜酸均质状","角质层细胞胞质内充满角蛋白丝"],"a":1,"e":"板层颗粒出现于棘层细胞内，至颗粒层增多，内含糖脂和酸性磷酸酶，可形成膜状物封闭细胞间隙；基底层细胞不含板层颗粒。"},{"q":"关于呼吸性细支气管，下列哪项错误","o":["是终末细支气管的分支，一条终末细支气管可分支形成2～3条呼吸性细支气管","是肺呼吸部的一部分","上皮为假复层纤毛柱状上皮，有纤毛细胞和分泌细胞两种","上皮下结缔组织中有少量结缔组织和环行平滑肌","已开始具有气体交换的功能"],"a":2,"e":"呼吸性细支气管管壁已有肺泡开口，上皮由单层纤毛柱状渐变为单层立方，含纤毛细胞和克拉拉细胞，并非假复层纤毛柱状上皮。"},{"q":"分泌醛固酮的结构是","o":["肾上腺皮质网状带","肾上腺髓质嗜铬细胞","嫌色细胞","肾上腺皮质球状带","垂体细胞"],"a":3,"e":"肾上腺皮质球状带细胞分泌醛固酮，受肾素-血管紧张素系统调节；束状带分泌糖皮质激素，网状带分泌雄激素，髓质嗜铬细胞分泌儿茶酚胺。"},{"q":"关于初级精母细胞的描述，错误的是","o":["位于精原细胞近腔侧","细胞大，核大而圆，染色质粗网状","染色体核型为46，XY","经两次分裂形成4个次级精母细胞","成熟分裂过程历时较长，故生精小管切面上易于见到"],"a":3,"e":"初级精母细胞经第一次减数分裂形成2个次级精母细胞，后者经第二次减数分裂形成4个精子细胞，一次成熟分裂并不能得到4个次级精母细胞。"},{"q":"关于视网膜色素上皮细胞描述，错误的是","o":["单层矮柱状细胞，基部附于玻璃膜","细胞顶部胞质突伸入视细胞之间","胞质内含有黑素颗粒和吞噬体","储存维生素A，参与视紫红质的合成","能感受强光，增强视锥细胞的功能"],"a":4,"e":"色素上皮细胞能吞噬视细胞脱落的膜盘、储存维生素A并参与视紫红质合成、吸收杂散光线，不感受光刺激；感强光并辨色的是视锥细胞。"},{"q":"老花眼是由于","o":["角膜曲度改变","晶状体弹性减弱","玻璃体混浊","房水减少","房水过多"],"a":1,"e":"老花眼因晶状体随年龄增长弹性减弱、睫状肌调节力下降，看近物时不能充分变凸；角膜曲度改变、房水异常或玻璃体混浊另有相应表现。"},{"q":"从小肠吸收来的营养物质运输至肝细胞的途径为","o":["肝动脉→小叶间动脉→肝血窦→肝细胞","肝静脉→小叶间静脉→肝血窦→肝细胞","门静脉→小叶间静脉→肝血窦→肝细胞","门静脉→小叶下静脉→肝血窦→肝细胞","肝静脉→小叶下静脉→肝血窦→肝细胞"],"a":2,"e":"小肠吸收的营养物质经肠系膜静脉汇入门静脉，在肝内行于小叶间静脉，再经肝血窦与肝细胞接触；肝动脉供氧，肝静脉为流出道。"},{"q":"胸腺小体位于胸腺的","o":["皮质","皮质与髓质交界处","皮质和髓质","小叶间隔内","髓质"],"a":4,"e":"胸腺小体由同心圆排列的退化上皮细胞构成，位于胸腺髓质，是胸腺的特征性结构；皮质内以密集的胸腺细胞为主，无胸腺小体。"},{"q":"内耳的内淋巴液来自","o":["脑脊液","组织液","骨膜内的毛细血管","血管纹","内淋巴囊"],"a":3,"e":"血管纹位于膜蜗管外侧壁、覆盖于螺旋韧带表面，为含毛细血管的复层上皮，主动分泌形成内淋巴；内淋巴囊仅参与引流吸收。"},{"q":"原始生殖细胞发生于","o":["尿囊内胚层","卵黄囊的胚外中胚层","未分化性腺的初级性索","生殖腺嵴的表面上皮","卵黄囊顶近尿囊处的内胚层"],"a":4,"e":"原始生殖细胞起源于卵黄囊顶近尿囊处的内胚层，随后沿后肠背系膜迁移至生殖腺嵴，在性别分化前两性过程相同。"},{"q":"神经元尼氏体是","o":["发出轴突的部位","合成蛋白质的场所","接受刺激的部位","轴突运输的载体","储存神经递质的结构"],"a":1,"e":"尼氏体富含粗面内质网和游离核糖体，是神经元合成蛋白质的场所，其形态和数量反映细胞的功能状态，损伤时溶解消失。"},{"q":"长骨骨干的间骨板位于","o":["骨单位与环骨板之间","骨单位中央","骨单位之间或骨单位与环骨板之间","外环骨板内","内环骨板"],"a":2,"e":"间骨板是骨改建时残留的旧骨板，填充于相邻骨单位之间或骨单位与内、外环骨板之间，其中无中央管。"},{"q":"关于肾小体的滤过作用，下列哪项是错误的","o":["毛细血管球的内皮细胞有孔","基膜具有通透性","裂孔膜可通透分子量为70KD以下的物质","血管球，位于皮质迷路和髓放线内","入球小动脉短粗，出球小动脉细长，致使血管球内血压较高"],"a":3,"e":"肾小体位于皮质迷路和肾柱内，髓放线内只有肾小管直部和集合管；滤过屏障由有孔内皮、基膜和足细胞裂孔膜构成。"},{"q":"脊髓内分化为躯体运动神经元的成神经细胞位于","o":["基板","翼板","顶板","底板","基板和翼板之间"],"a":0,"e":"基板位于神经管腹侧，其成神经细胞分化为躯体运动神经元，轴突组成前根；翼板位于背侧，分化为感觉性中间神经元。"},{"q":"喉气管先天性狭窄或闭锁是由于","o":["平滑肌痉挛收缩","软骨环增生肥大","间质水肿压迫","甲状腺增生肥大压迫","管腔重建过程受阻"],"a":4,"e":"喉与气管发生中上皮一度过度增生使管腔闭塞，随后细胞退化吸收以重建管腔；此过程受阻即致先天性狭窄或闭锁。"},{"q":"关于子宫内膜，下列哪项错误","o":["内膜全层均有周期性脱落变化","其周期性变化受下丘脑分泌的激素影响","上皮中分泌细胞多于纤毛细胞","子宫腺也可有少量纤毛细胞","卵泡刺激素可通过影响卵巢功能进而影响子宫内膜周期性变化"],"a":0,"e":"月经期仅功能层剥脱，基底层保留并增殖修复；内膜周期性变化受卵巢激素调控，卵巢功能又受下丘脑和腺垂体促性腺激素调节。"},{"q":"关于单卵双胎结果的描述，哪一项不可能","o":["均为男性","均为女性","性别各异","可能发生连体畸形","可能发生寄生胎"],"a":2,"e":"单卵双胎由一个受精卵发育为两个胚胎，遗传物质相同，性别必然一致；双卵双胎才可能性别不同，单卵双胎可发生连体畸形或寄生胎。"},{"q":"长骨骨干骨密质内的血管走行于","o":["中央管和骨小管内","中央管和穿通管内","穿通管和骨小管内","只在中央管内","骨小管内"],"a":1,"e":"长骨骨干骨密质内的血管穿行于中央管和横向的穿通管，骨小管内仅有骨细胞突起和组织液，无血管通行。"},{"q":"次级性索来自","o":["未分化性腺的表面上皮","初级性索","皮质索","脏壁中胚层","体壁中胚层"],"a":0,"e":"次级性索又称皮质索，由未分化性腺表面的体腔上皮向深部增生形成，断裂后围绕原始生殖细胞构成原始卵泡；初级性索退化消失。"},{"q":"在心肌闰盘的纵向连接面上有","o":["紧密连接","中间连接","桥粒","缝隙连接","中间连接和桥粒"],"a":3,"e":"闰盘横位部分有中间连接和桥粒，起机械连接作用；纵位部分存在缝隙连接，便于离子通过，使心肌细胞同步舒缩。"},{"q":"淋巴结内发生细胞免疫应答时，结构明显增大的是","o":["浅层皮质","副皮质区","髓索","髓窦","毛细血管后微静脉"],"a":1,"e":"副皮质区为胸腺依赖区，细胞免疫应答时T淋巴细胞在此增殖转化，区域明显增厚；体液免疫应答则以浅层皮质淋巴小结增大为主。"},{"q":"化学突触内与神经冲动传递直接相关的结构是","o":["线粒体","微管","突触小泡","微丝","神经丝"],"a":2,"e":"突触小泡内含乙酰胆碱或单胺类等神经递质，冲动到达时以胞吐方式释放，是信息传递的关键结构；线粒体仅供能，微管微丝起支架和运输作用。"},{"q":"分泌具有抗恶性贫血的内因子的细胞是","o":["表面黏液细胞","颈黏液细胞","主细胞","壁细胞","Paneth细胞"],"a":3,"e":"壁细胞分泌盐酸和内因子，内因子与维生素B12结合后促其在回肠吸收，缺乏时维生素B12吸收障碍而致巨幼细胞性贫血即恶性贫血。"},{"q":"附睾管起源于","o":["中肾旁管","中肾管","生殖腺索","中肾小管","输尿管芽"],"a":1,"e":"附睾管由中肾管演变而来，中肾小管形成睾丸输出小管；中肾旁管在男性退化为睾丸附件，输尿管芽形成输尿管和集合管系统。"},{"q":"肾上腺髓质的特征中哪项是错误的","o":["具有分泌类固醇激素细胞的超微结构特征","胞质中有许多嗜铬颗粒","细胞索互联成网，网孔中有窦状毛细血管","有少量交感神经节细胞分布","可分泌肾上腺素和去甲肾上腺素"],"a":0,"e":"肾上腺髓质细胞属含氮激素分泌细胞，胞质含嗜铬颗粒，分泌肾上腺素和去甲肾上腺素，受交感神经节前纤维支配，无类固醇激素分泌细胞的结构特征。"},{"q":"下列哪种细胞不是单核吞噬细胞系统的细胞成员","o":["血液内的单核细胞","神经组织的少突胶质细胞","结缔组织内的巨噬细胞","尘细胞","库普弗细胞"],"a":1,"e":"单核吞噬细胞系统包括血液单核细胞、结缔组织巨噬细胞、肝库普弗细胞、肺尘细胞和骨破骨细胞等；少突胶质细胞属神经胶质细胞，不属此系统。"},{"q":"关于中耳的描述，哪项错误","o":["鼓室内表面有黏膜","听小骨表面无黏膜","听小骨之间有关节连接","咽鼓管近鼓室段的黏膜上皮为单层柱状","咽鼓管近鼻咽段的黏膜上皮为假复层纤毛柱状"],"a":1,"e":"鼓室内表面及3块听小骨表面均覆有薄层黏膜，听小骨之间以关节相连，关节面为透明软骨，故听小骨表面并非无黏膜。"},{"q":"视杆细胞和视锥细胞共有的特征不包括","o":["属高度分化的感觉神经元","细胞分为胞体、内突和外突","外突和双极神经元形成突触","外节基部细胞膜内褶形成膜盘","膜盘上镶嵌有感光物质"],"a":2,"e":"视杆、视锥细胞的内突与双极细胞形成突触，外突即外节含膜盘和感光物质，是感光部位，不与双极细胞形成突触。"},{"q":"肾内可分泌肾素的细胞是","o":["球内系膜细胞","球旁细胞","球外系膜细胞","间质细胞","足细胞"],"a":1,"e":"球旁细胞由入球微动脉近血管极处的平滑肌细胞上皮样变而来，胞质含分泌颗粒并分泌肾素；致密斑为化学感受器，球外系膜细胞具吞噬功能。"},{"q":"视网膜视部的感光部位是","o":["视细胞所在的部位","视细胞内突所在的部位","视细胞胞体所在的部位","视细胞外突的内节所在的部位","视细胞外突的外节所在的部位"],"a":4,"e":"视细胞外突分为内节和外节，外节内排列含视紫红质或视紫蓝质的膜盘，是感光物质所在部位，故感光部位为外节。"},{"q":"在妊娠后期，乳汁内的初乳小体是","o":["乳蛋白凝块","吞噬脂滴的巨噬细胞","分泌抗体的浆细胞","脱落的导管上皮细胞","脱落的腺细胞"],"a":1,"e":"初乳小体是吞噬脂滴的巨噬细胞；初乳含多量蛋白质和抗体而脂肪较少，其中的免疫球蛋白来自血液，故初乳小体并非腺细胞或蛋白凝块。"},{"q":"光镜下表皮颗粒层细胞嗜碱性，是因为含有大量","o":["游离核糖体","张力丝","板层颗粒","透明角质颗粒","角蛋白"],"a":3,"e":"颗粒层细胞胞质内透明角质颗粒大小不等，HE染色呈强嗜碱性，板层颗粒则不着色，此时核与细胞器已退化。"},{"q":"有关单核细胞的描述，哪项错误","o":["是体积最大的血细胞","细胞核多呈肾形","胞质染成蓝灰色","胞质内无颗粒","在血流中停留12～48小时"],"a":3,"e":"单核细胞胞质呈灰蓝色，含较多嗜天青颗粒即溶酶体，并非无颗粒；它是体积最大的血细胞，核多呈肾形，在血中停留12～48小时。"},{"q":"胎儿遗传性别的决定因素是","o":["受精前母体精神状态","参与受精的卵子性染色体","参与受精的精子性染色体","受精后激素作用","受精前环境作用"],"a":2,"e":"胎儿性别由受精时精子所带性染色体决定，含Y染色体的精子受精发育为男性，含X者为女性；卵子只提供X染色体。"},{"q":"来源于尿生殖嵴内侧份的结构是","o":["尿生殖窦","生殖腺嵴","脊索","生肾索","尿生殖结节"],"a":1,"e":"尿生殖嵴内侧份为生殖腺嵴，其表面上皮向深部增生形成性索，与迁入的原始生殖细胞共同发育为睾丸或卵巢；外侧份为生肾索。"},{"q":"生精细胞中存在时间最短的是","o":["精原细胞","初级精母细胞","次级精母细胞","精子细胞","精子"],"a":2,"e":"次级精母细胞存在时间最短，完成第二次减数分裂即形成精子细胞，故切片上不易见到；初级精母细胞历时较长，易于观察。"},{"q":"大脑皮质中的大锥体细胞主要位于","o":["外颗粒层","多形细胞层","内颗粒层","内锥体细胞层","外锥体细胞层"],"a":3,"e":"大脑皮质内锥体细胞层即第Ⅴ层，含大锥体细胞，其轴突下行组成投射纤维至脑干和脊髓；外锥体细胞层为中型锥体细胞。"},{"q":"锥体细胞分布于","o":["小脑皮质","大脑皮质","脊髓灰质","脊髓后角","脊髓前角"],"a":1,"e":"锥体细胞是大脑皮质最主要的神经元，胞体呈锥形，顶树突伸向皮质表面；小脑皮质为浦肯野细胞，脊髓灰质以多极神经元为主。"},{"q":"关于甲状腺的结构特征，哪项是错误的","o":["甲状腺滤泡主要由滤泡上皮细胞构成","上皮的高低与细胞功能状态密切相关","功能活跃时滤泡上皮细胞内粗面内质网丰富","甲状腺素储存在胞质的分泌颗粒中","滤泡腔内含嗜酸性的胶状物质"],"a":3,"e":"甲状腺激素以胶质形式贮存于滤泡腔内，而非胞质分泌颗粒；释放时经胞吞胶质小泡、溶酶体水解成T3、T4后入血。"},{"q":"关于主肺动脉隔的发育，哪项是错误的","o":["来自动脉干和心球的心内膜下组织","起初为一对纵行的嵴","以后左、右嵴在中线愈合，形成主肺动脉隔","主肺动脉隔垂直下行","将动脉干和心球分隔成肺动脉干和升主动脉"],"a":3,"e":"主肺动脉隔在动脉干和心球内呈螺旋状走行，故主动脉与肺动脉干离开心脏时相互缠绕；垂直下行则不能形成正常交叉关系。"},{"q":"神经嵴不分化为","o":["脑神经节","神经垂体","周围神经","肾上腺髓质","脊神经节"],"a":1,"e":"神经管分化为中枢神经系统、神经垂体和松果体；神经嵴分化为神经节、周围神经、肾上腺髓质和黑素细胞等。"},{"q":"对血细胞发生的描述，哪项错误","o":["血细胞发生大致分为原始阶段、幼稚阶段和成熟阶段","红、粒系的幼稚阶段又可分为早、中、晚三阶段","红、粒系，单核和巨核细胞系的幼稚阶段也分为早、中、晚三阶段","单核和巨核细胞的幼稚阶段不分早、中、晚三阶段","单核经幼单核、单核，进一步分化为巨噬细胞"],"a":2,"e":"红系和粒系的幼稚阶段分早、中、晚三期，单核细胞和巨核细胞系的幼稚阶段不分早、中、晚三期。"},{"q":"构成神经原纤维的是","o":["神经丝和微丝","微管和微丝","神经丝和张力丝","神经丝和微管","微管和张力丝"],"a":3,"e":"神经原纤维由神经丝和微管构成，在镀银切片中呈棕黑色细丝，构成细胞骨架并参与物质运输；张力丝属上皮细胞的骨架。"},{"q":"关于骨单位的特点，下列哪项错误","o":["多层骨板环绕中央管作同心圆排列","骨单位中央管之间有穿通管相互连通","中央管内无血管及神经","中央管内衬有骨膜","骨单位顺骨干长轴作纵向排列"],"a":2,"e":"中央管内含少量疏松结缔组织、小血管和神经纤维，并与穿通管相通，故“无血管及神经”错误，其内表面也无骨膜衬覆。"},{"q":"关于呼吸道上皮内分泌细胞，哪项错误","o":["属于APUD系统","分泌5-羟色胺","矮柱状，基部胞质内含分泌颗粒","参与神经上皮小体的构成","分泌物必须通过血循环发挥作用"],"a":4,"e":"呼吸道上皮内分泌细胞属APUD系统，矮柱状，基部含分泌颗粒，分泌5-羟色胺等，多以旁分泌方式调节邻近细胞，并非都经血循环起作用。"},{"q":"在神经元的胞体、轴突、树突内均存在的结构是","o":["神经原纤维","高尔基复合体","粗面内质网","中心体","核糖体"],"a":0,"e":"神经原纤维由神经丝和微管组成，贯穿胞体、树突和轴突；尼氏体、高尔基复合体和中心体仅见于胞体及树突近端，轴突内缺如。"},{"q":"角膜基质来源于","o":["神经嵴","间充质","神经外胚层","视杯口边缘部的间充质","表面外胚层"],"a":1,"e":"角膜基质与角膜内皮由间充质细胞分化而来，角膜上皮则来自表面外胚层；巩膜亦由间充质发生。"},{"q":"电镜下，纹状管单层高柱状上皮细胞基部具有","o":["丰富的分泌颗粒","发达的质膜内褶和线粒体","滑面内质网","粗面内质网和核糖体","溶酶体"],"a":1,"e":"纹状管上皮细胞基部有发达的质膜内褶，褶间纵行排列大量线粒体，为主动转运水和电解质供能，故基部呈强嗜酸性纵纹。"},{"q":"肝小叶内产生网状纤维的细胞是","o":["肝巨噬细胞","血窦内皮细胞","肝细胞","贮脂细胞","大颗粒淋巴细胞"],"a":3,"e":"贮脂细胞位于肝血窦与肝细胞之间的窦周隙内，能产生网状纤维和基质，并贮存维生素A；肝细胞产生胶原，内皮细胞不产生网状纤维。"},{"q":"形成小脑的平行纤维的是","o":["高尔基细胞的树突","浦肯野细胞的轴突","篮状细胞的轴突","星形细胞的树突","颗粒细胞的轴突"],"a":4,"e":"颗粒细胞的轴突穿入分子层后呈T形分为两支，与叶片长轴平行走行称平行纤维，与浦肯野细胞树突形成突触；篮状细胞轴突止于浦肯野细胞胞体。"},{"q":"周围神经系统有髓神经纤维的髓鞘形成细胞是","o":["星形胶质细胞","施万细胞","小胶质细胞","卫星细胞","少突胶质细胞"],"a":1,"e":"周围神经系统有髓神经纤维的髓鞘由施万细胞形成，一个施万细胞包卷一段轴突；中枢神经系统的髓鞘由少突胶质细胞形成。"},{"q":"分泌甲状旁腺激素的细胞是","o":["主细胞","嗜碱性细胞","滤泡旁细胞","滤泡上皮细胞","嗜酸性细胞"],"a":0,"e":"甲状旁腺主细胞数量最多，分泌甲状旁腺激素，促进骨盐溶解并增加肠、肾对钙的吸收使血钙升高；滤泡旁细胞分泌降钙素。"},{"q":"关于子宫颈的结构和功能特点，错误的是","o":["黏膜上皮为单层柱状","外口处上皮移行为变移上皮","上皮移行处是宫颈癌的好发部位","黏膜的分泌受卵巢激素的影响","妊娠时分泌物黏稠，可阻止微生物进入子宫"],"a":1,"e":"子宫颈管内为单层柱状上皮，宫颈阴道部为复层扁平上皮，外口处两者移行，此移行区是宫颈癌好发部位，并非移行为变移上皮。"},{"q":"表皮中的哪种细胞来源于血液中的单核细胞","o":["基底细胞","黑素细胞","胶质细胞","梅克尔细胞","朗格汉斯细胞"],"a":4,"e":"朗格汉斯细胞来源于骨髓单核细胞，迁入表皮后具抗原提呈功能；黑素细胞和梅克尔细胞来自神经嵴，基底细胞为角质形成干细胞。"},{"q":"胞质易染色颗粒中含有白三烯的细胞是","o":["巨噬细胞","嗜酸性粒细胞","淋巴细胞","肥大细胞","中性粒细胞"],"a":3,"e":"肥大细胞颗粒内含组胺、肝素等，并合成释放白三烯，引起支气管痉挛和血管扩张；嗜酸性粒细胞含组胺酶和芳基硫酸酯酶，可灭活这些介质。"},{"q":"人胚发育过程中，能根据外生殖器分辨性别是在","o":["第6周","第7周","第12周","第4个月","第5个月"],"a":2,"e":"胚胎第9周前外生殖器不能分辨性别，至第12周左右男女外生殖器分化完成，可据外观辨认；性腺分化始于第7周。"},{"q":"形成精子顶体的细胞器是","o":["中心体","核糖体","线粒体","滑面内质网","高尔基复合体"],"a":4,"e":"高尔基复合体在精子形成中产生顶体颗粒，融合扩大成顶体，覆盖核前2/3；中心体形成轴丝，线粒体形成线粒体鞘。"},{"q":"抗利尿激素从何处释放入血","o":["视上核","室旁核","垂体神经部","垂体远侧部","垂体漏斗部"],"a":2,"e":"抗利尿激素由下丘脑视上核和室旁核神经元合成，经轴突运至神经垂体贮存并在此释放入血；腺垂体远侧部不贮存该激素。"},{"q":"下列哪项不是血管纹的特点","o":["为复层上皮","含有血管","位于椭圆囊外侧壁","覆盖于螺旋韧带表面","能产生内淋巴"],"a":2,"e":"血管纹位于膜蜗管外侧壁、覆盖于螺旋韧带表面，为含毛细血管的复层上皮，能分泌内淋巴；椭圆囊外侧壁无此结构。"},{"q":"关于骨骼肌纤维的光镜结构，哪项是错误的","o":["为细长圆柱形的细胞","有多个细胞核","肌原纤维顺肌纤维的长轴平行排列","细胞核位于肌纤维中央","肌原纤维有明暗相间的横纹"],"a":3,"e":"骨骼肌纤维有多个细胞核，位于肌膜下方靠近肌膜处，肌原纤维平行排列并显示明暗横纹；核居中是心肌纤维的特点。"},{"q":"淋巴组织最丰富的部位是","o":["结肠","回肠","空肠","食管","胃幽门部"],"a":1,"e":"回肠固有层内淋巴小结多而密集，常聚集成集合淋巴小结，淋巴组织最丰富；空肠、结肠和胃的淋巴组织相对较少。"},{"q":"下列关于隐睾的描述中，哪一项是错误的","o":["睾丸可停留在腹股沟管内","睾丸可停留在腹腔内","双侧隐睾可造成不育症","常影响间质细胞的雄激素分泌","出生后1年内仍可降入阴囊"],"a":3,"e":"隐睾时睾丸间质细胞仍分泌雄激素，第二性征多不受影响，主要危害是腹腔温度较高使生精障碍，双侧者可致不育。"},{"q":"浆液性腺细胞的结构特点不包括","o":["细胞核扁平，贴于细胞基底面","基底部胞质嗜碱性","细胞顶部含分泌颗粒","细胞核上区有发达的高尔基复合体","细胞基底部含丰富的粗面内质网"],"a":0,"e":"浆液性腺细胞核圆或椭圆形，位于细胞偏基底部，基底部胞质嗜碱性、顶部含嗜酸性分泌颗粒；核扁平贴于基底是单层扁平上皮的特点。"},{"q":"关于人耳蜗的描述，哪项错误","o":["蜗轴为锥体形，为骨性结构","蜗轴内含螺旋神经节","骨蜗管围绕蜗轴盘旋2周半","骨蜗管自上而下分依次为前庭阶、鼓室阶和膜蜗管","前庭阶和鼓室阶在蜗顶经蜗孔相通"],"a":3,"e":"骨蜗管被膜蜗管分隔为上、下两部，上部为前庭阶、下部为鼓室阶，膜蜗管位于两者之间的外侧壁，并非自上而下依次三层。"},{"q":"气管黏膜表面产生sIgA的细胞是","o":["上皮细胞和浆细胞","上皮细胞和巨噬细胞","内分泌细胞","纤毛细胞和克拉拉细胞","巨噬细胞和克拉拉细胞"],"a":0,"e":"气管黏膜的sIgA由浆细胞产生的二聚体IgA经上皮细胞表面的分泌成分转运入管腔，故需上皮细胞与浆细胞共同参与。"},{"q":"关于甲状腺素的形成，哪项错误","o":["滤泡上皮细胞自血中摄取氨基酸","在溶酶体内水解成T3、T4后释放入血","摄入的碘与甲状腺球蛋白在细胞内结合成碘化甲状腺球蛋白","分泌颗粒以胞吐方式入滤泡腔贮存","甲状腺球蛋白在粗面内质网和高尔基复合体合成加工"],"a":2,"e":"碘在滤泡腔内经过氧化物酶作用与甲状腺球蛋白结合成碘化甲状腺球蛋白，并非在细胞内完成碘化。"},{"q":"关于心肌纤维，哪一项是错误的","o":["单核，有的肌纤维可见双核","肌纤维短圆柱状","有不明显的横纹","肌纤维分支吻合成网","细胞核位于肌膜下"],"a":4,"e":"心肌纤维有1～2个细胞核，位于细胞中央而非肌膜下；肌纤维短圆柱状、有分支吻合成网，横纹不如骨骼肌明显。"},{"q":"具有很强分裂能力的细胞是","o":["黑素细胞","梅克尔细胞","基底细胞","棘细胞","朗格汉斯细胞"],"a":2,"e":"基底细胞为单层矮柱状，是表皮干细胞，增殖分化能力强，不断产生子细胞向浅层推移；黑素细胞、梅克尔细胞和朗格汉斯细胞无此能力。"},{"q":"眼最重要的屈光结构是","o":["角膜","房水","晶状体","玻璃体","黄斑"],"a":2,"e":"晶状体是有弹性的双凸透明体，屈光力强且可调节，是眼球最重要的屈光装置；角膜屈光力虽大但不能调节。"},{"q":"关于间质细胞的描述，哪项是错误的","o":["位于睾丸纵隔内","常成群分布","具有分泌类固醇激素细胞的超微结构特点","体积较大，圆形或立方形","胞质嗜酸性"],"a":0,"e":"睾丸间质细胞成群分布于生精小管之间的间质内，体积较大，胞质嗜酸性，具类固醇激素分泌细胞超微结构，分泌雄激素，并非位于纵隔内。"},{"q":"肺的呼吸部指","o":["终末细支气管及以下分支至肺泡","呼吸性细支气管及以下分支至肺泡","肺泡管及以下分支至肺泡","细支气管及以下分支至肺泡","全部肺泡"],"a":1,"e":"肺呼吸部包括呼吸性细支气管、肺泡管、肺泡囊和肺泡，管壁上有肺泡开口而参与气体交换；终末细支气管属肺的导气部。"},{"q":"下列哪种细胞是抗原提呈细胞","o":["中性粒细胞","郎格汉斯细胞","浆细胞","网状细胞","嗜酸性粒细胞"],"a":1,"e":"朗格汉斯细胞能捕获抗原、处理成抗原肽-MHC复合物并提呈给T细胞，是表皮内的抗原提呈细胞；浆细胞分泌抗体，不属抗原提呈细胞。"},{"q":"原始卵泡来源于","o":["尿生殖窦","中肾小管","中肾旁管","次级性索","生殖腺嵴"],"a":3,"e":"次级性索即皮质索，由未分化性腺表面上皮增生形成并断裂为细胞团，围绕原始生殖细胞构成原始卵泡；中肾旁管形成输卵管等结构。"},{"q":"生精细胞逐批同步发育的基础是","o":["缝隙连接","桥粒","紧密连接","胞质桥","细胞间桥"],"a":3,"e":"一个精原细胞产生的各级生精细胞胞质未完全分开，以胞质桥相连，使细胞同步发育并共享物质；缝隙连接与桥粒不承担此作用。"},{"q":"淋巴结内的毛细血管后微静脉主要分布于","o":["浅层皮质","副皮质区","淋巴小结","髓窦","髓索"],"a":1,"e":"淋巴结副皮质区含高内皮微静脉即毛细血管后微静脉，是血液淋巴细胞进入淋巴结的主要部位；浅层皮质以淋巴小结为主。"},{"q":"胎儿血液循环中含氧量最高的血液位于","o":["主动脉","肺动脉","肺静脉","脐动脉","脐静脉"],"a":4,"e":"脐静脉运送经母胎交换后的富氧血，含氧量在胎儿血管中最高；脐动脉含氧最低，肺动脉和主动脉居中。"},{"q":"上皮组织的主要结构特点是","o":["细胞多，细胞间质少","有丰富的毛细血管","分为单层、复层两类","感觉神经末梢少见","组成的细胞无序排布"],"a":0,"e":"上皮组织细胞排列紧密、细胞间质少，细胞有极性并附着于基膜，无血管而神经末梢丰富；按层次分单层和复层仅为其形态分类之一。"},{"q":"关于心肌纤维的叙述，错误的是","o":["心肌纤维呈短圆柱状，有分支并互相连接成网","心肌纤维纵切面上可见横纹，但不如骨骼肌的明显","心肌纤维之间有丰富的毛细血管","新生儿心肌纤维内的脂褐素含量更多","闰盘在HE染色的标本中呈着色较深的阶梯状粗线"],"a":3,"e":"脂褐素为溶酶体残余体，随年龄增长而增多，故老年心肌纤维内含量更多，新生儿心肌纤维内含量最少。"},{"q":"脂肪组织主要由大量密集的脂肪细胞构成，根据脂肪细胞结构和功能的不同，脂肪组织分为黄色和棕色脂肪组织。有关黄色脂肪组织的描述，哪一项错误","o":["为通常所说的脂肪组织","在人呈黄色，在某些哺乳动物呈白色","由大量多泡脂肪细胞聚集而成","见于皮下组织、网膜和肠系膜等处","具有储存脂肪和维持体温等作用"],"a":2,"e":"黄色脂肪组织由大量单泡脂肪细胞聚集构成，多泡脂肪细胞是棕色脂肪组织的标志；它主要分布于皮下、网膜和系膜，是体内最大的贮能库，并有维持体温、缓冲保护作用。"},{"q":"下列哪项共同超微结构特点与软骨细胞和成骨细胞合成基质和纤维的功能相适应","o":["粗面内质网丰富，高尔基复合体发达","线粒体和粗面内质网丰富","滑面内质网和管状嵴线粒体丰富","含有较多的溶酶体、吞饮小泡和吞噬体","含有较多的脂滴"],"a":0,"e":"软骨细胞和成骨细胞均需大量合成胶原等蛋白质基质，故含丰富的粗面内质网和发达的高尔基复合体，这是蛋白质分泌细胞的典型超微结构特征。"},{"q":"对于成纤维细胞的描述，哪项不正确","o":["是疏松结缔组织的主要细胞","细胞呈扁平、多突起","细胞核，较大，核仁明显","细胞质较丰富，呈弱嗜酸性","富含粗面内质网和发达的高尔基复合体"],"a":3,"e":"成纤维细胞功能活跃时细胞质较丰富，因含大量粗面内质网而呈弱嗜碱性；呈弱嗜酸性的是功能静止的纤维细胞。"},{"q":"消化吸收的重要部位是","o":["绒毛表面的黏液","微绒毛表面的细胞衣","吸收细胞的细胞内小管","吸收细胞之间的间隙","吸收细胞之间的连接复合体"],"a":1,"e":"小肠上皮微绒毛表面的细胞衣含双糖酶、肽酶及吸附的胰蛋白酶、胰淀粉酶，是食物消化吸收的重要部位，皱襞与绒毛只扩大表面积。"},{"q":"没有细胞核也没有细胞器的是","o":["红细胞","血小板","间充质细胞","脂肪细胞","网织红细胞"],"a":0,"e":"成熟红细胞无细胞核也无任何细胞器，不能合成蛋白质和代谢所需酶类，仅保留血红蛋白；网织红细胞仍残留少量核糖体。"},{"q":"抗利尿激素和醛固酮的作用部位是","o":["近端小管和远端小管","髓袢","远端小管和集合管","髓袢和集合管","近端小管和髓袢"],"a":2,"e":"醛固酮作用于远曲小管和集合管促进保钠排钾，抗利尿激素促进该段重吸收水使尿液浓缩，二者共同调节水盐平衡。"},{"q":"关于浆细胞的描述，哪项正确","o":["细胞形态多样，可伸出突起","细胞核圆形，位于细胞中央","核内异染色质呈辐射状分布","胞质内有丰富的滑面内质网","胞质中充满异染性颗粒"],"a":2,"e":"浆细胞核圆形偏位，异染色质呈粗块状自核中心向核膜辐射状分布；胞质含大量平行排列的粗面内质网，核旁浅染区为发达的高尔基复合体。"},{"q":"下列哪个结构不分布在髓放线内","o":["集合管","近端小管直部","远端小管直部","细段","乳头管"],"a":4,"e":"髓放线内纵行着近端小管直部、细段、远端小管直部和直集合管；乳头管位于肾锥体乳头处，已不属于髓放线。"},{"q":"生精上皮的组成是","o":["支持细胞和生精细胞","肌样细胞和生精细胞","支持细胞，肌样细胞和精原细胞","支持细胞和肌样细胞","生精细胞和间质细胞"],"a":0,"e":"生精上皮由支持细胞和5～8层生精细胞组成，自基底面至腔面依次为精原细胞、初级精母细胞、次级精母细胞、精子细胞和精子。"},{"q":"中肠袢在人胚胎发育演变中共逆时针旋转","o":["90°","120°","180°","270°","360°"],"a":3,"e":"中肠袢以肠系膜上动脉为轴先逆时针旋转90°，退回腹腔过程中再逆时针旋转180°，累计共旋转270°。"},{"q":"不属于角膜特征的是","o":["分角膜上皮、前界层、角膜基质、后界层和角膜内皮5层","富含感觉神经末梢","毛细血管丰富","角膜上皮再生能力强","前界层损伤后不能再生"],"a":2,"e":"角膜无血管，营养靠房水、泪液和角膜缘血管供给，故毛细血管丰富不是其特征；角膜富含感觉神经末梢，上皮再生能力强。"},{"q":"下列哪种神经元不是多极神经元","o":["运动神经元","大脑锥体细胞","中间神经元","脊神经节的节细胞","自主神经节的节细胞"],"a":3,"e":"脊神经节节细胞为假单极神经元，胞体发出一个突起后呈T形分支；运动神经元、锥体细胞、中间神经元及自主神经节细胞均为多极神经元。"},{"q":"关于破骨细胞的结构与功能，下列哪项错误","o":["只溶解骨质而不能吸收骨质","有2～50个核","来源于单核细胞","位于骨质的表面","胞质内含大量溶酶体"],"a":0,"e":"破骨细胞贴附于骨表面，释放水解酶和有机酸溶解骨盐并分解有机成分，再经皱褶缘吞饮吸收，故既有溶骨作用也有吸收骨质的作用。"},{"q":"一个肺小叶的组成是","o":["一个终末细支气管及其分支和肺泡","一个细支气管及其分支和肺泡","一个呼吸性细支气管及其分支和肺泡","一个小支气管及其分支和肺泡","一个主支气管及其分支和肺泡"],"a":1,"e":"肺小叶是指一个细支气管连同它的各级分支及所属肺泡构成的锥形结构，是肺的独立功能单位。"},{"q":"骨基质中的有机质不包括","o":["以羟基磷灰石结晶存在的骨盐","胶原纤维","蛋白聚糖","骨钙蛋白","骨粘连蛋白"],"a":0,"e":"骨基质有机成分包括胶原纤维、蛋白聚糖、骨钙蛋白和骨粘连蛋白；羟基磷灰石结晶属无机成分即骨盐，占干骨重量65%。"},{"q":"球旁细胞由下列哪种成分演变而成","o":["出球微动脉的内皮细胞","入球微动脉的内皮细胞","近曲小管上皮细胞","球外系膜细胞","近血管球处入球微动脉的平滑肌细胞"],"a":4,"e":"球旁细胞由近肾小体血管极处入球微动脉管壁的平滑肌细胞分化为上皮样细胞，胞质含分泌颗粒，可分泌肾素。"},{"q":"关于胆汁正确的是","o":["进食后胆管括约肌收缩利于胆汁在胆囊内的浓缩","交感神经兴奋促使胆囊肌收缩","胆管上皮能通过吸收胆汁中的水和无机盐而浓缩胆汁","胃大部切除患者由于迷走神经兴奋易发生胆石症","Oddi括约肌功能紊乱可导致胰腺炎或肝功能异常"],"a":4,"e":"Oddi括约肌功能紊乱使胆汁排出受阻或反流，可诱发胰腺炎或胆汁淤积性肝功能异常；浓缩胆汁靠胆囊上皮吸收水和无机盐。"},{"q":"胰腺的泡心细胞是一种","o":["内分泌细胞","腺泡细胞","导管的上皮细胞","未分化细胞","从血管渗出的白细胞"],"a":2,"e":"泡心细胞是胰腺闰管起始部上皮细胞伸入腺泡腔内形成，细胞较小、染色浅，属导管上皮细胞，并非腺泡细胞或内分泌细胞。"},{"q":"关于真皮的网织层，正确的是","o":["为致密结缔组织","与表皮相邻接","形成许多真皮乳头以增加与表皮的接触面","含有触觉小体","不含神经末梢器"],"a":0,"e":"真皮网织层由致密结缔组织构成，胶原纤维束粗大交织成网，使皮肤具有韧性和弹性；与表皮相邻并形成真皮乳头的是乳头层。"},{"q":"睾丸间质细胞来源于","o":["生殖腺嵴的间充质","次级性索","初级性索","中肾管","中肾旁管"],"a":0,"e":"睾丸间质细胞由生殖腺嵴表面上皮下的间充质细胞分化而来，第8周出现于睾丸索之间并分泌雄激素；初级性索上皮细胞分化为支持细胞。"},{"q":"在肾内的动脉分布中，发自叶间动脉的是","o":["弓形动脉","直小动脉","入球微动脉","出球微动脉","小叶间动脉"],"a":0,"e":"肾动脉入肾后分为叶间动脉，叶间动脉在肾柱内上行至皮髓质交界处横向分出弓形动脉，弓形动脉再发出小叶间动脉进入皮质迷路。"},{"q":"子宫内膜处于分泌期时，卵巢内","o":["即将排卵","黄体生长","黄体退化","卵泡生长","卵泡成熟"],"a":1,"e":"分泌期为月经周期第15～28天，此时卵泡已排卵，残留卵泡壁发育为黄体并分泌孕激素和雌激素，故此期又称黄体期。"},{"q":"构成粗肌丝的蛋白质是","o":["肌动蛋白","肌球蛋白","肌钙蛋白","原肌球蛋白","肌红蛋白"],"a":1,"e":"粗肌丝由肌球蛋白分子组成，分子尾对尾排列、头部外露形成横桥；肌动蛋白、原肌球蛋白和肌钙蛋白共同构成细肌丝。"},{"q":"周围神经系统神经纤维的神经膜细胞是指","o":["星形胶质细胞","少突胶质细胞","小胶质细胞","施万细胞","卫星细胞"],"a":3,"e":"周围神经纤维的神经膜细胞即施万细胞，形成节段性髓鞘与神经膜；星形胶质细胞、少突胶质细胞和小胶质细胞均属中枢神经胶质细胞。"},{"q":"单核细胞","o":["发生过程中与中性粒细胞源自同一造血祖细胞","数量少于任何一种有粒白细胞","穿出血管后具有变形运动和趋化性","吞噬作用和免疫功能较巨噬细胞弱","胞质内只含有大量溶酶体"],"a":3,"e":"官方题库缺失图片"},{"q":"关于虹膜的描述，哪项错误","o":["为环形板状薄膜","虹膜基质含黑素细胞","虹膜不含血管和神经","虹膜上皮为视网膜盲部","瞳孔开大肌由上皮特化而成"],"a":2,"e":"虹膜基质为富含血管和黑素细胞的疏松结缔组织，虹膜内血管、神经丰富；虹膜上皮属视网膜盲部，瞳孔开大肌由上皮特化而成。"},{"q":"具有屏障作用的细胞连接是","o":["桥粒","缝隙连接","中间连接","紧密连接","通讯连接"],"a":3,"e":"紧密连接位于相邻细胞间隙顶部，跨膜蛋白颗粒互相吻合成网封闭细胞间隙，具有屏障作用；桥粒和中间连接主要起机械连接作用。"},{"q":"关于胰腺腺泡细胞的结构特征，正确的是","o":["细胞为圆形","有丰富的滑面内质网","细胞基底部有许多酶原颗粒","基部胞质嗜碱性","核圆，位于细胞中央"],"a":3,"e":"胰腺腺泡细胞基底部富含粗面内质网，故基部胞质呈强嗜碱性，酶原颗粒集中于核上区顶部；细胞呈锥体形，核圆而偏于基底部。"},{"q":"精子形成是指","o":["精子细胞经过复杂的形态变化形成精子的过程","从精原细胞发育成精子的过程","从初级精母细胞至精子形成的过程","生精细胞的两次成熟分裂","精子形成以后到受精的过程"],"a":0,"e":"精子形成指精子细胞不再分裂，经复杂变态由圆形转变为蝌蚪状精子的过程，包括核浓缩、顶体形成、多余胞质脱落和鞭毛形成。"},{"q":"排卵发生在月经周期的","o":["月经期","增生早期","分泌期中期","分泌期晚期","增生期末"],"a":4,"e":"排卵发生在月经周期第14天左右，此时子宫内膜正处于增生期末，即将转入分泌期，排卵后残留卵泡壁形成黄体。"},{"q":"关于壶腹嵴的结构和功能，哪项错误","o":["位于膜半规管的壶腹内","由支持细胞、毛细胞和壶腹帽构成","毛细胞顶部有许多静纤毛","壶腹帽的糖蛋白由毛细胞分泌","感受头部旋转运动的开始和终止"],"a":3,"e":"壶腹帽的圆锥形糖蛋白胶质由支持细胞分泌，毛细胞仅将动、静纤毛插入其基部；壶腹嵴感受头部旋转变速运动。"},{"q":"关于透明软骨的叙述，错误的是","o":["它是体内分布最广的一类软骨","细胞间质内无纤维","软骨细胞存在间质中的软骨陷窝内","其新鲜标本呈淡蓝色半透明状","基质染色嗜碱性"],"a":1,"e":"透明软骨基质含大量极细的Ⅱ型胶原原纤维并交织成三维网架，并非无纤维；因纤维折光率与基质接近，光镜下不能分辨。"},{"q":"以下哪项不是箭头所指细胞的特征","o":["能够吞噬异物及自身衰老细胞","能够分泌抗体","细胞膜表面表达有MHCⅠ类及MHCⅡ类分子","分布广泛，淋巴组织内常见","具有抗原呈递能力"],"a":1,"e":"官方题库缺失图片"},{"q":"增生隆起最后形成耳廓的是","o":["第Ⅰ鳃沟周围的间充质","第Ⅱ鳃沟周围的间充质","第Ⅲ鳃沟周围的间充质","第Ⅳ鳃沟周围的问充质","第Ⅰ咽囊周围的间充质"],"a":0,"e":"第6周第Ⅰ鳃沟周围的间充质增生形成6个耳丘，围绕外耳道口演变为耳郭；外耳道则由第Ⅰ鳃沟本身演变而成。"},{"q":"关于位觉斑，哪项错误","o":["呈圆斑状隆起","毛细胞顶端有许多动纤毛","毛细胞夹在支持细胞之间","位砂膜内有位砂沉着","位于球囊和椭圆囊内"],"a":1,"e":"位觉斑毛细胞顶部有40～80根静纤毛和1根动纤毛，静纤毛呈阶梯状排列；位砂膜内含位砂，感受直线变速运动和静止状态。"},{"q":"HE染色的透明软骨切片中看不到纤维的原因是","o":["软骨组织不含纤维","纤维在HE染色中不着色","纤维与基质的折光率相同","纤维密集排列","纤维平行排列"],"a":2,"e":"透明软骨的胶原原纤维极细，直径仅10～20nm，且折光率与基质接近，故HE染色切片中不能分辨，并非基质内不含纤维。"},{"q":"与伴行动脉相比，关于静脉的描述，以下哪项是错误的","o":["管腔大、管壁薄","可有瓣膜","外膜中的滋养血管较少","外膜中可有纵行平滑肌束","内弹性膜不明显"],"a":2,"e":"静脉外膜最厚，含丰富的滋养血管和神经，故滋养血管较少一说不成立；静脉管壁薄、腔大，内弹性膜不发达，可有静脉瓣。"},{"q":"属于单核吞噬细胞系统的细胞是","o":["少突胶质细胞","星形胶质细胞","小胶质细胞","施万细胞","卫星细胞"],"a":2,"e":"小胶质细胞由血液单核细胞迁入神经组织演化而成，属单核吞噬细胞系统，损伤时可转变为巨噬细胞；少突胶质、星形胶质和施万细胞不属该系统。"},{"q":"关于肾小体的特征描述，下列哪项错误","o":["由血管球及肾小囊组成","可分为血管极和尿极","尿极与远端小管曲部相连","血管极有入球和出球微动脉出入","致密斑位于血管极两条微动脉之间"],"a":2,"e":"肾小体尿极与近端小管曲部相连，血管极有入球、出球微动脉出入，致密斑位于血管极两条微动脉之间。"},{"q":"关于睾丸支持细胞的功能，哪项是错误的","o":["构成血-睾屏障","能吞噬精子形成时丢失的胞质","为生精细胞提供营养","能合成和分泌雄激素，促进精子发生","分泌少量液体有利于精子的输送"],"a":3,"e":"雄激素由睾丸间质细胞合成和分泌；支持细胞在卵泡刺激素和雄激素作用下分泌雄激素结合蛋白，维持生精小管内高水平雄激素以促进精子发生。"},{"q":"在脑的发生过程中，菱脑泡的腔演变为","o":["第三脑室","中脑水管","侧脑室","侧脑室和第三脑室","第四脑室"],"a":4,"e":"菱脑泡的腔演变为宽大的第四脑室；前脑泡的腔形成侧脑室和第三脑室，中脑泡的腔形成狭窄的中脑水管。"},{"q":"胎盘的组成是","o":["基蜕膜和平滑绒毛膜","壁蜕膜和丛密绒毛膜","壁蜕膜和平滑绒毛膜","包蜕膜和丛密绒毛膜","丛密绒毛膜和基蜕膜"],"a":4,"e":"胎盘由胎儿的丛密绒毛膜与母体基蜕膜共同构成；丛密绒毛膜血供充足、绒毛反复分支，平滑绒毛膜与包蜕膜不参与胎盘形成。"},{"q":"关于疏松结缔组织的特点，哪项错误","o":["细胞少，细胞外基质多","细胞外基质包括纤维和基质","细胞有极性，分布于细胞外基质内","基质的化学成分主要是蛋白聚糖","蛋白聚糖聚集形成有许多微孔的分子筛"],"a":2,"e":"疏松结缔组织的细胞散在分布于细胞外基质中，无极性，这是与上皮组织的重要区别；基质主要成分为蛋白聚糖，形成多微孔的分子筛。"},{"q":"心肌纤维闰盘的横位部分位于","o":["M线水平","A带水平","A带与l带交界处","I带水平","Z线水平"],"a":4,"e":"闰盘的横向部分位于Z线水平，含黏着小带与桥粒使心肌纤维连接牢固；其纵向部分位于相邻心肌纤维侧面，有缝隙连接。"},{"q":"关于肾的球外系膜细胞，描述正确的是","o":["位于肾小体血管极处，与球内系膜细胞相延续","位于肾小体血管极处，与足细胞相延续","位于肾小体尿极处，与球内系膜细胞相延续","位于肾小体尿极处，与肾小囊壁层相延续","位于肾小体血管极处，与肾小囊壁层相延续"],"a":0,"e":"球外系膜细胞位于肾小体血管极，与球内系膜相延续，形态结构也相似，并与球旁细胞、球内系膜细胞之间有缝隙连接。"},{"q":"成熟女性的月经周期一般为","o":["7天","14天","28天","35天","60天"],"a":2,"e":"月经周期指自青春期起子宫内膜在卵巢激素作用下，每28天左右发生一次剥脱、出血、修复和增生的周期性变化。"},{"q":"关于胸腺，哪项错误","o":["是培育T细胞的中枢淋巴器官","胸腺细胞增殖分化成T细胞","与皮质相比，髓质内的T细胞较少","胸腺小体仅分布于髓质","胸腺小体由胸腺细胞呈同心圆排列而成"],"a":4,"e":"胸腺小体位于髓质，由胸腺上皮细胞呈同心圆排列并角化形成，是胸腺的特征性结构；胸腺细胞是处于不同发育阶段的T细胞。"},{"q":"关于阑尾的描述哪项正确","o":["有少量的绒毛，肠腺少而短，有丰富的淋巴组织","有少量的绒毛，肠腺少而短，杯状细胞较少，有丰富的淋巴组织","无绒毛，肠腺少而短，杯状细胞较多，有丰富的淋巴组织，肌层薄","无绒毛，肠腺少而短，黏膜肌完整，有丰富的淋巴组织，肌层薄","无绒毛，肠腺少而短，黏膜肌不完整，有丰富的淋巴组织，肌层薄"],"a":4,"e":"阑尾腔小，无绒毛，肠腺少而短，固有层淋巴组织丰富致使黏膜肌不完整，肌层薄，故易发生穿孔。"},{"q":"对远端小管继续吸收水和钠离子有调节作用的是","o":["雌激素","胰岛素","甲状腺素","醛固酮","黄体酮"],"a":3,"e":"醛固酮作用于远曲小管和集合管，促进重吸收Na+并排出K+，是调节该段水钠重吸收的主要激素。"},{"q":"关于软骨的叙述，哪项正确","o":["富含钙离子","三种软骨均含纤维","羟基磷灰石结晶比骨组织少","对长骨的生长作用甚微","基质中埋藏有成软骨细胞"],"a":1,"e":"透明软骨、弹性软骨和纤维软骨的基质中均含纤维，仅纤维类型和含量不同；软骨基质中钙盐沉积远少于骨组织。"},{"q":"胆道堵塞内压增大时出现","o":["胆汁通过肝板上的孔流入中央静脉","胆汁通过肝板上的孔流入肝血窦","胆汁通过闰管流入肝血窦","胆汁通过胆小管周围破坏的细胞连接进入肝血窦","胆汁通过胆小管周围破坏的细胞连接进入中央静脉"],"a":3,"e":"胆道堵塞致内压升高时，胆小管周围的连接复合体被破坏，胆汁溢入窦周隙继而进入肝血窦，临床出现黄疸。"},{"q":"胞质内有异染性颗粒的细胞","o":["成纤维细胞","浆细胞","肥大细胞","巨噬细胞","纤维细胞"],"a":2,"e":"肥大细胞胞质充满粗大的异染性颗粒，内含肝素、组胺和嗜酸性粒细胞趋化因子，参与过敏反应，颗粒呈异染性。"},{"q":"患寄生虫感染时，血液中何种白细胞增高","o":["中性粒细胞","嗜酸性粒细胞","嗜碱性粒细胞","单核细胞","淋巴细胞"],"a":1,"e":"嗜酸性粒细胞释放的阳离子蛋白对寄生虫有很强的杀灭作用，故寄生虫病及过敏性疾病时血液中嗜酸性粒细胞增多。"},{"q":"原始消化管管壁的构成是","o":["内胚层和体壁中胚层","内胚层","外胚层和脏壁中胚层","脏壁中胚层","内胚层和脏壁中胚层"],"a":4,"e":"原始消化管由内胚层上皮与其外侧的脏壁中胚层共同构成，后者分化为消化、呼吸系统的肌组织、结缔组织和血管等。"},{"q":"肌质网的膜上有钙泵蛋白，它可以","o":["调节线粒体内的Na＋浓度","调节肌浆中的Ca2＋浓度","抑制兴奋传递","是一种ATP酶，可与肌动蛋白接触","抑制横桥发生屈伸运动"],"a":1,"e":"肌质网膜上的钙泵是一种ATP酶，能逆浓度差把肌浆中的Ca2+泵入肌质网内贮存，从而降低肌浆Ca2+浓度引起肌舒张。"},{"q":"内分泌细胞数量和种类最多的内分泌器官是","o":["脑垂体","肾上腺","消化道","甲状腺","松果体"],"a":2,"e":"消化管黏膜面积巨大，其上皮及腺体内散布40余种内分泌细胞，总量超过其他内分泌腺，是内分泌细胞数量和种类最多的部位。"},{"q":"圈中结构为","o":["弥散淋巴组织","初级淋巴小结","次级淋巴小结","胸腺小体","脾小体"],"a":2,"e":"官方题库缺失图片"},{"q":"以下关于环层小体的描述，哪项正确","o":["分布于皮肤真皮乳头内","感受压觉和振动觉","圆形，与触觉小体大小相似","有髓神经纤维穿行于中央","薄层结缔组织组成被囊"],"a":1,"e":"环层小体位于真皮深层和皮下组织，体积大，被囊由数十层同心圆排列的结缔组织和扁平细胞构成，感受较强应力，参与产生压觉和振动觉。"},{"q":"构成神经组织的基本成分是","o":["神经元和神经纤维","神经元和神经丝","神经元和神经胶质细胞","神经元和神经末梢","神经元和神经"],"a":2,"e":"神经组织由神经元和神经胶质细胞构成，神经元是神经系统的结构和功能单位，神经胶质细胞起支持、营养、绝缘和保护作用。"},{"q":"关于脾血窦的描述哪项错误","o":["窦壁的内皮细胞呈扁平状","内皮细胞处基膜不完整","窦周围有许多巨噬细胞","内皮细胞之间有较明显的间隙","形状不规则，位于红髓的脾索之间"],"a":0,"e":"脾血窦窦壁由长杆状内皮细胞纵向排列而成，细胞间有明显间隙，基膜不完整，窦外有大量巨噬细胞，血窦位于脾索之间。"},{"q":"关于Ⅱ型肺泡细胞，哪项错误","o":["是一种立方或圆形的细胞","含板层小体","板层小体是分泌颗粒，含磷脂","可由Ⅰ型肺泡细胞分化而来","可分化为Ⅰ型肺泡细胞"],"a":3,"e":"Ⅱ型肺泡细胞呈立方或圆形，含板层小体并分泌表面活性物质；它可增殖分化为Ⅰ型肺泡细胞，而不能由Ⅰ型肺泡细胞分化而来。"},{"q":"放射冠细胞是","o":["初级卵母细胞","次级卵母细胞","卵原细胞","成熟卵细胞","卵泡细胞"],"a":4,"e":"放射冠是紧贴透明带的一层高柱状卵泡细胞，呈放射状排列，其本质是卵泡细胞而非卵母细胞。"},{"q":"垂体细胞是","o":["嫌色细胞","神经内分泌细胞","神经胶质细胞","神经元","特化的成纤维细胞"],"a":2,"e":"垂体细胞是神经垂体中的神经胶质细胞，形态不规则，对神经纤维起支持、营养作用并参与激素运输，并非神经元或内分泌细胞。"},{"q":"关于深层皮质单位的描述，哪项错误","o":["细胞免疫功能活跃时，此区明显扩大","是一片弥散淋巴组织","位于淋巴小结与髓质之间","含有毛细血管后微静脉","是B细胞聚集处"],"a":4,"e":"深层皮质单位即副皮质区，为弥散淋巴组织，位于淋巴小结与髓质之间，含毛细血管后微静脉，是胸腺依赖区，以T细胞为主。"},{"q":"血细胞最早出现的部位是","o":["卵黄囊血岛","骨髓","肝","淋巴结","脾"],"a":0,"e":"人胚第3周卵黄囊壁的血岛最早造血，其后肝、脾、骨髓相继造血，出生后红骨髓成为终身造血的主要器官。"},{"q":"能进行物质交换的主要血管是","o":["微动脉","中间微动脉","真毛细血管","直捷通路","小动脉"],"a":2,"e":"真毛细血管壁仅由内皮和基膜构成，血流缓慢，是血液与组织进行物质交换的主要部位；直捷通路和微动脉主要起分流与调节作用。"},{"q":"视近物时，晶状体曲度增大是由于","o":["睫状肌收缩，睫状小带紧张","睫状肌舒张，睫状小带紧张","睫状肌收缩，睫状小带松弛","睫状肌舒张，睫状小带松弛","与睫状肌和睫状小带无关"],"a":2,"e":"视近物时睫状肌收缩，睫状体向前内侧移位，睫状小带松弛，晶状体靠自身弹性变凸、曲度增大，折光力增强。"},{"q":"中胚层自中轴向外侧依次为","o":["间介中胚层、轴旁中胚层、侧中胚层","轴旁中胚层、侧中胚层、间介中胚层","轴旁中胚层、间介中胚层、侧中胚层","侧中胚层、间介中胚层、轴旁中胚层","侧中胚层、轴旁中胚层、间介中胚层"],"a":2,"e":"中胚层由中轴向外侧依次分化为轴旁中胚层、间介中胚层和侧中胚层，轴旁中胚层随即分节形成体节。"},{"q":"肌节","o":["1个明带＋1个暗带","位于M线与Z线之间","位于相邻两条Z线之间","位于相邻两条M线之间","1/2暗带＋明带＋1/2暗带"],"a":2,"e":"肌节是相邻两条Z线之间的一段肌原纤维，由1/2 I带＋A带＋1/2 I带构成，是骨骼肌纤维结构和功能的基本单位。"},{"q":"胰腺中哪种细胞退化可引起糖尿病","o":["A细胞","B细胞","D细胞","PP细胞","浆液性腺细胞"],"a":1,"e":"胰岛B细胞分泌胰岛素，其退化或功能低下使胰岛素分泌不足，血糖升高并从尿中排出，即形成糖尿病。"},{"q":"淋巴结内发生体液免疫应答的主要变化是","o":["浅层皮质变小","髓质增大","初级淋巴小结增多增大","次级淋巴小结增多增大","副皮质区增厚"],"a":3,"e":"体液免疫应答时，B细胞在浅层皮质受抗原刺激后增殖分化，次级淋巴小结增多增大、髓索内浆细胞增多，是体液免疫活跃的标志。"},{"q":"可对原尿进行重吸收的部位是","o":["肾小囊和肾小管","肾小体和肾小管","肾小管和集合管","肾小体和肾小囊","集合管"],"a":2,"e":"肾小体滤出的原尿流经肾小管和集合管时，绝大部分水、营养物质和无机盐被重吸收入血，故重吸收部位是肾小管和集合管。"},{"q":"神经垂体来源于","o":["间脑底部的神经外胚层","端脑底部的神经外胚层","中脑底部的神经外胚层","后脑底部的神经外胚层","末脑底部的神经外胚层"],"a":0,"e":"神经垂体由间脑底部的神经外胚层向腹侧突出形成的神经垂体芽演变而来，腺垂体则起源于口凹表面外胚层形成的拉特克囊。"},{"q":"食管的组织结构特点不包括","o":["黏膜上皮为复层扁平上皮","上、下端固有层可有少许黏液性腺","黏膜下层含食管腺","肌层为纵行的平滑肌","外膜为纤维膜"],"a":3,"e":"食管肌层为内环行、外纵行两层，上1/3为骨骼肌、中1/3混合、下1/3为平滑肌，故纵行平滑肌的表述错误；外膜为纤维膜。"},{"q":"食管及胃的上皮分别为","o":["单层扁平上皮及复层扁平上皮","复层扁平上皮及复层柱状上皮","复层扁平上皮及单层柱状上皮","单层柱状上皮及变移上皮","单层扁平上皮及变移上皮"],"a":2,"e":"食管黏膜上皮为未角化的复层扁平上皮，胃黏膜上皮为单层柱状上皮，二者在贲门处骤然相接。"},{"q":"小肠是消化吸收主要场所，下列哪组结构有助于扩大小肠的表面积","o":["纵行皱襞、小肠绒毛和微绒毛","环行皱襞、小肠绒毛和杯状细胞","环行皱襞、小肠绒毛和纹状缘","纵行皱襞、小肠绒毛和吸收细胞","环行皱襞、小肠腺和小肠绒毛"],"a":2,"e":"小肠的环行皱襞、绒毛和微绒毛（光镜下即纹状缘）三级结构逐级扩大表面积，使吸收面积扩大约600倍。"},{"q":"具有吞噬功能的神经胶质细胞是","o":["少突胶质细胞","室管膜细胞","星形胶质细胞","小胶质细胞","卫星细胞"],"a":3,"e":"小胶质细胞由单核细胞迁入中枢神经系统后演化而成，具有吞噬功能，神经损伤时转变为巨噬细胞清除死亡细胞碎屑。"},{"q":"以下关于骨骼肌纤维超微结构的描述，哪项是错误的","o":["每条肌原纤维由更细的肌丝构成","肌丝分粗肌丝、细肌丝两种","横小管位于Z线水平","肌浆网在靠近横小管处膨大形成终池","横小管和两侧终池组成三联体"],"a":2,"e":"骨骼肌横小管位于明、暗带交界处，心肌横小管才位于Z线水平；骨骼肌横小管与其两侧终池共同组成三联体。"},{"q":"心脏传导系统的细胞实际上是","o":["感觉上皮细胞","特殊的心肌细胞","特殊的神经细胞","特殊的运动神经元","结缔组织细胞"],"a":1,"e":"心脏传导系统由特殊心肌纤维构成，包括窦房结、房室结、房室束及浦肯野纤维，能产生并传导动作电位，并非神经细胞。"},{"q":"关于静脉的结构特点，哪项是错误的","o":["3层膜界限清楚","管壁较薄而管腔较大","内弹性膜不发达或缺如","中膜薄，平滑肌稀疏","外膜较厚"],"a":0,"e":"静脉无明显内、外弹性膜，中膜薄、外膜厚，故3层膜界限不清；其管壁薄而腔大，内弹性膜不发达，外膜可有纵行平滑肌束。"},{"q":"对视锥细胞的描述，错误的是","o":["细胞核较大，染色较浅","外节膜盘与细胞膜分离，顶部膜盘不断脱落","细胞分3类，分别含红敏视色素、蓝敏视色素和绿敏视色素","缺少含红（绿）敏视色素的视锥细胞会引起红绿色盲","黄斑中央凹处只有视锥细胞"],"a":1,"e":"视杆细胞外节的膜盘与细胞膜分离，顶部膜盘不断脱落并由色素上皮细胞吞噬；视锥细胞的膜盘则与细胞膜相连，不脱落。"},{"q":"系膜增生性肾炎和膜增生性肾炎都有光镜下系膜增生的表现，关于球内系膜（血管系膜）的描述，下列哪项是错误的","o":["由球内系膜细胞和基质组成","球内系膜细胞有突起伸到内皮细胞与基膜间，但决不能到达毛细血管腔内","系膜细胞的胞质内可含有中间丝","目前认为球内系膜细胞为特化的平滑肌细胞","球内系膜细胞有合成、分泌和吞噬作用及收缩能力"],"a":1,"e":"球内系膜细胞的突起可伸入内皮细胞与基膜之间，甚至突入毛细血管腔，故决不能到达腔内一说不成立；该细胞兼具收缩、吞噬和分泌功能。"},{"q":"关于淋巴结，哪项错误","o":["被膜中有输入淋巴管","T细胞主要分布在皮质浅层","髓窦中有巨噬细胞","能过滤淋巴","是免疫应答的场所"],"a":1,"e":"淋巴结的T细胞主要分布于副皮质区即深层皮质，皮质浅层的淋巴小结以B细胞为主；输入淋巴管经被膜下窦进入淋巴结。"},{"q":"中央前回的大脑皮质中哪层较发达","o":["分子层","外颗粒层","外锥体细胞层和内颗粒层","内锥体细胞层","多形细胞层"],"a":3,"e":"中央前回为躯体运动中枢，其内锥体细胞层含大量大、中型锥体细胞，轴突组成皮质脊髓束等下行投射纤维，故该层最发达。"},{"q":"早期晶状体泡由单层上皮组成","o":["其前壁细胞呈立方形，后壁细胞呈高柱状","其前壁细胞呈高柱状，后壁细胞呈立方形","其前壁为单层立方，后壁为假复层柱状","其前壁为单层扁平，后壁为假复层柱状","其前壁为单层扁平，后壁为单层立方"],"a":0,"e":"晶状体泡前壁细胞呈立方形，分化为晶状体上皮；后壁细胞呈高柱状，逐渐向前壁伸长形成初级晶状体纤维。"},{"q":"在内分泌腺中，常见腺细胞排列成滤泡状的结构是","o":["肾上腺皮质和髓质","腺垂体结节部和中间部","甲状腺和腺垂体中间部","甲状腺和甲状旁腺","肾上腺髓质和神经垂体"],"a":2,"e":"甲状腺滤泡和腺垂体中间部的腺细胞均围成滤泡状，滤泡腔内分别含胶质和胶体；肾上腺与甲状旁腺的腺细胞多排列成索或团。"},{"q":"回肠憩室的成因是","o":["卵黄囊未退化，残留一指状盲囊","卵黄蒂近端退化不全，残留一指状盲囊","尿囊未退化，残留一指状盲囊","尿囊基部未退化，残留一指状盲囊","脐腔未闭锁"],"a":1,"e":"回肠憩室又称梅克尔憩室，由卵黄蒂近端退化不全残留形成，位于回肠壁上距回盲部40～50cm处，呈指状盲囊。"},{"q":"感冒时，鼻呼吸部黏膜肿胀、通气不畅的主要原因是","o":["固有层深层动脉壁平滑肌收缩，使浅层毛细血管充血肿胀","固有层深层淋巴管平滑肌收缩，使浅层毛细淋巴管充满淋巴液肿胀","固有层深层静脉壁平滑肌收缩，使浅层静脉丛充血肿胀","固有层深层平滑肌收缩，使浅层海绵组织充满组织液肿胀","鼻腺分泌物刺激所致"],"a":2,"e":"鼻黏膜呼吸部固有层富含静脉丛，感冒时黏膜充血肿胀压迫气道致通气不畅，起关键作用的结构是静脉丛而非毛细血管。"},{"q":"未分化生殖腺的初级性索发生于","o":["卵黄囊胚外内胚层","尿囊内胚层","生殖腺嵴表面上皮","次级性索","卵黄囊胚外中胚层"],"a":2,"e":"未分化期第5周，生殖腺嵴表面的体腔上皮细胞增生并伸入下方间充质，形成许多不规则的细胞索条即初级性索。"},{"q":"基膜的特点不包括","o":["位于上皮组织和结缔组织之间","PAS反应阳性","电镜下可见有透明板、基板和网板","化学成分主要为糖蛋白和蛋白聚糖","是一种半透膜"],"a":2,"e":"电镜下基膜仅分基板和网板两部分，并无透明板；基膜PAS反应阳性，化学成分主要为糖蛋白和蛋白聚糖。"},{"q":"结缔组织中的可以合成分泌胶原蛋白的细胞是","o":["间充质细胞","纤维细胞","成纤维细胞","浆细胞","组织细胞"],"a":2,"e":"成纤维细胞合成并分泌胶原蛋白和弹性蛋白，在细胞外聚合成胶原原纤维；纤维细胞功能静止，合成能力弱。"},{"q":"房间隔缺损主要为卵圆孔未闭，成因中不包括","o":["卵圆孔瓣上有许多穿孔","第一房间隔在形成第二房间孔时吸收过多，导致卵圆孔瓣太小","第二房间隔发育异常，形成过大的卵圆孔","心内膜垫发育异常","主动脉肺动脉隔偏位"],"a":4,"e":"房间隔缺损多因卵圆孔瓣穿孔、第一房间隔吸收过多致卵圆孔瓣过小，或第二房间隔发育异常使卵圆孔过大；主动脉肺动脉隔偏位引起的是动脉干分隔异常。"},{"q":"关于次级卵泡的叙述，哪项错误","o":["内含一个次级卵母细胞","卵泡细胞间有空隙或存在卵泡腔","卵泡膜分内外两层","放射冠由一层柱状卵泡细胞形成","卵泡细胞层数增至6～12层"],"a":0,"e":"次级卵泡内含初级卵母细胞，次级卵母细胞在排卵前完成第一次减数分裂才形成；卵泡腔、卵泡膜分层和放射冠均为该期特点。"},{"q":"由B淋巴细胞分裂、分化的细胞是","o":["树突细胞","巨噬细胞","网状细胞","浆细胞","T淋巴细胞"],"a":3,"e":"B淋巴细胞受抗原刺激后增殖分化为浆细胞，浆细胞分泌抗体；树突细胞、巨噬细胞和网状细胞均非B细胞来源。"},{"q":"电镜观察骨骼肌纤维，只有粗肌丝而无细肌丝的是","o":["I带","H带","A带","A带和H带","I带和H带"],"a":1,"e":"H带仅有粗肌丝，明带即I带仅有细肌丝，H带两侧的暗带由粗、细两种肌丝共同构成，故只含粗肌丝的区域是H带。"},{"q":"视网膜最敏锐的视觉部位是","o":["视网膜中部","视网膜周边部","黄斑","中央凹","视盘"],"a":3,"e":"中央凹处视网膜最薄，仅有色素上皮细胞和视锥细胞，视锥细胞与双极细胞、节细胞一对一联系，故视觉最敏锐。"},{"q":"胃底腺主细胞的超微结构特点是","o":["大量滑面内质网及酶原颗粒","大量粗面内质网及酶原颗粒","大量线粒体及酶原颗粒","大量粗面内质网，无酶原颗粒","高尔基复合体发达，无酶原颗粒"],"a":1,"e":"胃底腺主细胞基底部富含粗面内质网，核上区含大量酶原颗粒，分泌胃蛋白酶原，属典型的蛋白质分泌细胞。"},{"q":"男性进入青春期后，激发第二性征的发育，和男性第二性征直接相关的激素是","o":["卵泡刺激素","黄体生成素","醛固酮","雄激素","糖皮质激素"],"a":3,"e":"雄激素由睾丸间质细胞分泌，可启动并维持精子发生，促进附属性腺发育和男性第二性征出现；FSH、LH通过调节间质细胞与支持细胞间接起作用。"},{"q":"晶状体核来自","o":["晶状体泡的前壁上皮","晶状体泡的后壁上皮","初级晶状体纤维及其胞核","次级级晶状体纤维及其胞核","次级级晶状体纤维"],"a":2,"e":"初级晶状体纤维及其胞核逐渐退化形成晶状体核；次级晶状体纤维由赤道部上皮细胞不断增生形成，逐层添加于核周围。"},{"q":"微小病变性肾小球病时可见足细胞损伤，以下关于足细胞的正确描述是","o":["是肾小球内的内皮细胞","是肾小囊壁层上皮细胞","是肾小囊脏层上皮细胞","是球旁细胞","是球内系膜细胞"],"a":2,"e":"足细胞是肾小囊脏层上皮细胞，胞体发出初级和次级突起贴附于基膜外面，参与构成肾小体滤过屏障。"},{"q":"宫内节育器避孕的原理为","o":["杀死卵子","杀死受精卵","阻止精卵相遇","抑制胚胎发育","影响着床"],"a":4,"e":"宫内节育器主要引起子宫内膜无菌性炎症反应，改变宫腔内环境，干扰受精卵着床，并非杀灭精子、卵子或受精卵。"},{"q":"在心房间隔上的卵圆孔是","o":["在第二房间隔上，位于第二房间隔的上端，左侧被第一房间隔覆盖","在第一房间隔上，位于第二房间孔的下端，右侧被第一房间隔覆盖","在第二房间隔上，位于第二房间孔的上端，右侧被第一房间隔覆盖","在第二房间隔上，位于第二房间孔的下端，右侧被第一房间隔覆盖","在第二房间隔上，位于第二房间孔的下端，左侧被第一房间隔覆盖"],"a":4,"e":"卵圆孔位于第二房间隔下缘，位置较第二房间孔稍低，两孔交错重叠，其左侧由薄而软的第一房间隔即卵圆孔瓣覆盖。"},{"q":"关于玻璃体的描述，哪项错误","o":["为无色透明的胶状体","有支撑视网膜的作用","有屈光作用","损伤后可以再生","有一些透明细胞"],"a":3,"e":"玻璃体为无色透明的胶状体，含少量透明细胞和胶原原纤维，有屈光和支撑视网膜作用，损伤后不能再生，缺损由房水填充。"},{"q":"关于骨和软骨的共同特征，下列哪项错误","o":["都能以间质生长方式生长","骨细胞与软骨细胞都位于陷窝内","细胞间质含有基质和纤维","软骨膜和骨膜都是致密结缔组织","软骨细胞与骨细胞都来源于骨祖细胞"],"a":0,"e":"骨只能以膜内成骨和软骨内成骨方式发生，不能间质生长；软骨则可间质生长和附加性生长，故二者并非都能间质生长。"},{"q":"T淋巴细胞","o":["在胸腺内分化发育而成","在骨髓内分化发育而成","分布于淋巴小结和脾小体","与体液免疫有关","不能进行淋巴细胞再循环"],"a":0,"e":"T淋巴细胞由淋巴干细胞经血液循环迁入胸腺，在胸腺上皮细胞及胸腺素作用下增殖分化为胸腺细胞，最终发育为成熟T细胞。"}];
